/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250415-8","meetingId":"r07-cm04","date":"2025年4月15日","dateIso":"2025-04-15","committee":"建設委員会","time":"午後 １時００分～午後 ４時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年請願第７号、戸越公園駅北地区再開発計画の見直しを求める請願","agenda":"令和７年請願第７号、戸越公園駅北地区再開発計画の見直しを求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、戸越公園駅の北地区の再開発計画の見直しを求める請願ということで出されました。併せて、それに対する意見書の提出もあったと思うのですけれども、この意見の数と、その内容を伺えればと思います。それと併せて、前回の１月に行った第１６条の説明会で、その他とされた意見があったと思うのですけれども、その内容が分かれば少し紹介いただきたいのと、その賛否についても伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"３点のご質問をいただきました。３月に行われた都市計画法第１７条に関する説明会ですが、こちらは３月１６日、１７日と２日間にわたり開催させていただきまして、参加者は合計で１５２名となっています。","voiceIndex":23,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"今回の説明会への参加者が１５２名ということ。そして、その他の意見でも反対に近い声が多かったということで、こうした反対意見など、いろいろ指摘があったと思うのですけれども、こうしたことはどのように反映されているのか、３月の説明会では、計画案に何も変更がないまま説明が行われているという状況ですけれども、どのように反映されているのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、反対の意見があることも区としては受け止めておりまして、今後も地域の声に耳を傾け丁寧に対応してまいりたいと考えているところです。","voiceIndex":25,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"住民の方が考えて、区が必要な計画だと判断したということですけれども、なぜ必要な計画だと判断したのでしょうか。防災やにぎわいという話もありましたけれども、その点について伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"こうした課題解決に寄与するとともに、商店街のにぎわいの維持増進を図り、多様な世代が住み続けられる居住環境を確保するためには、今回の都市計画案は必要なものと考えているところです。","voiceIndex":27,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"課題解決に必要だというお話なのですけれども、この課題を解決するために超高層にしなくてはならない理由はあるのでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"一部繰り返しになりますが、ビジョン等では、多様な世代が住み続けられる地域生活拠点の核となる地区といたしまして、高度利用を図った都市型住宅を整備する、幅広い年代の定住人口を確保するというところがありますので、そういった点を踏まえますと。","voiceIndex":29,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"多様な世代が住めるように高層化が必要だというお話ですけれども、説明会の中でも意見がありましたけれども、もう既に駅前の１９番地、２３階建ての計画ができている、建設が終わって居住もされているという中で、人口の偏りがもう解消されているという声が区民から出されていましたけれども、区はその点をどうお考えなのでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"説明会で人口の偏りが解消されたのではないかというところでご意見は賜ったところですけれども、北地区といたしましても、準備組合のほうでは人口の調査をしておりまして、やはり一定、高齢者層の方の世代に偏りがあるというところが課題として掲げられているところです。","voiceIndex":31,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"ビジョンに位置づけているということで、区民の批判の声を無視してどんどん進めていくというのは、やめるべきだと思います。人口も調査をして偏りがあるというお話でしたけれども、その人口調査はいつ行ったのでしょうか。この１９番地ができてから行ったのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"先ほども申しましたが、人口の調査は準備組合のほうで行っているものでございまして、区といたしましては、そちらのデータも含めまして、まちづくりビジョンに位置づけられている拠点をしっかりと整備していくことが、まちの活性化と定住人口の確保。","voiceIndex":33,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"この請願の中にも、少なくとも隣接する東急マンションの高さ以下にしてほしいということが書かれておりますけれども、隣接する東急マンションは１３階か１４階だと思うのですけれども、そのぐらい高くなれば、現状よりも多くの人が住むことができるということにもなりますので、多様な世代が住むということが、それでもできると思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"繰り返しになりますけれども、まず東急マンションですが、委員がおっしゃるとおり、品川区のほうでも１３階建て、４０ｍから４５ｍ程度というふうに捉えているところですが、区といたしましては、まちづくりビジョンでしっかりと示されている課題。","voiceIndex":35,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"その一定の高層化というのは、どのくらいなのでしょうか。もともと、北地区では、マンション１棟、大きなものがありますけれども、あれは５階建てぐらいですか。ほかのところは駐車場ですので、むしろ住宅ができれば、５階建てでも多くの方が住めるということになりますけれども、そうしたことで多様な住民が住めると思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"現在、準備組合で検討されているものにつきましても、２９号線沿いには１階の店舗を配置する。","voiceIndex":37,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"本当に高過ぎるという町の声がまさにそのとおりだというふうに私は思います。風の影響が、実際、住民の方に出ているというふうに私は思いますけれども、区の認識を伺います。丸ビルは１００ｍ未満ということで計画されているそうなので、今回、１１０ｍ、東京駅前よりも大きなビルが戸越公園駅に建つというのは、本当に戸越公園の街並みに全くそぐわないというふうに私は思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"今、委員からご指摘のございました既に竣工しております戸越五丁目１９番地区の周りで風が強いですけれども、区といたしましても、風が強い状況にあることは一定認識しています。このような状況を踏まえまして、区では再開発組合に対しまして対応策を検討するよう話をしています。","voiceIndex":39,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"請願項目の２番の高さを下げてほしいというところは、私はまさにそのとおりだなというふうに思います。それと、商店街があります。実際、１９番地では、そうしたコミュニティが、マンションの中での関係、あるいは地域との関係はどうなっているのか伺いたいと思います。そうした面でも、やはり防災の面から見ても悪影響があると思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこうしたところをしっかりと区民の声を聞いて反映していくということで、この請願にも書かれておりますけれども、都市計画審議会委員も参加して、まちづくりの専門家も交えて、住民と意見交流できる公聴会を開いてほしいということで求められておりますので、やはりそうした地区内だけでなく、広い方も対象に思いが話せる場が、まさに今、必要だというふうに思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、関係権利者等に対しまして、都市計画案について説明を行うとともに、質疑対応により出席者から質問や意見を陳述する機会を設けており、その場でいただいた質問や意見に対し、区が回答、説明を行うことが、より丁寧な対応と考えているため。","voiceIndex":46,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうなれば、実際、にぎわないということになりますので、お聞きしたいと思います。対策になっていないというふうに思います。実際にこれを仕組みとして区がつくっていくということが求められているのではないかなというふうに思いますけれども、いかがでしょうか。そうしたことを推し進めていくということが、まちづくりの在り方としておかしいのではないかというふうに思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、聞くだけでは、やはり丁寧な対応とは言えないと考えておりまして、その場でいただいた意見や質問に対して丁寧に回答をすることが、より丁寧な対応と考えているところですので、説明会という形で実施しています。","voiceIndex":48,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"多分そうだったと思うのですけれども、北品川で止まったと思うのですけれども、そういったこともありますので、この戸越公園北地区の問題でも、一度立ち止まって住民の皆さんと話し合う場をつくっていくということが私は必要だと思いますし、それがやはりまちづくりとしての本来あるべき姿だというふうに思いますので、５月の都市計画審議会に今かけるということは、やめるべきだということは。","respondent":"大石まちづくり立体化担当課長","answer":"住民の皆様からしっかりと意見を聞くべきだというお話ですけれども、区といたしましては、都市計画法上の手続でやる説明会については、３月で終わっているところですけれども、ただ、一連の手続のほかにも、ご不安やご懸念があれば、区といたしましては個別でお話を伺うなど。","voiceIndex":51,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"都市計画の手続は、区が判断をして進めているわけですので、区が判断して、ぜひやめていただきたいというふうに思います。請願項目にある３番目、区議会としても現場を調査してほしいということで言われておりますので、様々説明会でも問題が上がっておりますし、実際、強風を体験するということなども含めて、現場を調査すべきだというふうに思いますので、皆さんもぜひ一緒に行けたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど来、やり取りがありましたけれども、初めに、委員長に伺えたらなというか、今お考えがあれば伺えたらと思ったのが、この請願項目の３つ目の区議会として現場を調査してくださいということですけれども、確かに建設委員会で請願・陳情に関わること、また、区の事業に関わること、様々な件に関して現地を確認するということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-015"},{"speaker":"中塚委員","kind":"確認","question":"特段、お考えはないということです。これは少し残念です。やはり書かれているとおり、長時間の日照が奪われる問題、風害が深刻な問題など住環境の問題、現状の商店街の機能や魅力が失われてしまうと訴えているわけですから、建設委員会として現地を確認して、その上で質疑、討論を行うということが活発な建設委員会かなと思いますので、一言述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-016"},{"speaker":"のだて委員","kind":"意見","question":"聞かれましたので、お答えしたいと思いますけれども、もちろん地域の方にも署名をお願いして回って、ほかの方にも、それはお願いをして回っています。やはりこの再開発の問題は、地域だけでなく、補助金も投入されるということですので、それは様々、いろいろな方に、特にこの開発とかに関心ある方にお願いをして、あと、関わる方にお願いをして集めてきたというものだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがとうございました。地域の方もいるし、関わっている関心のある方は署名してくれるということです。区は、一定程度まとまったのだと、都市計画の手続を進めていくのだとおっしゃるけれども、地域の方も含めて、これだけの方が反対であり、撤回を求めますという請願に署名をしているわけです。まとまっていないと思うのですけれども、いかがでしょうかというのが質問です。","respondent":"大石まちづくり立体化担当課長","answer":"一定程度まとまったですけれども、区といたしましては、昨年１２月に事業者のほうで説明会を開きまして、そちらで主な質問、意見をいただいたと聞いているところです。","voiceIndex":62,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"一定程度まとまったというのは、区の上位計画との整合性でまとまっただけであって、住民の中ではまとまっていないということですか。","respondent":"大石まちづくり立体化担当課長","answer":"先ほどお伝えしたとおり、１２月１１日の説明会でも事業者がその意見をしっかりと回答して、それらの意見を踏まえた上で計画案をつくっているというふうに聞いてありますので、そちらで一定程度まとまっているという表現を使っているところです。","voiceIndex":64,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"自分たちとしては、こうしたいと、意見が一致したから提出したに決まっていると思うのですけれども、私が言っているのは、４００名を超える反対があり、撤回を求める署名が出されているということと、先ほど、課長は、一定程度まとまったから進めていくのだというところは、あまりにかけ離れていると思うのです。一体どこが、一定程度、地域住民がまとまっていると言えるのですか。きちんと答えてください。","respondent":"大石まちづくり立体化担当課長","answer":"今回出された都市計画案、地域主体で検討されたものにつきましては、都市計画に対する仮同意という形で区のほうにも報告を受けております。","voiceIndex":66,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"今の約８割というのは、関係地権者の約８割ということですか。前回の建設委員会でも聞いたけれども、地域住民は、その場その場で対象が異なると。例えば、この説明会で言えば、２ｈａの範囲の方々にお知らせをしているわけですよね。２ｈａの範囲方々の８割が賛成しているという意味ですか。もう１回、別の聞き方をしますけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-021"},{"speaker":"中塚委員","kind":"確認","question":"地権者の約８割。ということで、２ｈａの範囲の関係住民の約８割では決してないということですよね。つまり、一定程度まとまったというのは、地権者がまとまったという、ただそれだけですか。もう一度確認させてください。","respondent":"大石まちづくり立体化担当課長","answer":"再開発事業、その他まちづくりにつきましては、その場でお住まいの方たちが話合いを重ねながら形づくっていくものと認識しています。","voiceIndex":70,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"森澤区長が本会議で何と言ったのかと。「まちづくりの主体は、そこに住む地域住民であるとの考えを改めて強くしたところです」と。この区長の言っている「地域住民である」とは、地権者を指しているということでいいのですか。","respondent":"大石まちづくり立体化担当課長","answer":"区長の答弁でありました「地域住民」ですけれども、地域に明確な定義はないものとまずは考えているところでございまして、使い方によって、その範囲が一定決まってくるものと考えているところです。","voiceIndex":72,"id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"何を言っているか分からないのですけれども、もう一度聞きます。区長が言っている「まちづくりの主体は、そこに住む地域住民であるとの考えを強くした」と、この区長の言う「地域住民」とは地権者を指しているのか、それとも、そうではないのか、ご説明してください。","respondent":"大石まちづくり立体化担当課長","answer":"使い方によって、その範囲が一定決まってくるものと認識しています。先日開催しました素案説明会では、地区計画の範囲内に権利をお持ちの方を対象としているため、例えば、素案説明会においては、その範囲の方が地域住民というふうに考えているところです。","voiceIndex":74,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"つまり、一定まとまったと言いながら、関係地権者の約８割が賛成だというだけで、この請願にも書かれているとおり、日照が奪われる、風害が深刻になる、商店街のにぎわいが失われる等、地権者以外の周辺住民の方に目が全く向いていないということなのです。森澤区長は、地域住民であると言いながら、結局、周辺住民には目を受けていないということでよろしいのですか。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、反対の意見があるということも区は把握しています。施設計画に関する意見は準備組合に届けるなど、しっかり行っていきたいと考えていますし、区では個別でご相談も受け付けておりますので、しっかりとそこは真摯に対応してまいりたいと考えているところです。","voiceIndex":76,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"４００名を超える方々が反対であり、撤回を求めている、こういうものが出ていて、反対の住民の声は聞きますと言いながら計画を進めると、これが区長が言う地域住民のまちづくりの主体なのですか。そうではなくて、地権者の８割がまとまっているというだけで、周辺住民がどのように反対をしていても計画は進めする、この区のやり方が一体どこが丁寧なのですか。区長が言っていること、うそではないですか。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、先ほどから申しているとおり、まちづくりビジョン、こちらは上位計画として位置づけておりますが、こちらにつきましては、基本計画になるのですけれども、策定時にパブリックコメントを実施しておりまして、それらの意見を踏まえた上で今のビジョンを策定していますので。","voiceIndex":78,"id":"exchange-026"},{"speaker":"中塚委員","kind":"確認","question":"さっきも言いました。それが民主主義だからいいのです。区長は、住民の様々な声に耳を傾けてまいりますと言ったけれども、耳を傾けているだけで聞いていないではないですか。ということは、まず聞くことは必要だなという姿勢でよいのかということをまず確認させてください。であれば、様々意見が上がっているのだから、５月の都市計画審議会の日程は延期すべきだと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"都市計画手続の延期をすべきですけれども、こちらも繰り返しになりますが、地域住民主体で検討されてきた案、こちらが私たち区でつくっております上位計画等との整合性について、しっかりと品川区のほうで確認いたしまして、今後。","voiceIndex":81,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"その説明はさっき聞いたのです。だから、その答弁を聞いて私が質問したのです。もう１回言います。つまり、意見陳述の場であれ、意見に対して回答ができる場であれ、いずれにしても地域の住民の方々が自分の思いを述べるという機会を確保することは必要だと。私、すごく丁寧に質問しているつもりなのですけれども、必要だという立場でいいのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"それに対しまして、しっかりと区として説明、回答を行うことが、より丁寧な対応と考えているところです。","voiceIndex":83,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"ならば、これだけ意見が出ているのだから、意見を聞く機会を遮って、一旦終了して、都市計画手続に進むのではなくて、５月の都市計画審議会は延期すべきではないかと冒頭に私は質問したわけです。個別には聞きますよ。これだけの方が。分かりますか。そういう場で意見を聞くことが基本だというのであれば、都市計画審議会の日程を延期して意見を聞く機会を設けるべきだと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"５月８日に開催されます都市計画審議会では、都市計画法第１７条で募集しました意見書の内容も踏まえた上で都市計画審議会の委員の皆様に審議をいただく予定としておりますので、そこでどういったご意見があるか、そこも審議をいただく予定になってあります。","voiceIndex":85,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"意見を聞くと言いながら意見を聞く場をつくらない。森澤区長については、まちづくりの主体はそこに住む地域住民と言いながら、実は地権者の約８割の合意で進めていく。本当に乱暴だなと思います。今の説明も、都市計画審議委員の方々に諮って進めていくのだと、それはそういう形をとっています。課長は現地を見たことがあるのですか。ここ、周りはオフィスビルではないですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"いわゆる地域の概念というのはなかなかであったわけですけれども、まさに地権者というところであれば、そうしたご意見があったり、また、それを含め、その地域でお互い暮らしていくわけですから、そういった面では、まさに風通しのよい関係、風の課題があるわけだけれども、風通しのいい関係性をつくっていくということは、やはり行政の立ち位置としてのそれぞれの意見をどう調整していくかというところが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択です。１月の説明会の意見書も反対のほうが多くありました。これはこのまま進めてよいわけがありません。昨年１２月の事業者説明会が準備組合の理事長が発言をして、皆さんの意見を活かしていきたいと言っておりました。一言、都市計画審議会を５月にやると言っておりますけれども、この状況ですので、ぜひやらないように、これは強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"意見を聞くというのであれば、それが反対の意見であっても、まずは双方の主張を出して整理して、何が問題なのか、どうすれば解決ができるのか、その話合いを継続することなどなど、先ほども指摘をさせていただきました。少なからずまちの意見が二分しているのに、地権者の合意だけで進めていく、こうしたまちづくりは間違っていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"本日結論を出すで、先ほどの説明や議論を踏まえまして、不採択でお願いします。今後も区民のお声については、区として丁寧に聞き、また、真摯にご対応していただきますようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-034"}]},{"id":"topic-02","title":"令和７年５月都営住宅入居者募集","agenda":"令和７年５月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"昨年度の申込人数や倍率を資料に載せていただきまして、ありがとうあります。今後もよろしくお願いいたします。昨年８月と今年の２月、単身者向けの募集の際に倍率が非常に高くなっていますけれども、８月が１３４倍、２月が９２.５倍ということで、その原因は募集戸数が少ないということにあると思うのですけれども、なぜ募集戸数が少ないのか、どういう制度、仕組みになっているのか伺います。","respondent":"川原住宅課長","answer":"単身者向けの募集戸数がなぜ少ないかというご質問です。都営住宅については、区内には既に１４団地あるのですけれども、もともと単身者向けの住居は管理戸数が少ないということがありますので、当然、申込者数が増えると倍率も高くなるということが想定されます。","voiceIndex":100,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"併せて、ほかのものの住戸数も伺いたいと思います。都営住宅に網戸がないというのは、やはり夏場、窓を開けて風を入れたいとか、そういったことを考えると、やはりこれは普通に住宅として必要なものかなというふうに思うのですけれども、区内の網戸がない状況とか、分かれば伺いたいのと、区営住宅はどうなっているのかというところを伺いたいと思います。","respondent":"川原住宅課長","answer":"都営住宅も含め、公営住宅には網戸の設置そのものはないというふうに認識しています。区営住宅であっても同様に網戸に関してはご自身のご判断で設置をしていただくということになってありますので、そのような形をとらせていただいているところです。","voiceIndex":102,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"戸数は、詳細には単身者向けは分からないということだったのですが、何となくの割合とか、何割ぐらいとか、もしそういうものが分かりましたら伺いたいと思います。そうしたところを、やはり一般的な住宅としての機能を区営住宅としても持っていくということが必要なのではないかと思うのですが、いかがでしょうか。","respondent":"川原住宅課長","answer":"〔同日後刻に「都営住宅における単身者向けの戸数については公表されていない」と答弁あり〕 そして、単身者向けについては、少しお話はそれてしまうかもしれないですけれども、今、区では、民間の入居者あっ旋というところで。","voiceIndex":104,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこでは、今、やはり単身者が増えているということもあるかと思いますので、そうしたところで、やはり都営住宅の増設をしていくということが私は求められていると思いますので、区としても、区民の住居をしっかり保障していくというところで、東京都に都営住宅の増設を求めていただきたいというふうに思います。伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"単身者の住宅も、基準で５万３,７００円ですので、やはりそうしたところがない。なので、全然足りていないのです。公営住宅をぜひ増やして、区民の暮らし、住まいをしっかり保障していくということが自治体の役割だというふうに思いますので、増やしていっていただきたいと、これを求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"倍率が高い理由は、当然、少ないところに多くの方が申し込むわけであって、また多くの方が希望しているところの募集が少ないから倍率は高くなるわけですけれども、この高い倍率は、単身の高齢者のどのような暮らしぶりを示していると区は思っているのか、区民の暮らしの状況をどう分析されていらっしゃるのか、単身者向けの倍率が１３４倍、９２.５倍といっても。","respondent":"川原住宅課長","answer":"戸建てなど広い住宅が、お一人暮らしになって、もう不用になってしまったといったようなケースもあるかと思いますので、そういったお一人お一人の声をしっかりと聞きながら、適切なご案内に努めてまいりたいというふうに考えてあります。","voiceIndex":110,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"戸建てを持っていたけれども、様々な理由で、今は賃貸というか、都営住宅を希望されているというお話があったと思いますけれども、ここをもう少し深掘りしたいと思っていまして、つまり、ご高齢の単身者のどういう暮らしの厳しさを示していると思うのか、どういう暮らしの実態を示していると思うのか、どういう生活苦がそこにあると思うのか、改めて伺いたいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう暮らしぶりの実態なのか、改めて伺いたいと思います。なぜならば、課長としては、そうだとは言いづらいかもしれませんけれども、つまり、都営住宅が足りないことを示しているのだと思うのです。だから、私は、区は都に都営住宅の増設を求めていただきたいと思うのです。だから高倍率になっている。この認識に立つこと、そして都に求めることが私は品川区に必要だと思いますが、いかがでしょうか。","respondent":"川原住宅課長","answer":"民間の賃貸住宅をしっかりと分析をいただいたご意見も踏まえていたしまして、今後は、セーフティネット住宅の専用住宅であるとか、あと、今後、１０月に施行予定となるセーフティネット法改正による居住サポート住宅、見守り付きの住宅を、民間住宅の不動産事業者。","voiceIndex":114,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"１戸３０００万円、４０００万円です。家賃にして１０万円、２０万円です。そういう住宅は住民の反対の声を無視してつくるくせに、これだけ求めている都営住宅や区営住宅はつくらないという点は、いつも指摘させていただいて、住宅施策がゆがんでいると指摘させていただいていますけれども、やはり区民の暮らしの実態に、ぜひ目を向けて増設を進めていただきたいと要望して終わりたいと思います。","respondent":"川原住宅課長","answer":"先ほど１つ前の質問で、のだて委員からご質問がありました都営住宅の世帯向けの戸数というご質問に対しての補足の回答をします。都から区へのお知らせによりますと、都営住宅における単身者向けの戸数については公表されていないという状況です。","voiceIndex":116,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"できれば、そういう今の考え方の中で、ニーズがどういうふうな、世代も、また収入もいろいろ含めてあるのかということは精査していかなければいけないと思うのですが、単身者向けのつくりを、先ほど、公表はしていないけれども、あると思うのですが、その辺の調整というのでしょうか、今後、当然、全体のハードを増やすということはないと思うのですが、ただ、既存のもので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-044"}]},{"id":"topic-03","title":"ＡＩオンデマンド交通の実証運行","agenda":"ＡＩオンデマンド交通の実証運行","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"それと、今回、アルファード１台ということで、運転手と、乗客が５人ということですけれども、１台で大丈夫なのかなという、何となく２台でやるのかなというイメージだったのですけれども、対象地域の広さの面積は何平米なのかということも伺いたいのですが、そことの関係で、運行上、問題がないかどうかというところを伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"３点目が、１台で大丈夫かですが、率直に申し上げると、動かしてみなければ分からないというところがありますが、他区等のこれまでの実証運行等の状況を見ると、それほど逼迫した需要が初期から来るということは聞いていないところでして。","voiceIndex":123,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"実際、公共交通会議での質問に対する回答はどうだったのかということも伺いたいのと、あとは検証期間です、そうすると、結局は翌年の３月３１日までやりつつ、検証や分析もしながらということでしょうか。","respondent":"櫻木地域交通政策課長","answer":"ミーティングポイントについては、機動的にというか、実施をしていく中で、近隣の方から様々ご紹介等があれば、そこは検討するということで増えていく可能性もあるのかなとは思っております。","voiceIndex":125,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"ほかのところも、旗の台六丁目とか、小山六丁目、七丁目辺りは、あって１か所というような感じになってしまっているので、やはりこうしたところに、適宜、ミーティングポイントを設置していくということが利用しやすいものになるのかなというふうに思いますので、ぜひそうしたところも、挙げたところも含めて増設していっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"２点目です。アプリの説明会なのですけれども、これから検討というところではありますが、地域センター単位でやっていくのかなという感覚ではおります。","voiceIndex":127,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、説明会は、地域センター管内ですか。需要との関係があると思いますけれども、それでしっかり説明、周知できるのかなというところもあるので、ぜひきめ細かくやっていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-048"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。複数質問します。運転手なのですけれども、何名体制で行われるのかというところと、あと、運行の事業者とシステムの事業者があるかと思うのですけれども、それぞれどのような連携体制をとって行われていくのかということを確認させてください。最後に、点検であったりとかメンテナンス、整備の状況を教えてください。","respondent":"櫻木地域交通政策課長","answer":"アンケートにつきましては、これもこれから検討するところではありますが、基本的に、こちらはアプリを使って予約することが主流ですので、アプリ内でアンケートをとる、もしくは車内でアンケート用紙をとって。","voiceIndex":130,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干伺いたいのですけれども、まず、周知方法、先ほども議論がありましたけれども、昨年、建設委員会でも行政視察でたくさん学ぶことが多かったのですけれども、その中の１つが、フットワーク軽く、呼ばれたら、大小構わず、どこでも行って説明をすると、これがやはり、地味なのだけれども、確実に必要な人が使ってくれるというのでしょうか、それを私、受け止めたのです。","respondent":"櫻木地域交通政策課長","answer":"説明会、基本的には係長、もしくは事業者と係長という形でやらせていただくと考えています。できるだけ利用を、参加していただきやすいように、例えば平日と休日、もしくは昼間と夜のような形で、少しバリエーションを変えながらやらせていただければと考えています。","voiceIndex":132,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１点、ミーティングポイントの議論がありまして、先ほど説明があったのですけれども、旗の台駅前にないのはなぜなのかなということなのですけれども、電車と電車の交わるところだし、結構な乗る人も、降りる人も、乗り換える人もいる駅だと思うのですけれども、ぜひ旗の台駅前にミーティングポイントをつけていただきたいと思いますが、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"ただ、ご指摘のとおり、ここにあったら非常に利便性が高いということと、障害者施設への使い勝手という形でも、旗の台駅にあると望ましいのかなと私どもも考えていますので、どういう形ができるのかということは考えてまいりたいと考えています。","voiceIndex":134,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"交渉したけれども難しいということでしたけれども、確かに乗り降りが多い駅だと、その分、人もいるから、逆にそこがミーティングポイントになれないという難しい現象になってしまってはいるのですけれども、例えば、考え方としては、運行エリアからは離れるけれども、住所でいうと、旗の台三丁目、旗の台四丁目側にというか、そこでも一定広さがあったり、場所があったりであれば。","respondent":"櫻木地域交通政策課長","answer":"現在設定している運行エリアにつきましては、様々な関係機関との調整、もしくは地域の交通事業者との調整で、こういう形であれば、運行、営業に支障がないというお話等もいただいた中で設定していますので、基本的に区としましては、広げていく。","voiceIndex":136,"id":"exchange-052"},{"speaker":"澤田委員","kind":"確認","question":"そういう場合、同乗する方、サポートする方の割引はどうなっているのかということと、あとは、塾への送迎とかも、後々のというか、目的の中の１つにあると思うのですけれども、今回、午後５時までというところで、子どもだけで使うということはあまりないかもしれないのですが、子どもだけ、小学生とかだけで使うという場合は使えるのかということと、その場合は、保護者が例えばアプリとかで予約して。","respondent":"櫻木地域交通政策課長","answer":"２点目の、いわゆる代理予約ということかと思いますが、代理予約については可能です。３点目で、説明会等で説明するマニュアル等は、お持ち帰りいただいて、ご自身で使えるような形で説明会をできればと考えています。","voiceIndex":138,"id":"exchange-053"},{"speaker":"澤田委員","kind":"質問・要望","question":"代理予約について確認なのですけれども、子どものための代理予約で大丈夫ということなのですかということと、あと、お持ち帰りいただく案内のものは、分かりやすく、例えば絵が対応されていたりとかという形でやっていただけたらいいなという、こちらは要望です。","respondent":"櫻木地域交通政策課長","answer":"お子様のために親御さんが予約するということは可能なシステムになっております。","voiceIndex":140,"id":"exchange-054"}]},{"id":"topic-04","title":"東品川海上公園におけるＰａｒｋ－ＰＦＩの導入に向けた公募設置等計画の認定","agenda":"東品川海上公園におけるＰａｒｋ－ＰＦＩの導入に向けた公募設置等計画の認定","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"確認をさせていただきたいと思いますが、今回、公募をした際に、提案はどのくらい、何者あったのか伺いたいと思います。それと、少しそもそも論的なところになってしまいますが、資料の２、選定方法にある選定委員会と選定会議との位置づけの違い、選定会議は区の職員４名のみとなっていますけれども、法律上そう決まっているのかどうかということも含めて伺いたいと思います。","respondent":"大友公園課長","answer":"東品川海上公園におきましては、水辺空間の利用促進、また、地域の交流の場の居場所づくり、居心地のよい時間を過ごせるサードプレイスの創出というところを考えているところでございまして、それを実現できるという提案であった内容だと認識しています。","voiceIndex":147,"id":"exchange-055"},{"speaker":"のだて委員","kind":"提案","question":"提案は２者あったということで、今回の提案の優れていた部分、選定理由のところなのかもしれませんが、その辺を伺いたいのと、あと、選定会議が選定委員会の中の会議だというお話だったのですけれども、そこを学識経験者など、地域団体の方も外して選定をするというのは、どういうことなのか。","respondent":"大友公園課長","answer":"こちらについては２０年間という安定した事業が実施できるかを審査するために基準を設けたものでございまして、そのため二次審査の対象は、認定計画提出者である東品川海上公園のHarbor of Harmony共同企業体の１者となっているところです。","voiceIndex":149,"id":"exchange-056"},{"speaker":"のだて委員","kind":"提案","question":"それで、選定委員会のところでは、選定会議を別でやらなければいけないという法律はないということですか。それと併せて、今回、施設をいろいろつくるということで、新しくつくるのは、飲食施設と自販機になるのですか。選定理由のところで、地域の声も聞きながらということが書いてあったと思うのですけれども、そこの地域の声を聞く仕組みは、どういう提案がされたのか伺いたいと思います。","respondent":"大友公園課長","answer":"選定委員会や有識者の意見等々、そのまま決定することはできなかったのかというところなのですけれども、こちらにつきましては、先ほどお話しさせていただいた都市公園法第５条の４の第４項で書いているところなのでけれども、公園管理者、設置予定者を選定しようとするときには。","voiceIndex":151,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり住民の憩いの場にもなります公園ですので、地域住民の意見が反映された、また、利用しやすい、愛されるような公園にしていくことが必要だと思いますので、そこをお願いしたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"周辺住民の方々、公園を利用されている方々の声が、オープンまでの間に計画に反映し、オープン後も反映する仕組みはないのか、あるのであれば、「いやいや、問合せに対して答えますよ」という程度なのか、例えば、説明会みたいなものを開いて意見を伺うのか、その仕組みというところを改めてご説明いただきたいと思います。","respondent":"大友公園課長","answer":"その後、地域団体等との調整期間を踏まえた後、その前に、一定、地域団体との実施内容がまとまった段で、本委員会および地域に説明するという予定になってあります。","voiceIndex":154,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがとうございました。２０年ということで、制度上の質問です。なぜかというと、これから始まるというときに、「なんだ、２０年後のことを聞くのかよ」と言われるかもしれないけれども、２０年後はどういうふうに、一からやり直すのか、それとも、この制度そのものの、そもそも論から、２０年後ですから、２０年後はどうなるのかという仕組みだけご説明ください。","respondent":"大友公園課長","answer":"したがって、基本的には、原状回復をして２０年を終えるという状況になります。２点目ですけれども、地域の声をというところにつきましては、要望として受け止めさせていただきまして、今後、よりよい公園づくり、維持管理等に努めてまいりたいと考えているところです。","voiceIndex":156,"id":"exchange-060"},{"speaker":"澤田委員","kind":"質問・要望","question":"少し確認させていただきたいのですけれども、東品川海上公園なのですけれども、公園のトイレに、おむつ替え台はあったかなということを教えていただきたいのですけれども。","respondent":"大友公園課長","answer":"設置されております。","voiceIndex":158,"id":"exchange-061"},{"speaker":"澤田委員","kind":"提案","question":"今度、バーベキューテラスのほうに、もしトイレなどが、室内にも、屋内にもできるような形であれば、このイメージの写真だと建物になっているので、例えば、その中にトイレなどができるということであれば、大きな公園ですので、おむつ替え台とか授乳スペースなど、やはりあると便利なのかなということがありますし、出先で困っているお母さんもよく見かけるので。","respondent":"大友公園課長","answer":"現在いただいている提案、計画という中においてなのですけれども、建物の外からも、中からも利用できるトイレという形で考えているです。しかしながら、実際にどのような設備というところまでの踏み込んだご提案はないので、これからの調整の参考にさせていただきたいと思います。","voiceIndex":160,"id":"exchange-062"},{"speaker":"澤田委員","kind":"意見","question":"女性のトイレだけではなく、男性のトイレにも、おむつ替え台があるところも今は多いので、ぜひそちらもお願いしたいと考えています。ほかにも、先ほどの話につながるのですが、子育て支援販売機として、おむつなどの販売機も、今いろいろなところに置かれ始めていますけれども、そういうものもいいのではないかなと思うのですが、その辺の考え方をお聞かせください。","respondent":"大友公園課長","answer":"現在いただいている提案で、まだ詳細ではないのですけれども、自動販売機につきましては、３台の設置予定というところで計画しています。","voiceIndex":162,"id":"exchange-063"},{"speaker":"横山委員","kind":"提案","question":"少し細かい質問になってしまうのですけれども、少し分からないところがありますので、イメージを教えていただきたいなと思いまして。事業者の優れた提案である評価として、これまでの実績が豊富だというお話なのですけれども、具体的にどういった公園であったり、どういったことをされてきたという部分を区として捉えていらっしゃるのかということをご説明いただきたいと思います。","respondent":"大友公園課長","answer":"可動式日除けにつきましてですけれども、タープといわれるものを想定していると提案を受けているところです。タープの下に、ベンチであったり、テーブルであったりの設置を検討しています。","voiceIndex":164,"id":"exchange-064"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。ごみ箱については、これ、ドッグランの近くなので、そういういろいろなごみも出るのかなですとか、なるべく早めに効率的にごみを回収していくみたいな形で運用されていくのかなというふうに少し思ったのですけれども、また、Ｐａｒｋ－ＰＦＩを都内で多数実績があるということで、私、期待しておりますので、ぜひ進めていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-065"},{"speaker":"つる委員","kind":"質問","question":"共同企業体の名前なのですが、これは、企業が、代表とか構成法人のほうであった名前なのでしょうか。教えてください。","respondent":"大友公園課長","answer":"この企業体の名前についてですけれども、事業者側から、このような企業体名でというところでの提案があって、応募がこの事業名であったです。","voiceIndex":167,"id":"exchange-066"},{"speaker":"つる委員","kind":"質問","question":"多分、企業名とかの類似とか版権だとか、いろいろ商品に既に使われているとか、いろいろあるのだと思うのですけれども、その辺は、これだけの大きな企業ですから、当然チェックして、クリアして、この名前というふうになっていると思うのですけれども、その辺りも含めて教えてください。","respondent":"大友公園課長","answer":"しかしながら、「ハーバー（Ｈａｒｂｏｒ）」とか「ハーモニー（Ｈａｒｍｏｎｙ）」というのはよくあるような名前、単語ではあるので、一部活用されているところはあるのかもしれないですけれども、大丈夫なものと認識は当然しております。","voiceIndex":169,"id":"exchange-067"},{"speaker":"つる委員","kind":"質問","question":"先ほど、ＩｏＴのごみ箱の話がありましたけれども、そこは外面というのか、周りを広告だったり、いろいろ自治体の特徴の絵とかを付けたりということがあるのだと思うのですけれども、この辺の考え方を教えてください。","respondent":"大友公園課長","answer":"２点目のご質問ですけれども、アートですけれども、こちらは、アートというところで、天王洲はアートを進めている地域として様々なアートの取組があるかと思います。","voiceIndex":171,"id":"exchange-068"},{"speaker":"つる委員","kind":"提案","question":"そうすると、今のアートのところは、具体的に、絵とか、そういうものは、共同企業体のほうからの提案というふうになるのでしょうか。直近で言うと、品川区の新たなアートの採用があったかと思うのですが、その辺との関連も含めて教えてください。","respondent":"大友公園課長","answer":"具体的な提案内容について簡単にご説明させていただければと思います。こちらは、既存のトイレであったり、自動販売機であったり、ごみ箱であったり、アートラッピングというもの、全体的なラッピングを行うということでご提案をいただいております。","voiceIndex":173,"id":"exchange-069"}]},{"id":"topic-05","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"老朽化対策と耐震化をぜひスピードアップして進めていただきたいと思うのですけれども、どうやると早く進められるかというところ、何か方策はないのかなと思うのですけれども、伺いたいと思います。開削工法で一部やるということでしたけれども、今回の路線でいくと、何ｍぐらいになるのか、分かれば伺いたいと思います。","respondent":"関根河川下水道課長","answer":"延長ということではあらわしていないのですけれども、箇所数としては、１件目の東五反田一丁目、北品川三丁目の工事におきましては、４０か所程度、北品川二丁目の工事につきましては、６０か所程度の開削工法の採用を予定しております。","voiceIndex":179,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、全体で都のものも含めて５割ぐらい完了しているということで、区のところで見ると、平成２５年からですから１１年、１２年で５割と考えたら、さらに、その倍がかかるということになるので、ぜひこれは早く進めていただきたいなということで、管きょ更生工法がいいのではないかというお話だったので、そういうことも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"それだけに、こういう事業は敏感になるといいますか、少し質問したいのですけれども、東京都下水道局からの受託事業ということなので、東京都の意思が強いのだと思うのです。工事概要で、１つが、なぜここなのかということと、陥没の防止にどれぐらい効果があるのか、その２点を伺いたいと思います。つまり、選定路線の選定や、その方法や理由、危険箇所からやっているということなのか、状況を伺います。","respondent":"関根河川下水道課長","answer":"こちらにつきましては、先ほど写真でご説明させていただいた中に、被覆・補強するというものですけれども、こちらにつきましては、膜を覆うというイメージよりは、実際に中に入るものにつきましては、新しい管と同等程度の強度があるものを採用していますので。","voiceIndex":182,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"ご説明ありがとうございました。もちろん工事に絶対安全はないのだけれども、こういう問題意識で、こういう工事がここまで進んでいますよという区民への周知、またはホームページでは、より丁寧な周知ができると思うので、事故を受けての品川区の取組の進捗状況を広報紙や区のホームページで丁寧にお知らせしていくということが大事な時期だと思いますので、最後に、その点だけお考えを伺いたいと思います。","respondent":"関根河川下水道課長","answer":"例えば、工事の中でも、地元の方につきましては、工事することだけではなくて、工事の目的ですとか、どういったものでやるのかということも含めて、チラシというか、ビラというか、そういった形での周知等も考えておりますので。","voiceIndex":184,"id":"exchange-073"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは１点、質問させていただきたいのですけれども、先ほどの質疑の中で、新しい管と同等というお話がありましたけれども、こちらの管きょ更生工法を行いますと、どのくらい寿命が延びるのでしょうか。耐用年数等をどのように、区として、東京都として考えていらっしゃるのかということが分かれば教えてください。","respondent":"関根河川下水道課長","answer":"耐用年数につきましてですけれども、東京都下水道局のほうでは、新しい管については、これまで５０年を耐用年数として考えていたものを、適切に補修等をしながら延命化させて、トータルでのコストを減らして効率的に老朽化対策をしていこうという形の考え方をとってありますので。","voiceIndex":186,"id":"exchange-074"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。東京都のほうでも、ある一定、調査ですとか様々していただいているとは思うのですけれども、区と都で情報連携をしていただきながら、耐用年数にかかわらず、しっかりと点検ですとかメンテナンス、情報共有、ぜひお願いしていただきたいと思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7021#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":58360,"voices":190}},{"id":"r07-20250415-9","meetingId":"r07-cm04","date":"2025年4月15日","dateIso":"2025-04-15","committee":"文教委員会","time":"午後 １時００分～午後 ４時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区教育振興基本計画「品川区教育ビジョン」の決定","agenda":"品川区教育振興基本計画「品川区教育ビジョン」の決定","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどこれから周知に当たるという話がスケジュールのご説明の中でありましたので、ウェルビーイング教育は何ですか、こういう定義です、こういう意味ですということを、区民の方、また、特にお子さんを持っている保護者の方へ、品川区はこのように子どもをしっかり教育していこうと思っているのだということ、多分、これを策定された教育委員会の皆さんは当たり前のことだから。","respondent":"丸谷教育総合支援センター長","answer":"学校におけるウェルビーイング教育の取組につきましては、今後、子どもたちだけではなくて、保護者や区民の皆様にも広く知っていただく必要があると思いますので、ウェルビーイング教育としての定義といいますか、説明につきまして、分かりやすく。","voiceIndex":36,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"あくつ委員と同じ問題意識であります。今日は、確定版のご報告ということなので、今後の説明会の中で、あくつ委員同様の思いでですね、もっとより理解を深めていただけるようにお願いしたいと思います。ウェルビーイング教育というのは総じていうと。１点だけ、この計画書の３ページにウェルビーイングとはとあります。改めてすみません、分かりやすく教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長、唐澤教育施策推進担当課長","answer":"そういった基礎について学びを深めていきながら、将来かけてこれは学んでいくというか、身につけていくものだと思いますので、そういった将来にもつながるような学習を進めてまいりたいと考えております。センター長が先ほど申し上げたとおり、今後、先生方が子どもたちに詳しく説明していくことを前提とした上で、例えば、ここにある、困難を乗り越える力や。","voiceIndex":40,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"一人ひとりが幸福を感じ、生きがいを感じられる学びというのは、学校の現場、６年間プラス３年間で９年間の学びももちろんなのですが、学ぼうとする姿勢を学ぶというのでしょうか。そういうことを通じて、将来、学校を卒業した以降もウェルビーイングを子どもたちが体得できるような、ぜひ学校教育を実現していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-003"},{"speaker":"西村委員","kind":"質問","question":"このパブリックコメントの中にも書かれているのですけれども、これまで品川区は独自の３校種体制における学校教育の推進というのをやってきていただいたと思います。ですので、この教育ビジョンの中で、特別支援や不登校支援に関して、ＰＤＣＡサイクルがどのように行われていくのか、どのように示しておられるのかというのを区民の方からも聞かれておりますので、改めて伺えればと思います。","respondent":"唐澤教育施策推進担当課長","answer":"事例としては、発達障害教育支援員の配置と記載されていますが、今後、この実行プランの中で、特別支援学級の開設であるとか、今後の支援の流れだとか、そうしたものを示していければと現在考えておるところです。","voiceIndex":45,"id":"exchange-004"},{"speaker":"西村委員","kind":"質問","question":"この教育ビジョンだけではまだもちろん具体的なところが見えてきませんので、ぜひ実行に移されるところまで、課題もたくさんあると思いますが、お願いしたいと思います。先ほどからいろいろと新しい言葉も使われているので、子ども向けのものを作ってほしいという思いもあるのですけれども、その点はいかがでしょうか。","respondent":"舩木庶務課長","answer":"なかなか、専門的な用語の記載もありますので、今後、本計画を進めていく中で、各学校の児童・生徒に、区がこういうことを目指しているのだということが、そういった方向性がうまく伝わるように、今後、検討してまいりたいと思います。","voiceIndex":47,"id":"exchange-005"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも何点か質問します。ほかの委員からもご質問ありました趣旨と、分かりやすく伝えてほしいという観点から、幾つか質問します。品川区教育委員会で掲げている教育目標、基本方針との関係性について確認をさせていただきたいです。表では相互連携と書いてあるのですけれども、それぞれをどう活用して周知していくのかというところになります。すみ分けとか関係性について教えていただきたいと思います。","respondent":"舩木庶務課長","answer":"教育委員会の教育目標、あるいは教育方針との関係性、まず、そこですけれども、区では、これまで教育改革で培ってまいりました成果を活かして、次世代を担う子どもたちの未来を切り開く資質・能力を育てるために、地域とともにある学校づくり、それから。","voiceIndex":50,"id":"exchange-006"},{"speaker":"山本副委員長","kind":"質問・要望","question":"パブリックコメントについても質問させていただきたいのですけれども、４８件あって、肯定的なものもあれば、否定的なものもあり、それから、要望、改善を求めるものなど様々あるです。そのご要望のところで、私もすごく考えが似ているので質問したいのですけれども、教育現場での負担がすごく重いと。それから、まとめます。計画の４２ページですね。失礼いたしました。","respondent":"舩木庶務課長、丸谷教育総合支援センター長、唐澤教育施策推進担当課長","answer":"これは今現在、区全体で行っているパブリックコメントの在り方も含めて、どのような方法が、区民の方の意見をしっかりと集約でき、そして。現在、デジタル推進課と連携いたしまして、実施時期や実施内容について、今協議を進めているところです。今回の教育振興基本計画の検証につきましては、調査項目などを検討しながら、今後の実施について考えてまいります。","voiceIndex":52,"id":"exchange-007"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ぜひこういった効率的にできる手法を教育現場の皆さんに教えていただきたいと思いますので、よろしくお願いいたします。私からの要望としては、今までやっているアンケートの内容に加えて、今回のこの教育ビジョンに関する変化に対してもしっかりと聞けるような、質問が分かるような、分かりやすい質問等を入れ込んでいただいて、ぜひ効果検証をしっかりしていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-008"}]},{"id":"topic-02","title":"令和７年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副園長・副校長異動者名簿","agenda":"令和７年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副園長・副校長異動者名簿","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。今年度、来年度も含めてですかね、１５０周年を迎える小学校がいくつかあると思うのですけれども、そういったところに関しての配慮というか、基本的に異動のときにはお考えいただいているとは思うのですが、ぜひそこは配慮をしていただきたいという町場の意見です。ぜひ検討していただきたいということなのですが、ご答弁をお願いします。","respondent":"酒川指導課長","answer":"当然、都の広域人事の中ですので、致し方ないところはあるわけですけれども、そういった地域の声ですとか、学校、また、職員の声も踏まえて、何とか皆さんの思いに応える人事にはしておりますし、引き続きそういうものには応えていきたいと考えております。","voiceIndex":61,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"最大限応えていただいていると思います。これは当然、東京都教育委員会が決めることだと思うのですが、当然地元の意見も聞くでしょうから、その辺り、しっかりご配慮をお願いしたいということでお願いをします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"品川の教育は、平成１２年からプラン２１が始まりまして、教育改革が進んでおります。当時から、都内の教育の中で、品川区教育委員会は先進的に取り組んできたと思っています。それがあって初めて正式に品川の先生として迎えていただけるということになるのだと思うのですが、そこら辺はどのように取り組まれていらっしゃるのでしょうか。","respondent":"酒川指導課長","answer":"今、品川区の固有教員の配置を進めておりますけれども、こういった教員が、各学校で品川の教育の一番の推進者として、異動してきた教員にも、そういった区の教育への理解、普及を進めていくというようなことを行っているところです。","voiceIndex":65,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"しっかり教育を理解していただく一方で、他区での先進事例というのもあると思っています。こういう他区から来られている先生から他区での先進事例を学ぶ機会というのはあるのでしょうか。あったとするなら、私は、それは貴重な情報ですので、品川の教育をさらに充実させる上で、内容によっては当然活かしていくべきだと思っているのですけれども、その辺はどのような取組をされていらっしゃるのでしょうか。","respondent":"酒川指導課長","answer":"当然、他区からノウハウを持ってくること、教員が持ってくるノウハウというものを否定するつもりはございませんし、いいものはぜひ取り入れていきたいと考えています。","voiceIndex":67,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ありがとうございました。こういう人事異動を通じて、またさらに品川の教育の質を高めていただく、そういう一つの機会にぜひしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-013"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも何点かお伺いします。この異動の決定プロセスについての確認なのですけれども、都の教職員ではありますが、区の教育委員会のほうからも異動に関する意見が言えるのかどうかというところを教えてください。それでいうと、そういった観点でもぜひ区のほうで見ていただきたいと、私からもご要望はさせていただきたいと考えています。これは要望です。日野学園の校長先生の欄ですね。","respondent":"酒川指導課長","answer":"その場合には、どういった意図で先生を配置するのですとか、どういった意図で異動をしてもらうのですというのを丁寧にこちらも説明しますし、管理職同士も丁寧に引継ぎを行っていただいて、なるべく職員や地域に心配をかけないように、スタートができるようにしていっていただく。","voiceIndex":71,"id":"exchange-014"},{"speaker":"山本副委員長","kind":"質問・要望","question":"管理職が全て替わってしまうというところについては、ご配慮いただいているというところで確認ができましたが、できる限り、そういった事態を避けるように動いていただきたいという声が、やはり教職員や保護者の皆様からありますので、引き続きをお願いしたいと思います。どうしてもそうなってしまったときには、負担ができるだけかからないような工夫等を様々ご検討いただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど、副委員長がお話しした、管理職が２人同時に異動されたということですが、１０年ぐらい前にここで同じような質問をさせていただいて、それで、品川区からどこまで都教育委員会にそういうことが起きないように、強く主張しているのですかという話をしました。その後ずっとこういうことがなかったのですが、今年は、今、副委員長がご指摘されたように、３校もあるということです。","respondent":"酒川指導課長","answer":"繰り返しになってしまうのですが、校長にヒアリングをしまして、区の配置構想をつくって、都に内申をして、都が区にヒアリングをしてというところまでは要望を伝えることができるのですけれども、そこから先、最後、都がこれが最後の決定案ですと出てきたときに、それ以降。","voiceIndex":75,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"それは承知しています。そのときに、例えば、浜川小学校だったら、お二人ではなくて一人とか、ここ、区の固有の教員がいらっしゃいましたので、やり方が難しいかもしれませんけれども、３校というのはどうなのですか。ほかの区は見ていないから分からないのですけれども、ほかの２３区の中でも、それぐらい管理職が替わってしまうところがあったのか。具体的にどのようにフォローできるのですか。","respondent":"酒川指導課長","answer":"やはり全くもって好ましい状況ではないということは認識しておりますので、今後、区として、東京都とやり取りをするときに、しっかりと主張をして行かせていただきたいと考えています。これが１点目です。","voiceIndex":77,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今年の状況がどうか、いいかということを今見ていただいている、そういう感触を得ているところだと思います。どうやったらよくなっていくかというのも一番よくご存じだと思うのです。もちろん昇任することはすばらしいと思うのですけれども、その点について、品川区教育委員会の引き止めではないですけれども、ぜひ品川の教育を知っているのだから品川区でというところについてはいかがでしょうか。","respondent":"酒川指導課長","answer":"ただ、これについても、東京都の都全体の人事構想の中で、やむなく他区へというようなケースはどうしても出てきてしまうといったところですが、引き続き優秀な管理職の確保に向けて働きかけていきたいと考えています。","voiceIndex":79,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"意見","question":"ぜひそれをお願いしたいと思います。やはり一番に言えるのは、先ほどの繰り返しですけれども、その方個人のことを言っているという意味ではなくて、そういう方を品川区に残すような努力を、区の教育委員会なので、ぜひお願いしたいということを付け加えます。最後、１つだけ。","respondent":"酒川指導課長","answer":"もともと小学校籍の校長ではあるのですけれども、義務教育学校に配置する際には、中学校籍の校長として配置しています。","voiceIndex":81,"id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問","question":"それは小学校の免許があるので、それに特別の形で中学校の籍を取ったという考え方でよろしいですか。籍というのは……。","respondent":"酒川指導課長","answer":"もともと小学校の校長ですので、小学校と前期課程と後期課程、両方とも配置できる。今回、異動になっています守屋校長については、もともと中学校のほうで副校長経験があるということを踏まえて配置しております。いずれも中学校籍として配置しております。","voiceIndex":83,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"守屋校長は、荏原平塚で副校長をされていて、義務教育学校での経験はあるので、別になったことをどうこう言っているわけではなくて、ずっと今まで中学校の先生、いわゆる中学校の免許を持った先生がなられていたところ、経験がもちろんあるとしても、守屋校長がこのようになられたのは、今後そういうことも起き得るということなのでしょうかね。起きることが悪いという意味ではありません。","respondent":"酒川指導課長","answer":"これも、品川区全体の管理職の配置を考えたときに起こり得ると考えています。","voiceIndex":85,"id":"exchange-021"}]},{"id":"topic-03","title":"令和７年度（令和８年度採用）品川区立学校教育職員採用候補者選考日程","agenda":"令和７年度（令和８年度採用）品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"西村委員","kind":"質問","question":"特に大学３年生の前倒し選考について伺いたいと思うのですけれども、これは新しい試みと思っていてよいのかということと、こういう選考の仕方が今増えてきているのかというのも分からないので、教えていただければと思います。","respondent":"酒川指導課長","answer":"こちらは新しい取組です。なるべく優秀な人材を早めに確保したいということで、他の都道府県等々でも、こういった形が増えていると認識しております。","voiceIndex":91,"id":"exchange-022"},{"speaker":"西村委員","kind":"質問・要望","question":"本当に毎年募集が厳しい状態が続いていると思います。何か新しいことをということを要望してきた中でもあるのですけれども、これで本当にどれだけ来てくださるのかというところが見えないのです。見込みというか、こういう大学３年生の前倒し選考をすることで、うまくいっている事例がもし他区でもあるのであれば、教えていただければと思います。","respondent":"酒川指導課長","answer":"大学によっては非常に好意的に受け止めてくださいまして、学生に直接説明するような機会をつくってくれたというようなところもあったようですので、様々なＰＲの機会を今後検討していきたいと考えています。","voiceIndex":93,"id":"exchange-023"},{"speaker":"山本副委員長","kind":"質問・要望","question":"去年までは採用予定人数を、明確に、めどとして５名とか６名とか記載されていたのが、今回若干名に変わったのですけれども、これは何か理由があるのでしょうか。一方で、何か目標となる採用めどみたいなのがおありなのであれば、それをお伺いしたいということが１つあります。それから、前年度の採用実績と採用倍率、どれぐらいの競争率だったかというのをお伺いしたい。続けて言ってしまってもいいですか。","respondent":"酒川指導課長","answer":"現在、その５名を追加しまして、いわゆる管理職を除いた教員は２８名。管理職は３名です。段階的に４６校に配置するのかということにつきましては、おっしゃるとおりで、検討しております。","voiceIndex":97,"id":"exchange-024"},{"speaker":"山本副委員長","kind":"質問・要望","question":"大学３年生の前倒し選考はなかなか難しいということで、前年度は効果はなかったということですけれども、ほかもやっているということなので、同じように進めて、できるだけいい人材確保に努めていただきたいと思います。去年の実績で、２０名の応募で５名採用ということで、４倍の倍率ということだと思いますので、これは都の教職員の先生の倍率よりも高いのかと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどのところでおっしゃった統括副校長先生の話なのですけれども、これはお給料の表は、東京都の校長先生の表に当てはめていくのですか。副校長先生のラインではなくてというところが１つ。もう一つは、都道府県ではなくて、こういう基礎自治体が採用した教員の、それが校長先生という形で名のれるようになる法改正のめどがもし分かれば、お願いします。","respondent":"酒川指導課長","answer":"統括副校長は、申し上げましたとおり、給料表も校長と同級です。法改正等々については、今現在、正確に申し上げることができませんので、また改めてお伝えできればと思います。","voiceIndex":101,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、待遇がほかのいわゆる都職の校長先生と同じということで承知しました。それが今２８人いらっしゃる先生方、管理職のうち、校長級を除いた副校長先生は２名ですか、のやる気というか、そういった気持ちにつながっていくと思いますので、そこはぜひとも働きかけていっていただければと思いますが、そこだけ最後。","respondent":"酒川指導課長","answer":"ぜひ固有教員のやる気といいますか、意欲向上につながる、そういった管理職へのステップという道筋というものを今後も広げていきたいと考えています。","voiceIndex":103,"id":"exchange-027"}]},{"id":"topic-04","title":"品川区における部活動の地域移行に向けたロードマップ〔令和７年度〕","agenda":"品川区における部活動の地域移行に向けたロードマップ〔令和７年度〕","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました、私も詳しくないので、教えていただきたいのですけれども、今、アート部を新たに加えるというお話がありましたが、アートというのはどういったものを指すのかということがまず１点。それとも、実践をするお子さんとか学校の方針で決められるのか。そういったものについて、これは地域移行に関しては、どんなものでもいいのですということになっているのか、教えてください。","respondent":"酒川指導課長","answer":"今後、そういったことも踏まえて設定していくことになるかと思いますが、子どもたちからは、デジタルで絵を描いてみたいですとか、水墨画をやってみたい、版画、陶芸をやってみたい、３Ｄアートもやってみたいとか、様々な意見が出てきておりますので。","voiceIndex":109,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"ヒップホップダンスと決められているということなのですけれども、導入をする際には、先ほどのアートと一緒の形で、子どもたちの意見を聞いて、ヒップホップダンスがいいということにされたのか。決められているというのは、何かそれは誰かに決められていて、縛りがあるということなのか、教えてください。","respondent":"酒川指導課長","answer":"もともと地域のこういった地域部活動を支える団体として、この株式会社ウェーブマスターという会社がありまして、この株式会社ウェーブマスターのダンスのプロ集団がやっているダンスがヒップホップダンスだったということで、ヒップホップがまず最初にあってのことだです。","voiceIndex":111,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"今のご答弁ではそういうご説明だったのですけれども、子どもたちの意向というのは、今後、こういうところには反映をしていただけるのでしょうか。ヒップホップは人気だと思うのですけれども、ダンスというのもたくさんあり、こういうダンスをやりたいというようなことがあった場合には、それに沿ったような形での対応というのはできるのでしょうか。","respondent":"酒川指導課長","answer":"地域部活動ですので、地域にどういった資源があるのかということも大切になりますが、委員おっしゃいますとおり、子どもたちの思いというものも当然、大事に尊重していかなければいけないものだと思いますので、今後、このダンス等に限らず、地域部活動の幅を広げていくときには。","voiceIndex":113,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問","question":"地域部活動というところで、私がまだ理解できていないのですけれども、先ほどのアートに関しても、水墨画を習いたいといったときに、地域に資源がなければ、地域に水墨画を教える先生がいなければ、その夢はかなわないということなのでしょうか。","respondent":"酒川指導課長","answer":"そういった技術がある、ノウハウがあるというところと、子どもたちのやりたいこととのマッチングをしていくと、どうしてもそのようになってくるかと考えています。","voiceIndex":115,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"意見","question":"最後にします。地域部活動というのは、そもそも地域資源ありきなのだというのは、今、お話を聞いていて、分かりました。だから、先ほど言った人材リストの作成というところがあるのかと思いましたけれども、なかなかそうすると、制約があるのかと。この交通網が発達した段階においても、やはり地域にそういったものがなければ、制限、制約があるものだという理解をいたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"冒頭のご説明についてなのですが、既にこれは長年、部活動の改革、地域移行に向けた検討がされていて、今回、赤い部分が新たに加わったというご説明だったと思います。でも、メジャーと言っていいのかあれなのですが、今は野球、サッカーなどは対象から外れてしまっていて、ダンス、ラグビー、ホッケーとかに限定されてしまっているという状況なのでしょうか。","respondent":"酒川指導課長","answer":"加えて、学校部活動指導業務委託というこの緑のバーのお隣、左側に、部活動指導員の拡充とありますが、こちらは、学校教育総合支援センターから派遣しております指導員でございまして、教員の中で部活動をやりたい、自分で指導したい。","voiceIndex":119,"id":"exchange-033"},{"speaker":"田中委員","kind":"意見","question":"理解させていただきました。ただ、その後、顧問の先生が異動になってしまったために、継続がなかなかしづらい状況になってしまったという状況もあるのですけれども、そういう課題は、先ほど東京全体の人事異動との兼ね合いも含め、そういう先生の代わりとして、そういう指導者を常駐するというような取組はここには入っていないということですよね。","respondent":"酒川指導課長","answer":"指導の上手な、強豪校をつくるような教員がいるとしましても、公立中学校においては必ず異動年限がありまして、必異動ということで、必ず異動がつきものです。その途端に指導者がいなくなってしまうというようなことが生じるのは、これは致し方ないことかと考えています。","voiceIndex":121,"id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"すみません。要は、部活動を続ける上での費用はそんなにかかっていないと思うのです。要は有償で、外部に頼むということは、外部の事業者が主体となる事業になるので、有償だったらいいのかもしれないのですけれども、グラウンドとか体育館を無償で仮に貸すとしたら、それは学校施設管理上とか、もっと言うと、財源的なことも含めて問題なのではないかという気がするのですが、そこはいかがでしょうか。","respondent":"酒川指導課長","answer":"地域部活動も、学校部活動の指導業務委託のほうも、これまでよりも保護者負担が増えるというようなことはございません。","voiceIndex":123,"id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"分かりました。どこかの場面で確認だけしておいていただけたらと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２つお尋ねしたいと思います。もちろん地域に移行していくということは重要で、それをやっていく段階で、いろいろそれぞれ一生懸命やられるので、どうしても学校の考えなどと指導者の考えが合わないこともある。その点で、全校配置されているのかということと、どういう方がなっているのか。教員が兼ねているのか、あれですけれどもというのが一つ。その点はいかがでしょうか。","respondent":"酒川指導課長","answer":"全校配置ができるようにしていきたいと。教員がこれまで行っていたマネジメントの面、これを担ってくれる人材の確保に努めたいと考えています。基本的には、地域の学校に足しげく通うことができる地域の方というのを想定しております。","voiceIndex":132,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"意見","question":"コーディネーターのほうは承知しました。アートのほうは、今、お話があったように、ぜひとも何らかの形で参加していって、作品になるということがご本人たちの充実につながるので、その辺、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-038"},{"speaker":"西村委員","kind":"質問","question":"私も先ほどの委員の皆さんからの質問で大分理解できたところがありまして、学校部活動指導業務委託と地域部活動移行がごっちゃになって考えてしまっているような部分があったので、学校部活動指導業務委託の現在実施されている学校数を、先ほど言っていただいていたら申し訳ないのですが、改めて伺いたいと思います。","respondent":"酒川指導課長","answer":"この学校部活動指導業務委託、いわゆる学校で行っている部活動を外部の人に担っていただくというものですが、令和６年度から始め、今年度が改革推進期間の終わりということで、現在、全校で実施しております。大体各学校で３部活の業務委託を行っております。","voiceIndex":136,"id":"exchange-039"},{"speaker":"西村委員","kind":"質問・要望","question":"もう一つは、地域部活動移行のほうで、一度、渋谷区の地域部活動移行の話を伺ったことがあります。例えば、区内にも服飾の専門学校などありますし、セガだったら、ｅスポーツ部などもきっと子どもたちは大好きだろうと思いますので、そういった区内企業と連携できる可能性というのも模索していただきたいと思うのですが、その辺はいかがでしょうか。","respondent":"酒川指導課長","answer":"今後、また子どもたちのニーズですとか、地域にどんな資源があるのかということを踏まえながら、様々な活動の機会というのですかね。いろいろな活動ができる場所、機会というのを子どもたちに提供していけるように検討を進めていきたいと考えています。","voiceIndex":138,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問・要望","question":"基本的なことになってしまうかもしれないのですけれども、私からは、言葉について確認させていただきたいと思います。今回の資料で、品川区における部活動の地域移行ということなのですけれども、この中に地域部活動というのと学校部活動の業務委託、そういうものがまとまっているという理解でよろしいですか。物によって年齢が違うのかというところを教えていただきたいと思います。","respondent":"酒川指導課長","answer":"地域部活動のほうは、希望する５年生以上の児童・生徒で、小学生も含んです。","voiceIndex":142,"id":"exchange-041"},{"speaker":"せらく委員","kind":"質問","question":"御殿山小学校でダンス部が活動されているということで、５年生からということで理解しました。もう１点、実態について、資料右側の校区教育協働委員会のところで、２行目、部活動を地域移行することで、子どもたちの活動機会の影響や費用面の負担などが懸念されるというコメントがあったと思うのですけれども、費用面の負担というのは、子どもたちが負担するのですか。","respondent":"酒川指導課長","answer":"今まで教員が担っている間は、ほぼほぼ無償で指導を受けられたものが、地域移行し地域の中で企業等と連携してやっていくと、きっとお金がかかっていくのではないかという懸念がここに書かれていると思うのですけれども、そういった費用負担については。","voiceIndex":144,"id":"exchange-042"},{"speaker":"せらく委員","kind":"質問","question":"保護者の負担は極力生じないということで、そうしたら、学校側が負担が増えてくるという考えでしょうか。","respondent":"酒川指導課長","answer":"基本的には区です。","voiceIndex":146,"id":"exchange-043"},{"speaker":"せらく委員","kind":"意見","question":"分かりました。部活動の地域移行については、私もなかなか勉強不足で恐縮なのですけれども、今後も子どもたちがいろいろな体験ができるような方向にしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-044"},{"speaker":"山本副委員長","kind":"質問・要望","question":"本件については、これまでも度々質問とか要望をしてきました。学校部活動のほうです。それから、もし増やすとすれば、部活動指導員や、民間企業にお願いするのであれば費用の面があるということで推測しているのですけれども、もし生徒たちの声を基に、学校から部活を増やしたいという要望があったときには、区の教育委員会としてどのようなご対応を取られるのでしょうか。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"最初は、そもそも業務委託について、５部活動というのは予定をしておりましたけれども、令和７年度は３校というところで、しっかりと成果検証して、令和７年度以降、５部活動の委託というのを実現していきたいと考えております。今後の対応策といたしましては、地域の人材をどれだけ学校に取り込んでいくかというところもありますので、所管の文化スポーツ振興部等と連携をしながら、適切な人材を学校に配置できるように、検討というか。","voiceIndex":150,"id":"exchange-045"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それぞれご回答ありがとうあります。民間委託の対象学校数なのですけれども、令和６年度が２校、既にやっていて、令和７年度が、当初、５校に拡大する予定が３校にとどまっているという理解ですので、その辺り、既に１年やっていて、２年目というところの中で、５校ではなく３校にとどめた理由を改めてお伺いしたい。これは要望です。次に、併せて質問を続けますけれども……。","respondent":"酒川指導課長","answer":"最初の質問についてですが、やはり予算の部分です。","voiceIndex":153,"id":"exchange-046"},{"speaker":"山本副委員長","kind":"質問・要望","question":"様々、子ども・子育て施策、区として進めている中で、本件についてもすごく子どもたちのためになる大事な施策でもあり、教職員の負担軽減にもつながることでもあるので、ぜひ予算をつけていただきたいというところで、こちらは予算の都合ということだったので、来年度に向けて、今度こそということでご要望します。続いて、地域部活動について伺います。そういったところのお考えのところもお聞かせください。","respondent":"酒川指導課長","answer":"ですので、この体験会、説明会を丁寧にやって、今年度、参加人数がどのぐらいになるかというところを見ていきたいと考えています。","voiceIndex":155,"id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ぜひそのように進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-048"}]},{"id":"topic-05","title":"区立学校におけるいじめの重大事態の発生状況および調査結果","agenda":"区立学校におけるいじめの重大事態の発生状況および調査結果","exchanges":[{"speaker":"山本副委員長","kind":"質問","question":"ご説明ありがとうございました。私のほうから、いじめに関連してご質問をします。それから、あと、不登校支援ポータルサイトの「ぷらっと」も、昨年度つくっていただいていますので、こういったところも併せて学校の保護者となる方々にご案内いただいたらいいと思っているのですけれども、その辺り、ご計画等ありますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"保護者への様々な周知についてです。各学校では、４月の保護者会等を通しながら、学校いじめ防止基本方針の説明を確実にするようにということで周知をしています。","voiceIndex":163,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"昨年末の高等裁判所の判決で、大阪のいじめの事件において、いわゆる加害児童と被害児童がいて、被害児童のほうが、いわゆる別室登校ということで学校に通っていたけれども、結局、教室には戻れなかったというような事案に対して、教育権の侵害であるということで、判決は、いわゆる被害児童のほうの権利を認めて損害賠償を市に求めたというか、市が損害賠償をしなければいけなくなったというもの。","respondent":"丸谷教育総合支援センター長","answer":"こういったいじめが起こった際に、加害児童・生徒に対して、まずは事実確認のために、別室での事実確認と、場合によっては、指導という形で行うことはあります。一定期間、反省を促すために、別室での指導を継続するといった対応というのはこれまでもあります。","voiceIndex":167,"id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"運用については、加害児童の保護者からクレームが来たりとか、うちの子どもの学習権はどうなるのだとか、いろいろなことが錯綜しそうだというのは分かるのですけれども、そこについて。市側は控訴する、上告すると言っているので、まだ確定していないのですけれども、品川区としての現段階でのこうした加害児童、被害児童の学習権の保障というところについてのお考えを最後教えてください。","respondent":"丸谷教育総合支援センター長","answer":"そういった中で、個々のいじめ事案を指導、調査していく中で、必要な措置というものが取られるべきと考えておりますので、中には、加害児童・生徒を別室指導を継続したほうがいい場合もあるでしょうし、そうではなくて、お互い相互理解していく中で。","voiceIndex":169,"id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"今回、令和５年度の調査結果としてご報告を受けてました。私は基本的には、いじめた側が１００％悪いという姿勢で臨んでいるので、被害者側の立場に立って、そうした被害児童の学習権も含めた学校生活が守られるように、ぜひこれは今もやっていただいていると思いますけれども、そこについては配慮をお願いしたいと思います。答弁のしようもないと思うので、それで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-052"}]},{"id":"topic-06","title":"令和６年度就学・転学相談の結果","agenda":"令和６年度就学・転学相談の結果","exchanges":[{"speaker":"山本副委員長","kind":"質問","question":"一人ひとりの児童・生徒に寄り添った、こういった相談に乗っていただくようお願いしたいと考えています。その中でですけれども、この相談の中で、特別支援学校や特別支援学級のお勧めを区側からされている中でも、保護者の方のご希望で普通学級に通っているケースとかというのもあるのかと思うのですが、それがどの程度あるのかというところがもし分かれば、教えていただければと思います。","respondent":"新井特別支援教育担当課長","answer":"ただ、私どもとしましては、お子さんの様子というのを就学相談の中で確認をしていまして、その中でお医者さんですとか心理士の方、あとは、校長等の学校関係者による観察、検査なども踏まえ、就学先のご提案を丁寧に保護者の方に説明をいたしまして。","voiceIndex":176,"id":"exchange-053"},{"speaker":"山本副委員長","kind":"質問・要望","question":"これまでのご答弁の中でも、それぞれの状況があり、学校であったり、児童・生徒によっても状況が違うということがあるので、必ずしも毎日必要な子が全てだとは思わないですけれども、週に１回だけ２回だけというよりは、５日間いてもらったほうが、恐らく子どもたちにとってもいいと思いますし、学校の教職員の皆様にとっても、授業を進める上でもすごくいいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"中学校のほうは、今、浜川中学校と大崎中学校にあるのですけれども、このような数字というか、こちらに入られる生徒の増え具合というか、そういうところから見て、現状の、小学校のほうは１校、伊藤小学校が増えるからいいのですけれども、中学校のほうの状況は、数字を見ると１６人ということなので、今後、その辺はどのようにお考えですか。","respondent":"新井特別支援教育担当課長","answer":"やはり本区においても問合せが来ていると担当からは聞いてございまして、今後の就学人口の動向というものも踏まえた上で、また、この数年の増加率というのもきちんと見た上で、足りているか、今後増やしていくかどうかというところについては考えていきたいと思ってあります。","voiceIndex":180,"id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１学級８人ということですから、やはり増えていけば、足りなくなる可能性があるので、小学校のほうは伊藤小学校につくっていただいたように、中学校のほうもそれを考えて、今すぐにというのはできないので、しっかりと計画的に、自閉症・情緒の学級を中学校についても検討していっていただきたいと思います。今、状況を見ながらというお話でしたけれども、そこのところを確認で１つだけお願いします。","respondent":"新井特別支援教育担当課長","answer":"委員ご指摘のところ、やはり中学校についても、近年の動向を見ると、恐らくそういったお子さんが増えているということもありますので、自閉症・情緒の開設というのが必要かどうかということも含めて、計画的に増やせる学校はどこなのかといったところを。","voiceIndex":182,"id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。品川区に入れないので近隣の区へというのは、本当に保護者もご本人にとってもつらいことなので、ぜひ品川区で体制を整備していただきたいと思います。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-057"}]},{"id":"topic-07","title":"品川区こども計画の策定","agenda":"品川区こども計画の策定","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"確認なのですけれども、これは本編にもあると思うのですが、子ども向けの品川区こども計画こども版で、「たくさんのこどもの声を聞きました」と書いてあります。これはタウンミーティングのことを指しているのでしょうか。それとも、ＳＤＧｓとかでもあると思うのですけれども、これは何を指して品川区こども会議とおっしゃっているのか、教えてください。","respondent":"三輪子ども育成課長","answer":"おっしゃるように、区長とのタウンミーティングのことを指しています。","voiceIndex":189,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"これは、タウンミーティング、イコール、品川区こども会議という名称で実施していたのでしょうか。","respondent":"三輪子ども育成課長","answer":"おっしゃるように、みんなと区長のタウンミーティングで、副題で品川区こども会議というような形でつけさせていただいて、すみません、紛らわしい表記で申し訳ないですけれども、そういった形になってあります。","voiceIndex":191,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問","question":"今のお話にも関連するのですが、次の質問です。それと、ここでも品川区こども会議という表記がされていますけれども、実はタウンミーティングですと。それと、ＳＤＧｓのほうでも、こども会議というようなものがある。今回、リバースメンター事業というのも始まるということで、前にも質問しましたけれども、間違っても、屋上屋を重ねることにならないように。その辺りについて教えてください。","respondent":"三輪子ども育成課長","answer":"サイドブックスの８２ページになるかと思うのですけれども、子どもの意見表明・参画の促進というところで、具体的な取組というのはこういったことを行っていきますということを一覧にはしているというところでございまして、それぞれの対象でしたりとかが細かく異なる部分。","voiceIndex":193,"id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区は真っ先に手を挙げて、既にやっている部分もあります。各会議体にそれぞれ目的があって、意図があって、年代別というところの非常に重要な点もある、声の違いというのもあると思いますので、そこのところを区民、特にエントリーする方、保護者に向けて分かりやすいように、ぜひこれはお伝えしていただきたいと思います。そういう趣旨で質問しましたので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-061"},{"speaker":"西村委員","kind":"質問・要望","question":"実際にこども基本法の中でも、子どもの声を代弁するということをどう仕組み化していくのかということを自治体が求められていると理解していますので、子どもたちにとっては概念的で難しいかもしれないですけれども、自分たちが守られるべき存在なのだということを理解できるところまで、どのように教育の中で伝えていくのかというのを、教育だったり、保育だったり。","respondent":"三輪子ども育成課長","answer":"製本した冊子については数に限りがありますので、当然、小・中学校でしたり、義務教育学校にはお配りはするのですけれども、それ以外には、しながわこどもぽけっとのアプリでしたりとか、各種事業の実施の中で、このこども版をご紹介させていただいて、お子さん。","voiceIndex":197,"id":"exchange-062"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほども申し上げたのですけれども、概念的なので、子どもたち、大人も間違っていることがあると思います。もう１点だけ、パブリックコメントのほうで、１９番目なのですけれども、スクールカウンセラーとの面談が１か月待ちで１０分のみというご意見がありまして、学校差もあるのかと思うのですが、その辺りの現状を何かご存じでしたら教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"今後は、当然、そういう方向性で今検討が進んでいるようですので、スクールカウンセラーの配置の充実にも、東京都と連携して進めていきたいと思います。","voiceIndex":199,"id":"exchange-063"},{"speaker":"高橋（し）委員","kind":"意見","question":"子ども向けのほうについて、もうできてしまったからあれなのですが、「子ども」と「こども」と、使い分けをされているみたいです。子ども権利条約は固有名詞だから「子」なのだと思いますが、文章の中で漢字で出てきたり、平仮名で出てきたりしているのですけれども。","respondent":"三輪子ども育成課長","answer":"サイドブックスの４４ページに、すみません、概念的なところで書かせていただいておりまして、「こども」の表記につきましては本当に全世代、それから、「子ども」につきましては、乳幼児から思春期の切り分けをさせていただいているです。","voiceIndex":202,"id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"意見","question":"どうもありがとうあります。こども向けのところを読んだ子どもが、「子ども」と「こども」を見たときに、あれかなと思ったので。もうできてしまったから、いいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-065"},{"speaker":"田中委員","kind":"質問","question":"４０歳の人たちも「こども」という。そこの、こどもといったらこどもなのだと思うのですけれども、ポスト青年期以降というか、その後のおおむね３０歳から４０歳とか、青年期もそうなのですが、ここで言う「こども」というのはどういう意味でこのような定義になっているのかが、すみません、今のご説明、改めてもう一回お伺いしたいのですけれども。","respondent":"三輪子ども育成課長","answer":"こちら、すみません、用語の定義にあるとおりのところで恐縮なのですけれども、子ども、それから若者、それから、心身の発達過程にある者を含むという形で、あらゆる方を対象にしているというのが本計画です。","voiceIndex":206,"id":"exchange-066"},{"speaker":"田中委員","kind":"質問","question":"もう一回。要は、こども、いわゆる言葉が指す相手がという意味ではないということなのですか。青年期の人たちや、それ以降のポスト青年期、ポスト青年期以降の人たちも「こども」という対象になると見える表現になっているのですけれども。","respondent":"三輪子ども育成課長","answer":"この定義の大本となりますのが、こども基本法で定義がございまして、「こども」というのが、心身の発達過程にある者で、年齢の区切りを置かない概念として定義していますので、こうした表記にしています。","voiceIndex":208,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問","question":"統一されていないと思うのですけれども、基本計画だと、「こども」で平仮名とか、そこら辺との整合性というか、調整というか、統一化というか、概念的にどこかで定義ではないのですが、そういったものを国も都も含めてなのですけれども、特に東京都との関係も含めて、歩調合わせというか、調整するというかが必要なのかと思うのですが、そこは、すみません、今現在のお考えとしてお伺いしたいと思います。","respondent":"三輪子ども育成課長","answer":"委員おっしゃるとおり、国と自治体でそれぞれ使い分けが、整合性が取れていない部分があると、当然、混乱を招くと思いますので、それぞれの考え方であったりとかを改めて確認をしつつ、混乱のないような形で表記をしていく必要があると認識しております。","voiceIndex":210,"id":"exchange-068"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも質問します。以前、ご要望させていただきましたこともあり、子ども向けの冊子を作っていただいたのは、非常にありがたいと考えています。この辺りになるのです。私の発言の趣旨としては、子ども向けにやはり分かりやすいコンテンツをつくっていくことが必要ではないかと思っているのですけれども、その辺りのお考えをお聞かせいただければと思います。","respondent":"三輪子ども育成課長","answer":"学校教育の中で、どういった形で取り扱うかというところ、その辺り、何かできることはないかというのを検討していきたいと考えております。","voiceIndex":214,"id":"exchange-069"},{"speaker":"山本副委員長","kind":"提案","question":"ご回答ありがとうあります。そして、ご提案というか、私が思っているのが、やはりアプリとかを使って、質問形式だったり、することで、子どもたちがより理解が深まるようなツールをつくっていくとかというのがいいのではないか。これについて改めて一言ご答弁いただきたいのと、あと、教育委員会のほうでも、どういうお考えかというのをご回答いただければと思います。","respondent":"三輪子ども育成課長、丸谷教育総合支援センター長","answer":"委員おっしゃるように、デジタル系のツールの活用というのは、今、若い子たちにもいろいろなじみのあるようなことを考えておりますので、どういったものができるかというのは、これから一から検討になってしまうのですけれども。今後広く周知というところでは、関係課と連携をしながら、タブレットから閲覧できるとか、リンクを張るとか、そういったところでの子どもへの普及啓発というのは努めてまいりたいと考えております。","voiceIndex":216,"id":"exchange-070"},{"speaker":"せらく委員","kind":"確認","question":"今、山本副委員長の質疑に関連して１点確認なのですけれども、前回１月にお示しいただいた際に、こども版を作成し、それをＧＩＧＡ端末に入れるというようなお話を、私、自分でメモしていたのを確認しまして、それについてはどうなっているか、お伺いできますでしょうか。","respondent":"三輪子ども育成課長","answer":"そういったことができるかというところも含めて、今、確認して、取組ができるようであれば、進めていきたいと考えております。","voiceIndex":221,"id":"exchange-071"}]},{"id":"topic-08","title":"病児保育実施施設の新規開設","agenda":"病児保育実施施設の新規開設","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"いわゆる交渉をする話ですから、教えていただけるところも限度があると思うのですが、教えていただきたい。併せて、昨年度積んでいた予算が執行されなかったというのは、いわゆる交渉がうまくいかなかったからと聞いておりますが、今回、その３つのうちの１つが決まったということで、この３つの中には、昨年度交渉がうまくいかなかった施設も含まれているのかどうかというところも含めて教えてください。","respondent":"染谷保育施設運営課長","answer":"今すぐに確認は取れないところではありますけれども、今年度に関しては、本日ご報告申し上げたものを含めて、もう２施設、計３つの施設についての開設を進めてまいりたいと考えているところです。","voiceIndex":228,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。２つ確認させてください。最初の部分で、医師は常駐しないということですけれども、先ほどの手順というのは、若干説明が、登録、そういう説明がありましたが、もし病の子が預けられた場合に、何かあった場合はどういった形で、現在も保育所併設型もあるということですけれども、もう一度、どういう形でそういう子どもの対応をするのかという手順を教えていただきたいのが１つ。","respondent":"染谷保育施設運営課長","answer":"実際にお子さんの容体等がそこで変わってきた場合については、登録いただいている機関が輪番で実際に保育園に駆けつけるという対応もいただけるという話と、あと、状況に応じては救急車で搬送する、そういったような対応になってくるかと思います。","voiceIndex":230,"id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"意見","question":"今のあくつ委員のお話もありましたけれども、地図で見た、まさに空白の地域の保護者の方々は、今回、海側という話があったときに、もう少し南の海側かという感じではあったのですけれども、今交渉されている２つのところの話が迅速に、うまく話がまとまったら、ぜひもう少し南の東大井、南大井地区の方が預けることができるようにお願いしたいのですが、今年中に何とか開設などの見込みがもし分かれば。","respondent":"染谷保育施設運営課長","answer":"現在、交渉というか、調整を進めております２施設につきましても、現時点での先方との調整の中では、年度内での開設を見込んでいるです。","voiceIndex":234,"id":"exchange-074"},{"speaker":"西村委員","kind":"質問・要望","question":"１点だけすみません。親も大変な中で、子どもも高熱の中、おうちを離れるということを考えると、ベビーシッターで看護師資格を持っている方の活用でしたり、急性期もあるので、例えば、病後児なら検討できないかとか、その辺りも、新規開設とともにご検討いただきたいと思うのですが、その辺りはいかがでしょうか。","respondent":"芝野保育入園調整課長","answer":"こちら、東京都の新規事業として、東京都病児保育推進事業というのが予算化されておりまして、検証事業が始まりますので、こちらの事業、委員のご指摘のようなスキームで事業展開がなされると聞いておりますので、こちらのほうを注視しまして。","voiceIndex":238,"id":"exchange-075"},{"speaker":"田中委員","kind":"確認","question":"ご説明の中で、病児保育施設には、保育所併設型と医療機関併設型とあって、今回、保育所併設型なのだという話がありました。開設に当たっての手順をお伺いしたいのですけれども、既存の保育園として運営されていたところに、合計３,０００万円以上の予算をかけまして、１つは隔離室を含む部屋を、病児保育室を新たに設けるということです。","respondent":"染谷保育施設運営課長","answer":"現在は定員が７０名になっているところがあります。保育面積に余裕があるということから、本施設の機能強化を図りたいというところで、いわゆる余裕面積のところを活用して病児保育施設を開設していくという考え方です。","voiceIndex":241,"id":"exchange-076"},{"speaker":"田中委員","kind":"質問","question":"全体的には保育園はまだ足りないというか、新たに開設しているところが増えている中で、８０名から７０名に減ってきている、そこを有効活用するという。ここはどうでしょうか。現状のご認識を。","respondent":"染谷保育施設運営課長","answer":"病児保育に関してお話をしますと、現状の需給状況で見たところ、先ほどからご説明をさせていただいている今回ご報告と、それから、そのあとの２施設、こちらを開設することによって、地域の偏在をカバーしつつ、併せて全体の需給状況、区におけるニーズについても、ある程度。","voiceIndex":243,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問","question":"ぜひその残り２施設、実現できるように、引き続きのご対応をよろしくお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-078"}]},{"id":"topic-09","title":"の３のその他","agenda":"の３のその他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"これも各種委員会等で、私どもの会派からもご指摘というか、質問させていただいたところがあるのですが、当初はそこにカフェをつくるというコンセプトがあったと思うのですが、それがなくなってしまったということに関して、ここについてはどのようにお考えになるのか。無料だということですけれども、駐輪場、駐車場等があるのであれば、そこの利用料についても教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"テラスのところにも同様に座れるスペースをつくるということで、まず、座ってゆっくりできるスペースの確保を進めています。食べ物に関しては中で購入ができないのですけれども、飲み物の自動販売機は設置しております。","voiceIndex":250,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問","question":"これは八潮地域の方を中心に考えられた施設ということですが、今、八潮には高齢者がとにかく多いというお話があって、高齢化率が３５％ですか。カフェもできなかったということですから、残念だと思うのですが、そこについての、まず、どなた向けの施設なのかというところ、どなた向けというか、どの地域の方に向けた施設なのかというところを一つお伺いをしたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"そういった資源というところも認識しておりますので、コラボレーションではないですけれども、何か一緒にやっていける、それから、地域の方々が求めるような形で食事も提供できればということで、いろいろと検討を進めてまいりたいと考えています。","voiceIndex":252,"id":"exchange-080"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。私が読み取れていないのかもしれませんけれども、オアシスルームについて、ほかのオアシスルームは、定員が何人で、０歳・１歳は何人までと書いてあるのですけれども、こちらの定員はお問合せをすれば分かるのでしょうか。ホームページに一覧表を載せることになるのでしょうか。このチラシに定員がないと思うので、すみません。","respondent":"柴田子ども施策連携担当課長","answer":"ちなみに、５月１日からすぐ使えるように、４月の中旬から事前登録の面談などは実施していますので、八潮地区、もしくはその近辺で使いたい方に関しては、既に面接にいらしているというお話も聞いておりますので、そういったところも併せて丁寧にご案内等を進めてまいります。","voiceIndex":256,"id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問","question":"丁寧にご案内していただいているのはいいのですけれども、定員が何人なのか分からないのですが、まだ決まっていないのですか。","respondent":"柴田子ども施策連携担当課長","answer":"申し訳ございません。今、手元の資料をめくっていたのですけれども、明確に私が把握し切れていないもので、後ほどご案内します。","voiceIndex":258,"id":"exchange-082"},{"speaker":"山本副委員長","kind":"質問","question":"私からも質問します。このような施設、とてもいいものだと思っておりまして、すごく私も楽しみにしております。できた後に、利用者の方々に満足度とか、何かご意見を聞くアンケートというのをご予定されているのでしょうか。今後さらによくしていくという意味でお伺いします。","respondent":"柴田子ども施策連携担当課長","answer":"実績報告等についても、お時間いただければ、させていただければと考えております。アンケートについては、検討という形で進めてまいります。","voiceIndex":261,"id":"exchange-083"},{"speaker":"山本副委員長","kind":"質問・要望","question":"その質問項目の中で、やはり先ほどあくつ委員からもお話がありましたけれども、地域の方々、どのような方々がいらしているかというところが分かるように確認していくこともすごく大事なのではないかと思いますので、八潮の近隣の方々が来ているのか、遠方から来ているのかというところについても分かるように確認していただきたい。そういったことも含めてぜひ検討していただきたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7019#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":66361,"voices":265}},{"id":"r07-20250415-5","meetingId":"r07-cm04","date":"2025年4月15日","dateIso":"2025-04-15","committee":"総務委員会","time":"午後 １時００分～午後 ４時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員の異動","agenda":"幹部職員の異動","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、雨水排水能力の増強ということですが、下水管が太くなるということなのですか。管きょ更生工法ということで、下水管の内面を樹脂材で補強すると、これは補強するということで分かるのですが、排水能力を増強するとありますが、これは太さを変えることなのでしょうか、教えてください。","respondent":"佐藤経理課長","answer":"排水能力の増強についてですけれども、委員ご指摘のとおり、古い下水管の入替えの際に径を太くするということで、例えば２５ｃｍのものを３５ｃｍに入れ替えるとか、そういったことで排水能力を増強すると聞いております。","voiceIndex":28,"id":"exchange-001"}]},{"id":"topic-02","title":"品川区総合実施計画の改定","agenda":"品川区総合実施計画の改定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この製本なのですけれど、横ですね。それで、左側の短いほうをとじて、こう見る感じなのですか。ごめんなさい、非常に慣れなくて、だから、普通このぐらいの大きさだとすればこうではないですか、それでこうではないですか。だけど、こうなるの、少しそこら辺、まず教えてください。","respondent":"崎村企画課長","answer":"今回、Ａ４横判で製本させていただいておりまして、今、委員お話しのように、横判の左側をとじて右からめくっていただくような形になります。","voiceIndex":35,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"この目標値というのは、今後どうするのですか。一応、３つの重点項目というのがあって、そこでいろいろと振り分けているのは分かるのですけれども、だから何、というところがあって、品川区全体としてどういう方向に持っていくのですかというのがなかなか見えないのです。なので、もう少し、とがったというのですか、政策であってもいいのかなという思いがあるのですけれど、何か特徴が見えない。","respondent":"崎村企画課長","answer":"こういった計画事業を進めることによって、区民の幸福度ですとか、生活満足度を引き上げていくといったところが大きな目的となっておりまして、令和５年度に行った区民アンケートですとか昨年度の世論調査でも、この辺の幸福度、生活満足度を算出させていただきましたけれども。","voiceIndex":37,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"だから、その返済も含めると、品川区の全体の財政状況、どうなっていくかというのを多分見やすくしておかないと、見直していかないと、非常にあれもこれもそれもみんな借金だらけになると、結局は返済できないよね、みたいな状況に陥るといけないので、そういう財政的なシミュレーション、これはいろいろな方がお話しされていましたけれども、そういうものを手がけるというのはあるのでしょうか。","respondent":"崎村企画課長","answer":"今回は、総合実施計画ということで、５年間の財政の見通しについて記載させていただきましたけれども、そういった今後の投資的経費の増大、また、新庁舎に係るお金等もありますので、こういったことについてはしっかりと。","voiceIndex":39,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"分かりました。これ、毎年見直しを図っていくのでしょうか。これ、５年間ですけれど、年度の目標を立てて、見直しを図っていくという手法、今までもやっていたと思うのですけれど、それは今後も続けていかれるということで、だから例えば、１年やってみて来年度どうなったか、それでまた修正をかける必要があるので修正をかけていくとかという方向になっていくのか、それだけ教えてください。","respondent":"崎村企画課長","answer":"実施計画については、事務事業評価もありますので、しっかりとその評価というのは行った上で、まずはこの総合実施計画というものを毎年度改定していくかというと、そこについては検討が必要かなと思いますけれども、必ずその実施計画事業については、評価、また。","voiceIndex":41,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"財政収支のほうですが、投資的経費、今、西本委員からもありましたけれど、実際、２０２５年度が４９０億円余ですか、近年は少し増えているのですけれど、２０２７年度が６７０億円余ということですが、こんなものでは足りないのです。新庁舎自体が実際今、約倍近くなっている。大変だったと思います。先ほどの質問に対してお答えください。","respondent":"崎村企画課長、加島財政課長","answer":"年代ですとか性別、またその家族の状況によって違うかと思いますけれども、そういったところを含めてクロス集計等々の手法を用いながら、どういった年代が特にどの分野の幸福度が高いのかですとか、お子様をお持ちであるだとか。そこで発生したインフレスライド分について、対応できるように財源を考えていくとともに、減債基金につきましても３０億円ずつ、２５億円が新庁舎、５億円が学校改築という形で先々積立てを行いまして。","voiceIndex":44,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、この財政収支の中で投資的経費というのを少し甘く見られているのかなと。もっとやはり多く出すべきではないのかなという、要は、それは何が根拠かというと、今回の新庁舎が約２倍になっているなら、投資的経費もおのずと２倍近く跳ね上がって、ここに計上するべきではなかったのかなと少し思ったもので、それで質問をさせていただいたところです。","respondent":"加島財政課長","answer":"投資的経費のところにつきましては、私たちも決して甘く見ているわけではございません。今回の予算編成におきましても、起工時につきましてインフレスライドを見込んだ予算編成というのを行っております。それは先々においても同じことです。","voiceIndex":47,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"須貝委員の質問の答弁で、起債に関していろいろこの償還の計画が今、立てられているということで、要は全体が見えないのです。なぜなら、学校改築もやっているし、いろいろな借入れをしたりとか、起債したりとかといって、その償還はどうなっていくのかというのが全然見えないのです。それらの全体の返済というのはどうなっているのかというのを、少しまとめてもらうことはできないのですか。","respondent":"加島財政課長","answer":"償還計画につきましては、予算特別委員会資料の中で、これまで借り入れた分、定期償還、満期一括償還も含めて、そのときの元金払い、利払いというのを表示していますので、こちらが計画になります。","voiceIndex":50,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"それで、どこの部分がどういう返済になっているかというのが、あの表だと個別が分からなくて、予算書の中のものは全体が入っているので、それぞれのものがよく見えないのです。例えば、学校改築をやって、それ、今も計画が立っていますね。それと、それがどういう財源を使ってどこが起債になっていて、それがどのぐらいで返していけるのかという、全体でなくて個別というのが難しいものなのですか。","respondent":"加島財政課長","answer":"議会にお示しする資料といたしましては、全体の償還計画を今、提出させていただいているところです。個別につきましては財政課で管理をしておりますので、今現在、議会に提出する予定はございません。","voiceIndex":52,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"細かい数字というのは、別に細かいところまで必要とは思わないのですけれど、当然ながら、財政課にはあると思うのです。それが出せる状況まで、概要でもいいのですけれど難しいのでしょうか。全体ではなくて、学校改築とか、どこの改築とか、庁舎建て替えとかとなったときに、それ全体の借入れ、それから返済とかというシミュレーション的なものというのは、お示しは難しいでしょうか。","respondent":"加島財政課長","answer":"今現在は、先ほど申し上げたとおり償還計画の中でお示しすることを考えております。カテゴリーごとに示せないかというのが委員のご提案の趣旨かと思うのですけれども、こちらのほうにつきましては、今、財政課で管理するという方向性でやっております。","voiceIndex":54,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"では要望だけ言っておきます。なので、今は難しいかもしれないのですけれど、ぜひ検討していただいて、結局、透明性があるというか分かりやすい金額提示をしていただけると、こちらもいろいろと考えやすいかなと思っているので、一つの検討という形で今後お願いしたいと思っています。これは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-011"}]},{"id":"topic-03","title":"中高生リバースメンターの募集","agenda":"中高生リバースメンターの募集","exchanges":[{"speaker":"松本委員","kind":"質問","question":"リバースメンター、実際にやっているところを見ると、群馬県などがあるかと思って、単独でやっているわけではなくて委託という形でやっていて、よく出てくるのが、芸能活動をされている、たかまつななさんの笑下村塾というところがやっているというのを見るのですけれど、今回はそうした、どこかに委託するということなのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"事業者に委託をするのかどうかというご質問ですが、本件は、中高生の検討会４回のファシリテートですとか、その間の中高生個別の伴走支援などについて、専門的な知見を持つ事業者に事業の支援を委託する予定です。","voiceIndex":62,"id":"exchange-012"},{"speaker":"松本委員","kind":"提案","question":"せっかく時間を取ってもらって提言してもらっても、結局、ああ、よかったですね、みたいな感じで終わるというのがすごく難しいところだと思います。それで、ここでお伺いしたいのが、各メンターの方たちが、これが課題だと思ったときに、その課題を担当している、所管されている部署の職員の方たちとどのくらい接点を持つ機会があるのかというところをお伺いできたらと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員ご指摘のようにパフォーマンスで終わってしまうというようなことがないように気をつけて、そこについては今後、検討を進めていきたいというところではありますが、まずは、検討会４回の中で、検討会の詳細につきましてはこれから検討していくのですけれども。","voiceIndex":64,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"だから意味があるのです。なので、４回程度でできるのかという話です。１０人集まって、ではみんな、１０人とも違う課題を、となって意識を持って、１０人いて１０項目それぞれがやるのですか、ということになりますよね。これ、学校で今やっているのだから、それをもっと、品川区に、行政などに意見が言えるような道筋をつくってあげるほうが現実的ではないのかなと思うのですけれど、いかがですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区の職員がサポートに入ったりすることによって、区の職員は教員ではございませんので、学習、教育にたけてはいないので、自発性を阻害してしまうのではないかというようなご指摘もございましたが、その辺りは区の職員、入る前にはきちんと研修をしまして。","voiceIndex":67,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"どういうことをされているのかというのをまず見てほしいと思います。ここは文教委員会ではないですから分からないとは思いますけれど、でも、かなり進んでいる学校もあります。これをたかだか４回ぐらいやって、それで、はい、やってきました、区長の前でプレゼンしました、いいですね。これは私の意見なので別に、これはこれでやるのでしょうから。これは意見なので、別に答弁は求めませんので結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"今の西本委員の意見も確かに一理あるかと思うのです。ただ、普通の中学生・高校生が区長に提言、自分の考え方を発表できる、プレゼンできるというのは、その子たちにとってはある意味、チャンスであり、勉強になるのではないかなと思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"この観点で、もちろん教育でいろいろな学習で、それを区と連携しながらやっていく、教育委員会として区長部局と連携しながらやっていくというのは、すごくこれもいいアイデアだと思うのですけれども、このリバースメンター制度について教育の観点だけではなくて、区としてこれをうまく活用してよりよい区政につなげていくという観点のほうからも一言いただければと思いますが、いかがでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今、委員からご指摘がございましたように、リバースメンター、そもそもの側面としては、メンターを逆転するというところで、民間の企業などですと、従来は先輩だとか上司などが若手職員の相談役となるという制度でしたのを逆転して、若手職員が上司や経営層に対して。","voiceIndex":71,"id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"やはり大事なのは、パフォーマンスで終わらないためにはどのくらい、先ほどの資生堂の例もありましたけれども、資生堂がやってきた、あるいはほかの、企業に限られませんが組織がやってきた利点というのを吸収できるか。そういう意味では、今あるパッケージとしてのリバースメンターではなく、品川区としてより区政に反映できるような形でのやり方というのを考えていただければなと思います。以上、意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問","question":"新たな試みということで、１０名の区民、中学生・高校生相当の年齢の方ということで人選されるということなのですが、これ、委託をしているということでありますけれども、この１０人の人選に当たっての、この１０人を選ぶところもこの委託の事業者がやるということでしょうか。そこをお聞きしたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"リバースメンター、中高生１０名の選定主体についてのご質問ですが、リバースメンターの募集、それから選定については委託事業者ではなく、区が実施する予定です。","voiceIndex":75,"id":"exchange-019"},{"speaker":"新妻副委員長","kind":"提案","question":"区が人選と。ここに提案のテーマとして２つ掲げられておりますが、特に、ここにはかかわらず、区政に対する全般の何でも受けていいというふうに募集されると思うのですけれども、この１０名の、どういうふうに、どこで、ホームページとかそういうところで募集されると思いますが、より多くの方の目に触れられるというところでは、学校側への情報提供があるのか、どういうふうに人選をしていくのかと。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"応募者の方の選定基準、それから作文の審査は誰がやるのかというご質問ですが、まず、作文の審査については区の企画経営部の管理職を中心として実施する予定ですが、応募人数がかなり増えた場合については、書類審査、１次審査。","voiceIndex":77,"id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"本当に、子どもたちの発想、こんなことを言うのかという、私たちが気づかない視点でこの作文が上がってくるといいなと思うのですけれども、その基準の段階で、できることだけのことを言ってきている人の、そういう作文を選ぶのではなくて、本当に区がこれからこういうところは力を入れていかなければいけないよね、今までになかったなという、そう、一歩突っ込んで言ってくれるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"国で何かそういう、メンターに教える、さっきのお話を聞いていると、要は教えるにも教え方が多分あるのでしょうから、そういったものは国で決まっていた、何かそんな内容みたいなものがあるというご答弁が確かあったのですけれど、どんなものなのかなというのを教えていただきたいのと、例えば１０人に対して教える人は、何人ぐらいでやっていくのかなとか、そこら辺何かあれば教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２点目として、１０人の中高生リバースメンターに対して何人ぐらいの職員をですが、こちらも、子どもたちから上がってきた政策のテーマや、各部署の体制なども含めて今後検討してまいりたいと考えています。","voiceIndex":81,"id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問","question":"新しい事業ということは、そこにやはり職員が取られるわけなので、例えば、繁忙期があったときにはそういうところもいろいろ職員の負担にもなる部分も多いと思うので、応募があったときは柔軟に人を増やす、でもやはりなかなか人を増やすのも大変でしょうから、職員に負担がかかり過ぎない、それでもこの事業は成功させてほしい、難しいですけれど、そこら辺。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-023"},{"speaker":"大倉委員","kind":"確認","question":"いろいろお話を伺っていて分かりました。区は４月からお知らせをして、１か月ぐらいで課題感を作文して、それで９月までに４回ということで検討会を行って、結構、スケジュールとしてはタイトなのかなという感じがしたのですが、どうしてこういうスケジュールなのかというのは、予算プレスを見ると９月から事業化が検討されると、ここに合わせてやっているのだろうなというところでいいのかということの確認。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"この検討会は全体で進めるものですが、これとは別に、１０名の中高生リバースメンターそれぞれ、その間も宿題であったり、政策をより検討していたり、調査をしたりということもありますので、選ばれた１０名にとってはかなりタイトなスケジュールになるかとは思いますが。","voiceIndex":84,"id":"exchange-024"}]},{"id":"topic-04","title":"コンプライアンス推進のための取組み","agenda":"コンプライアンス推進のための取組み","exchanges":[{"speaker":"西本委員","kind":"意見","question":"いざこざをしている方がかなりいらっしゃって、警察も来ますね。そこでもめるということは何がいけないのだということなのです。このご時世なので、あるのは当然だし、つくるのも当然なのですけれど、でも、具体的な窓口業務などをやったときに、なぜそういう、もめてしまうのかということに対しての分析、どうあるべきだったのかという、そういうものは、これをつくるに当たって検討はされていますか。","respondent":"川村コンプライアンス推進担当課長","answer":"関連しまして、コンプライアンス推進基本方針や行動規範のほうにおきまして、まず、区民に対し誠実に公正かつ適正な対応が必要だということで、職員の意識を高める旨の指針も示しておりますので、今後。","voiceIndex":91,"id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"それで、それを受け止めている、人事課かよく分かりませんけれど、あると思うのですが、やはりきちんと言う勇気、それはもう、守っていますよということもきちんと、そういう気風がないと、職員からも庁舎の中で何でも言えるような、相談できるような状況になっていかないと、なかなかうまくいかない、辞めていく人も多くなってしまうと思うのですけれど、その意識の問題、それから。","respondent":"川村コンプライアンス推進担当課長","answer":"コンプライアンス推進担当、一つの部署で行えることではございませんが、まず、コンプライアンス推進の取組の中に、今年度研修を予定しております。組織のトップのほうからの意識改革も含めまして、職層に応じた研修を行っていけるように検討してまいります。","voiceIndex":93,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、それを救うという救済措置というのはきちんと示して、何かあったら言ってくださいねという、そういう部署であってほしいなと思うのです。やはり１人で悩んでいる方もいらっしゃると思う。議員は議員できちんと、こういうところでも私、これまでにも結構声が高くなったりなどしますから、カスハラと言われてしまうのかなとすごく心配になってしまうのですけれど、それはいかがでしょうか。","respondent":"川村コンプライアンス推進担当課長","answer":"最後のご質問に関しましてですが、議員の方も区の職員も、区政のよりよい実現に向かって建設的な議論を交わしていると捉えておりますので、そこはカスタマー・ハラスメントではないと考えています。","voiceIndex":95,"id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"別の自治体でこうした基本方針などを拝見すると、各窓口にもボイスレコーダーを配置しますということが明記されているところもあるのですが、品川区の場合は、ここは窓口におけるボイスレコーダー、録音機の対応というのはどのようになる予定なのか、お伺いできればと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"ただ今後、必要性などを現場からの要望に応じて検討してまいりたいと思いますし、現状ですと、事業の実施に当たってレコーダーを持っている課につきましては、そちらを利用していただく想定です。","voiceIndex":98,"id":"exchange-028"},{"speaker":"松本委員","kind":"質問・要望","question":"今のところでやはり、ある程度カスハラが想定できる部分については配置しておくということが大事ではないかなと思って、対応方針としてはあっても、いざ何か起こったときに、職員の方が自分のスマートフォンを出して録音するというのは、それはそれでまた、いろいろな問題が出てくると思いますので、今回、予算化を多分されていないからすぐには難しいかもしれませんが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"これ、品川区においては、例えば職員が全部最終的に判断されるということならば、その後に第三者機関が入る余地があるのか、それともそういうものは一切入れないのかという、その２点だけ教えてください。","respondent":"川村コンプライアンス推進担当課長","answer":"いざ、もっと大きな問題に直面したときの第三者委員会などの設置につきましては、今後の検討課題かなと思います。","voiceIndex":102,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"今の組織内で弁護士資格をお持ちの方が、一応判断というか相談に乗っていただいて判断されるということですが、そうなるとあくまで組織内という、いつもなあなあで話している、そういうやはり、きちんとした客観的に見える状況ではなくなってしまうのではないかなと思うのですが、その辺についてはどのようにお考えですか。","respondent":"川村コンプライアンス推進担当課長、柏原区長室長","answer":"ご心配の趣旨は理解できますけれども、大変職務意識の高い推進指導員に携わっていただいておりますので、その辺りはご心配ないように……。そういったところでの事案も含めながら、これは区の中だけの部分では、判断なり何なり厳しいというものであれば、それはもう第三者的な機関を場合によっては設置して、判断をもらったりなどというものが出てくるのだろうと。","voiceIndex":104,"id":"exchange-031"},{"speaker":"須貝委員","kind":"意見","question":"恐らくフジテレビでも皆さんそういうふうにやっていたと思うのですけれど、ただ実際、いざとなると、どうしても内部で収めてしまう。そういうことが往々にして多いので、民間企業では第三者機関に通報または相談というのが今、普通の仕組みになっているようなので、それだけ少し意見として言わせていただきます。","respondent":"柏原区長室長","answer":"それで、もっと大きな部分で、今回のフジテレビの部分に関しては内部の動きのところがどうだったかというのはあろうかとは思いますけれども、区としてはそういった外の相談ができる制度などを持ちながらですので、そういったものを持ちながら、足りない部分があれば。","voiceIndex":107,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"なので、そこは、某県の状況にはなってほしくないので、あれは少し異常だと思いますけれど、でも、やはり命を落とすぐらいのことが起きてしまっていることを考えると、やはり第三者機関などというもので少し別枠で、品川区の職員ということではなくて、別枠でそういう逃げ込むところ、頼れるところというものをつくっておいたほうがいいのではないかなと思いますけれど、今あるのですか。","respondent":"川村コンプライアンス推進担当課長","answer":"調査委員会などについてはやはり、先ほどの重複になりますけれども、事案に応じた判断が生じる場合もあるのかなとは考えております。","voiceIndex":109,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"これは本当にお願いです。職員の方々がいろいろ失敗することも多々あると思うのです。もう自分の思いが伝わらない、やはり理不尽なことをされました、そういう形、なかなかその解決が一人では見いだせないというような状況になってしまうと、精神的に病んでしまったりしてしまうので、そうならないように救済措置はきちんとあるということは、職員の方々に知ってほしい。","respondent":"柏原区長室長","answer":"そういったことが何もない職場というのが一番大切なのですけれども、そういったことが起こってしまった場合に、職員も言いやすい環境であったりとか状況というものをきちんとつくっていくというのが我々の役目だろうと思っていますので、その辺は努力します。","voiceIndex":111,"id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問","question":"そういうのは控えましょうという議長からの話があったりなどという部分があって、要は区民だけではなくてやはり議員からのハラスメント、カスハラになるのですか、そういうものというのも、これから先、今はコンプライアンス推進の取組で職員と区民という部分があるのですけれど、例えば、これから先は、議員もそうだと思いますし、そういったコンプライアンス推進の先にどう広げていくのかなという。","respondent":"川村コンプライアンス推進担当課長","answer":"対応要領、厳密に言えば、行政サービスの利用者等の「等」の中にいろいろな方が含まれておりますので、一概に区民の方とは申しませんけれども、そこはお互いのコンプライアンス意識の醸成が必要かと考えています。","voiceIndex":113,"id":"exchange-035"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"これは何かあるのではないのかなと、素人目にぱっと思ったりするときも、例えばの話ですけれど、そうすると、ハラスメントが何かあったのかなとふと思いますが、そういうものはやはり、職員の中で言えることはやはり難しいのかなと、我々議会も誰に言っていいのかなと、例えば私がそう感じたときですよ、部長だからとか勝手に思ったりすると、部長には言えないし、では誰に言ったらいいのかなというのが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-036"}]},{"id":"topic-05","title":"「デジタルプラットフォーム」を活用した区民意見募集の結果","agenda":"「デジタルプラットフォーム」を活用した区民意見募集の結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これ、今後いろいろなテーマで、このデジタルプラットフォームで意見を聞くよという理解でいいでしょうか。当然ながら、今回は防災訓練で防災課とのフィードバックという形になると思いますけれど、これ、テーマはどういうふうにして決めるのですか。","respondent":"與那嶺戦略広報課長","answer":"今後のテーマの設定についてのご質問です。委員おっしゃるとおり、今回は防災訓練で実施をしましたけれども、今後は区政の様々な課題について、こういった意見を聞いていくような使い方をしていこうと考えています。","voiceIndex":122,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"もちろん、庁舎の中でこういうものを聞いてみたいというのがいろいろな部署のほうから出てくるので、それから決めるのだろうなと思いますが、このコメント投稿数の中に、公開基準に合わないコメント１３件、これ、どんな類いのものなのですか。","respondent":"與那嶺戦略広報課長","answer":"今回行った調査については、試行実施という形で、実際に既に事業を行っているところのプラットフォームを活用したので、そこの事業者の基準に少し準拠した形ではあるのですけれども、例えばどういったことが基準になるかというところで、先ほどご説明申し上げたように。","voiceIndex":124,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"分かりました。当然ながらあり得ますよね。そこはもうその部署で責任を持って考えるという形ですか。ここは、デジタルプラットフォームを使ってこういうものを上げるというだけの企画であって、その結果を部署に渡して、あとはそれを使うかどうかというのはその部署が考えるという使い方になるのでしょうか。","respondent":"與那嶺戦略広報課長","answer":"今回の意見を受けて、いかに活かしていくかというところなのですけれど、まず、実際に施策に反映していく部分については当然、原課になる部署のところで検討、ご判断いただくところにはなるのですが、我々のところも、ただ渡しておしまいというわけではなくて。","voiceIndex":126,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"確かに意見がこれだけ出ていて、こういう企画をすればいいのではないのですかという話なのですが、新たな防災イベントの実施とか、マンションを対象とした訓練の検討とか、町会・商店街の防災イベントの検討とか様々な、恐らく地域によっては、やっていると思うのですけれど、今回は、これからどうするというより、取りあえずこういう募集ということを区民にお願いをしたと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-040"},{"speaker":"新妻副委員長","kind":"質問","question":"防災訓練だから応募が多かったということなのか、デジタルプラットフォームであったから意見があったのかという、そこら辺の分析をどうされているのかというところをお聞きしたいのが１点。６０代以上の方が２０％いたというところでは、今後の高齢者向けの、このようなデジタルに関する部分が何か、また検討されていくところがあるのかというところをお聞きしたいと思います。","respondent":"與那嶺戦略広報課長","answer":"この１１７件の意見が集められて、他自治体に比べて多いと評価しているという件なのですけれども、こちら、今回実施に当たった事業者と、この取組についてのレビューをしていくという中で、大体こういった意見募集を行うときに。","voiceIndex":131,"id":"exchange-041"},{"speaker":"新妻副委員長","kind":"意見","question":"こういうことを品川区がやっているということを知っていない方もまだまだいらっしゃると思うので、今年度も行われるに当たっては、こういう意見の募集をやっているのだということをより多くの人に知っていただけることも大事だと思いますので、そこら辺もまた取組をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-042"},{"speaker":"大倉委員","kind":"質問","question":"分かるのかどうか分からないですけれど、教えてもらえたらと思ったのですが。そう考えると、なかなか中学生１人、大学生２人というところではアクセスしたけれど、少し面倒くさいから答えないというようなことがあることもあるのではないかなと思ったのですが、何かその辺の分析などはあるのですか。","respondent":"與那嶺戦略広報課長","answer":"なので、まずこれを知ってもらう取組、それは、ほかの委員の方からもあったとおり、非常に大事な仕組みかなと思っていますし、実際、今回、６０代以上の方からも投稿いただいて、そこは多分この取組があるということを知っていただけたということだとは思いますので、まず。","voiceIndex":134,"id":"exchange-043"},{"speaker":"大倉委員","kind":"確認","question":"一点、アクセス数などが分かればさらに分析できるのではないかなというところでいうと、今取っていないということは、取れるけれど取っていないのかというところの確認だけさせていただければ。","respondent":"與那嶺戦略広報課長","answer":"ここは新たな業務実施に当たってまた、契約などを行ってまいりますので、そこの部分で、これが可能かどうかというところも含めて確認を取ってまいりたいと思います。","voiceIndex":136,"id":"exchange-044"},{"speaker":"大倉委員","kind":"確認","question":"確認していただいて、アクセス数が、先ほど考えられ得る懸念としてお伝えしたと思うのですが、アクセスするけれどアンケートまで行かないとか、そういうところがあったら何か課題としてさらに考えられるかなと思ったので、確認して、ぜひそういうことも分析に入れていただければいいかなと思いましたのでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-045"}]},{"id":"topic-06","title":"都市ブランドデザイン","agenda":"都市ブランドデザイン","exchanges":[{"speaker":"西本委員","kind":"質問","question":"さきにいろいろご説明いただいた経緯があるのですけれども、改めて質問を幾つかしたいのですが、なぜゆえに、株式会社ヘラルボニーなのでしょうか、ということと、周知の方法を、区民の方への周知はどうされるのかを教えてください。","respondent":"與那嶺戦略広報課長","answer":"ヘラルボニーが制作パートナーとなった理由ですが、今回、都市ブランディングの事業全般といいますか、こういった制作に当たっては、先般報告したとおり、事業者に協力していただきながらこういった制作を続けてきたということで、その中で。","voiceIndex":144,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"これ、いろいろなところに公募みたいにしたのですか。品川区と何かしら関係があったからとか、という、その辺はどうでしょうかということと、これ、使い方はいろいろ出てくると思うのです。色を変えてはいけないとか、スペースの問題とか、どの辺にこのロゴを使えるのかなどといろいろ細かい規則が出てくると思うのですけれど、それについてはどう告知されるのかということです。","respondent":"與那嶺戦略広報課長","answer":"作成の中で確かに様々なところはございましたが、いざこういった形で決めてしっかりと表に出したというところについては、しっかりと自信を持ってお示しできるデザインになったと考えています。","voiceIndex":146,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"分かりました。どういう観点でこれがつくり上げられたのか、特に、このロゴの由来は、というようなところはやはり、シティプロモーションの「わ！しながわ」は分かりやすかったのです。周知をするためにはそれなりのプロモーションをしなければいけないのは分かるのですが、でもやはり、なるべく税金を使わないような方法を考えていただきたいなと思いますが、その辺はどのような工夫をされますでしょうか。","respondent":"與那嶺戦略広報課長","answer":"最初のステップとしては、５月１日号の広報紙に、ブランディングについて３面ぶち抜きのような形で特集記事を予定しておりまして、そこのところで、まさにこの「アート」「ロゴ」「メッセージ」というところを、どういった観点で思いを持ってつけているか。","voiceIndex":148,"id":"exchange-048"},{"speaker":"新妻副委員長","kind":"確認","question":"記者発表のときにも総務委員にご案内をいただきましたので、参加をさせていただいて、この作品を見させていただきました。それが今後、ご本人の作品をどこかに掲示していくとか、お披露目をすると、区民が見られるような、そういう場があるのかというところを１点確認と、ノベルティグッズの製作というものがありますけれども、これは、このヘラルボニーがやっていくということでしたでしょうか。","respondent":"與那嶺戦略広報課長","answer":"これは今後の目指すところではあるのですけれども、例えば地域の方であるとか企業の方と連携をしていく中で、このブランドアートやブランドデザインを使ったグッズを作成するであるとか、そういったこともできたらいいなと、そのように考えてあります。","voiceIndex":151,"id":"exchange-049"}]},{"id":"topic-07","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これ、発生日というのと、何年間返済がなかったら、それを債権放棄というふうに、これは年数で決められるのですか。その仕組みをもう少し教えてほしいのですけれど。","respondent":"品川会計管理者","answer":"２番のケースに関しましては、返済開始から１０年間を基準として、時効ということを判断しております。","voiceIndex":157,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"そうすると、２番のケースのようなものは、１０年間たてば返さなくていいという仕組みになっているのですか。１番目のほうは、生活困窮という状態で返済できるという状況ではないということなのですが、この判断の期限というか、このぐらい待ったけれど無理ですというのは、何年ぐらいで判断することになるのでしょうか。","respondent":"品川会計管理者","answer":"基本、このケースについては１０年というところなのですが、様々な債権の種類によって時効というのも違いますし、それから時効を援用する、しないとか、そういったもろもろのケースがあります。","voiceIndex":159,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"いろいろな理由があって難しいというのがあるので、こういう措置があるということは理解はできるのですが、令和７年度では給付型の奨学金など、品川区はやっていくではないですか。時期は少しずれているかもしれないけれども、それを考えたときに、これはいいのです、もちろん支払わなくていいという形になっているので。だけれど、こういう方は結構今、いるのではないかと思うのです。","respondent":"品川会計管理者","answer":"それぞれの所管のケースのところでいろいろあるということで、件数については、現在私のほうで把握はできていないのですが、奨学金については平成３０年の制度改正によって、返還免除の制度も導入したということで。","voiceIndex":161,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"いろいろなケースがあるのだろうと思うのですが、ただ、品川区、今の制度からいうと免除という措置も取れている部分があるので、ですからやはり平成３０年の前の人たちに対して、とても大変だというのであれば、そこもカバーするということがあってもいいのかなと思います。なぜなら、もう今は給付型の奨学金をやると品川区が言っているわけだから。検討していただく可能性はありますでしょうか。","respondent":"品川会計管理者","answer":"個別のケースによっていろいろあると思いますので、まずはこういう制度にのっとった形で、そういう状況もいろいろ勘案して判断するところが、審議会という場所がありますので、こういったところで時効の判断、放棄の判断などといったものをしていくという考えです。","voiceIndex":163,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜなら、品川区でもう、給付型の奨学金をやると言っているのだから、だったら、ここだって、仮に条件が合う人がいるかもしれないし、救済という意味でいったら助けてあげる必要があるのかなというところがあるので、そこは制度がそのときの制度でしょうというのではなくて、今は品川区がこういう制度になってきているということを考えれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-054"}]},{"id":"topic-08","title":"公職選挙法の一部を改正する法律","agenda":"公職選挙法の一部を改正する法律","exchanges":[{"speaker":"西本委員","kind":"確認","question":"何かよく分からないのですけれど、まず、Ｉのほうなのですが、これ、具体的にどんなものがよくてどんなものは駄目ということなのか、例があったら言ってほしいなと思うのです。それがあるということなのですか。なので、一つは、どんなものが駄目で、それを確認するのは、事前の提出、もちろんいろいろあると思うのですが、そこで確認するのでしょうか。そこを教えてください。","respondent":"今井選挙管理委員会事務局長","answer":"ですので、判断につきましては先ほど申し上げましたとおり、ガイドラインの作成などのやり取りもございましたが、それにつきましては、ガイドラインについては特につくる予定というのは、国会の答弁ではございませんでした。","voiceIndex":171,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、すみません、インターネットの規制というものをもう一度確認をさせてください。でも、そのほかに規制というのは何か、今の時点であるのかどうかというのを教えてほしいと思います。それから、IIの２、これも意味がよく分からないのですけれど、長さ４２ｃｍ、幅４０ｃｍ以内というのは、これは令和８年度からになりますが、区議選もこの大きさになるという理解でよろしいでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"どちらかというと、プラットフォーム事業者に、情報流通プラットフォーム対処法のほうで、なるべく速やかに削除を求める規定が今回、審議されておりますので、そのような形で、今検討されているという認識があります。こちらはまだ、ＳＮＳの利用については審議中です。","voiceIndex":173,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7027#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":56584,"voices":178}},{"id":"r07-20250416-14","meetingId":"r07-cm04","date":"2025年4月16日","dateIso":"2025-04-16","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時５７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました。総括質疑の中でも確認をしたのですが、もう少し詳しくご説明いただきたいというところが幾つかあるので、確認をしていきます。意地悪く言うならば、そもそもＢＴＯ方式ありきだったのですかということがこれから問われる可能性があるので、そこについて、ここにも説明がありますけれども、言っていることはよく分かるのですが、もう一度丁寧にご説明いただければと思います。","respondent":"吉岡政策推進担当課長","answer":"こういった部分のところから、こちらの記載をさせていただいているとおり、ＢＴＯ方式の採用を検討したというところで進めているです。","voiceIndex":21,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"そういったこともあったと思うのですが、現段階でのサウンディング調査、そしてサウンディング調査をかけたのは、関心を示しているところや実績があるところというような、そのような認識なのですけれども、今どれぐらいの事業者から聞いているのか、どれぐらいの数の事業者が関心を示しているのか、もし教えていただける範囲があるならば、教えてください。","respondent":"吉岡政策推進担当課長","answer":"昨年の秋口にサウンディング調査を実施いたしまして、こちら５１ページに少し内容を書かせていただいているところですけれども、実際に整備、あるいは運営をしていく事業者に対して、１０社程度サウンディング調査を行ったです。関心ありと答えた企業が７割程度、７社と。","voiceIndex":23,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"私どもが視察に行ったところのＳＰＣは、前にも款別審査のときに申し上げましたけれども、７社ぐらいが構成されているＳＰＣでしたが、今おっしゃられた十数社、また、これから数十社というものは、ＳＰＣの代表となるような、いわゆる企業のことをおっしゃっているのか、それともその中で、何かコンソーシアムというか、そのようなものを組むということなのか、ちょっと細かいことですけれども。","respondent":"吉岡政策推進担当課長","answer":"一方で、代表にならなくても、やはり運営の肝となるような、例えば図書館など、そういったところもありますので、そういった部分については、また別途、今回のサウンディング調査で聞かせていただいたです。","voiceIndex":25,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"そこについてはできるだけたくさんの企業からできるだけたくさんの提案をいただいて、そういった区民ニーズに適したようなもの、そして都市ブランディングに資するようなものをつくっていただきたいと思いますが、そこについてもう一度ご答弁お願いします。","respondent":"吉岡政策推進担当課長","answer":"そういった中で、サウンディング調査を具体化することによって、事業者からの提案もありますし、質疑が出ることによって、また庁内連携、庁内検討がより具体化、深度化をしてまいります。","voiceIndex":27,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただ、現段階での計画の中では、近隣の比較的規模の小さい図書館並みの蔵書というところ、ただ、最先端の技術、いわゆる本を借りたり、貸し出したり、返却をしたりするものについては、最先端の技術だったり、閉架書庫、オートメーションの自動書庫、私たちもそれ見てきましたけれども、そういったものを取り入れるというものは拝見したのですが、ぜひぜひそこのところについては、もう少し。","respondent":"吉岡政策推進担当課長","answer":"そういった中で、蔵書数も含めまして、何が図書館の売り、あるいは図書館を中心としたこのようなスペースのところに人が集まっていただいてというところに寄与するのか、そういった部分を、やはり限られた面積、財源もありますので、どこに注力するかというところは。","voiceIndex":29,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"品川区においては、そのようなものに特化した学習スペースというものはあまりないような気がするのですが、計画の一部の中にそういった記載も見られるのですけれども、そこについては、ぜひこれも発注の仕様の中に、性能発注で仕様発注ではないのですが、そこのところもぜひご提案いただけるような発注の仕方をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"今、図書館の機能の中で、読書室、あるいは学習室というところで、少し音に寛容な施設でありながらも、こういった静かに学習できる、調べ物ができる、仕事ができるというスペースは重要だと考えていますので、今後のサウンディング調査を進めながら、どういった形で配置できるか。","voiceIndex":31,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"この住民説明会が３月に行われたということで、そこでどのような意見、あるいは質疑があったのか、それに区はどう答えたのか伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"住民説明会のほうで３月２４日に行わせていただいたというところでの質問の件ですけれども、まず、大きく防災に関する質問ございました。","voiceIndex":33,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりそれぞれが交流をして、有機的にもつながっていくというのですか、そうしたものになっていくというためには、運営の部分、そしてそれを監督する区の役割も重要になってくると思いますので、ぜひそこをしっかりしていただきたいと、それを含めて区民に愛される施設になるように力を尽くしていただきたいと思います。もし何かご答弁あれば、伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"今回の施設は超複合施設ですので、庁内の連携というのはもとよりですけれども、ＳＰＣ、これが設立したときにしっかりと区の意向を伝えて、あるいは区と話合いを進めながら契約を結ぶ、そして、その運営後につきましてもしっかりとモニタリングをして。","voiceIndex":35,"id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも質問します。中身としては体育館についてとなります。正式なサイズにちょっと広げてほしいという声を関係者の方から度々聞くのです。ですから、中途半端につくるよりは、やはりしっかりと先々を考えてつくっていただきたいという観点から、このようにお話ししているのですけれども、その辺り、この施設の広さに関してのお考えについてお聞きいたします。","respondent":"吉岡政策推進担当課長","answer":"当然ながら、体育館でできる競技、バスケットボールだけではございませんので、そういったスポーツの全体をどういったスポーツをやっていただけるか、なるべく制限もかけないようにというところで検討しています。","voiceIndex":37,"id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうあります。つまり、仕様をどのように、具体的に体育館のことでいえば、仕様をどこまで区で決めて公募するようなお考えなのかということと、それ以外の全般的な今のお考えのところについて、２点お伺いいたします。","respondent":"吉岡政策推進担当課長","answer":"は仕様のところで、２つ３つまとめてというような話にはなってしまうのですけれども、まさにこの機能の部分のところなのですが、面積につきましては、しっかりと固定して公募を進めたほうがいいという部分もありますし、一方で面積のところを、全てのところを当てはめてしまうと。","voiceIndex":39,"id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうあります。これは公募設定の前なのか後なのかというところもあるのですけれども、やはり事業者に全て任せるということではなくて、その声をできるだけ聴いて反映できるような進め方を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-011"},{"speaker":"筒井委員","kind":"意見","question":"最後に。ちょっと１点だけ、４９ページの公共と民間事業者の役割のところで、施設整備で既存施設の解体撤去のところで、ＰＦＩ方式を取っても「区ｏｒ民間」と書いてあるのですけれども、これ、最終的にいつぐらいで結論が出るのか、区が持つのか、民間が持つのか、その辺りいつ決定されるのか、その辺りのことをお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"今年度実施方針、あるいは要求水準書を策定する中で、民間事業者にお願いしたい業務というものを確定するところです。その中で解体業務が加わるか、加わらないかというところが確定をいたしますので、そういった意味では今年度中です。","voiceIndex":42,"id":"exchange-012"}]},{"id":"topic-02","title":"新庁舎整備に向けた実施設計概要等の説明","agenda":"新庁舎整備に向けた実施設計概要等の説明","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"中野区等で、今大きな公共施設の建設がストップをしたり、他自治体で不調が続出をしているという段階なのですけれども、品川区においては、当初４００億円以上という金額だったものが、最後は７００億円前後ですか、というところまで来ているのですが、ここについては、不調対策として、品川区としてどのようなことをされているのかお伺いします。","respondent":"小林新庁舎建設担当課長","answer":"各区の状況を見ますと、やはりそこの部分がしっかり反映されていなかったことによりまして、いわゆる予定価格が比較的低かったことから不調になっている事例も聞いているところですので、そういったような事例を参考にしながら、不調対策を進めてきたといったところです。","voiceIndex":50,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"要望も含めて、最後質問ですけれども、品川区においては、ここ何年もかけて、本当に新しい、先ほど新規の、今年度からの異動の方のご紹介も、ご挨拶もございましたが、何年もかけてようやくここまで来たというところで、最後の最後で、これは契約があるし、先方がある話ですから、不調ということがないように、現在工事公告等、公募されているということで。","respondent":"小林新庁舎建設担当課長","answer":"昨今の建設業界の状況は、非常に厳しいところでもあるわけですけれども、今回予算の中でしっかりと、その予算を使った上で発注のほうしておりますので、当然不調対策もしっかり施した上で工事公告も行ってありますので、我々としてもスケジュールどおりに進められるよう。","voiceIndex":52,"id":"exchange-014"}]},{"id":"topic-03","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"１点だけ、改めて見ておったのですけれども、現庁舎跡地等についてというところの（４）番で、「経済効果を要素として取り入れ」というところがありますが、これは「地域経済への効果を」としたほうが分かりやすいのかなと思いました。経済効果というものは品川区での効果ということだと思いますので、そのほうがいいのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"現庁舎跡地等についてなのですが、もうこれ明確な答弁もいただいているのですけれども、これから現庁舎跡地の検討が、新庁舎のほうの遅れに伴い、こちらも１年、かなりずれるということがあったのですが、計画の策定時には、この策定委員会に区議会の代表も入れていただきたいということで、それは検討するという答弁は何度かいただいているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7029#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19988,"voices":66}},{"id":"r07-20250417-19","meetingId":"r07-cm04","date":"2025年4月17日","dateIso":"2025-04-17","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"エコルフェス－２０２５ ＳＰＲＩＮＧ－の開催","agenda":"エコルフェス－２０２５ ＳＰＲＩＮＧ－の開催","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"きっとやっているに違いないと思いつつ確認なのですけれども、環境に配慮した取り組みで、リユース食器を使っていますよとか、これはどこの事業者ですよとかいうご案内とか、それから、キッチンカーの電気はこの屋上で発電した電気を使っておりますとかいう宣伝というのでしょうか、啓発になると思うのですけれども、そういうことはされる予定はいかがでしょうか。","respondent":"中西環境課長","answer":"今回も同じようにやる予定です。それから、リユース食器のところですが、今回Ｃｉｒｃｌｏｏｐという会社を使ってやりますので、そこがスタートアップ企業であるというところで、地域産業振興課のほうとも連携しながら、何か掲示ができないかというところは今検討しています。","voiceIndex":16,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"できれば要望なのですけれども、蓄電機を置くではないですか。一応要望なのですけれども、なかなか蓄電機はどう有効なのか、どう使うのか、簡単なのか難しいのか、やはりいざ災害のときに備える意味では、こういうエコのこともありますけれども、もしやっていただければありがたいなと思います。意見だけでいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-002"}]},{"id":"topic-02","title":"品川区災害時トイレ確保・管理計画","agenda":"品川区災害時トイレ確保・管理計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"このＡ３判の資料で、大きい２番の災害用トイレの種類と現状数量というところで、簡易トイレは４９４基あるということですけれども、どこに配備されているのか、そして、個室とか間仕切りとか、そういうものはどう考えられているのか伺いたい。マンホールトイレで、しかも下水に直結しているものというのは、この５２０基のうちどれくらいあるのか伺いたいのですが、お願いします。","respondent":"羽鳥防災課長","answer":"確かにマンホールはいろいろな形がありまして、くみ取り型であったり、下水道直結型であったり、直結していてもそこに貯留できるタイプなど、いろいろありますので、そういったところは今後詳細の数値のほうは確認してまいりたいと考えています。","voiceIndex":26,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"提案","question":"教室の中とかに何個もテントが張られる形になるのかとか、その辺のイメージはどんな感じなのか教えていただきたい。マンホールトイレです。「災害時に使いたいのはどのトイレですか」という問いに対しても、仮設トイレとかあるのですけれども、マンホールトイレが８２％になっていたり。マンホールトイレの啓発というのを区としてもやったらいいのではないかなというが提案の一つです。お願いします。","respondent":"羽鳥防災課長","answer":"学校改築の際にマンホールトイレを設置するなど、そういった区有施設の改築の機会を捉えてマンホールトイレを設置する、増やしていくように対応していきたいと考えています。","voiceIndex":28,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうなのですね。マンホールトイレの設置としては用地が出てきたときにということで、あまりなかなか迅速にいくものでもないのだなという思いがします。３,２１９基なのか８５９基なのか、どちらか分からないのですけれども、３,２１９基のほうだとしたら、これをゼロにするということを目指すということなのでしょうか。","respondent":"羽鳥防災課長","answer":"今回この計画を立てたところで、この時期にこれだけ不足するというのが顕在化、可視化できましたので、早めに手を打てるというところが今回のメリットだったのかなとは考えてあります。","voiceIndex":30,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、大きい３番の（２）番のほうの、「区民避難所から半径２５０ｍ圏内にあるトイレを含めると、トイレの必要基数は充足している」ということで、そうは言っても大丈夫ですよみたいな感じに聞こえるのですけれども、この半径２５０ｍ圏内にあるトイレというのはどんなトイレのことを言われているのか、そのトイレが実際に使えるトイレなのかというところまで。","respondent":"羽鳥防災課長","answer":"耐震化されているかされていないかというところに関しましては、耐震化されているトイレは、先ほどの２番の（１）の対象とする災害用トイレの表の下から２つ目、「災害対応型トイレ」となっていますのが、上下水道の管が耐震化されたトイレという形になってあります。","voiceIndex":32,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、避難所から半径２５０メートル圏内にあるトイレというのは、区有施設というか、大きい２番の（１）で言うと災害対応型トイレということなので、敷地施設内の下水道管が耐震化された既設のトイレということで言うと、区が関わっている施設のトイレということで、コンビニのトイレとかではなくて、区の関わりのある施設ということでいいですか。","respondent":"羽鳥防災課長","answer":"委員のおっしゃるとおり、区有施設のトイレになります。コンビニですとか商業施設、そういったトイレは含まれてございません。","voiceIndex":34,"id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"３月はしながわシティランでお披露目展示ですね、私も実際に使用させていただきました。やはり実際に本当に運用してみないと、検証しないと清掃云々という話もその次なのかなと思います。まだ２回しか展示されていないので、データというか課題というのはこれからかもしれませんけれども、この２回展示された中で何か気づいた点ですとか、課題に思った点があれば教えていただきたいと思います。","respondent":"羽鳥防災課長","answer":"いろいろ今回課題が見えてまいりましたので、そういった課題も含めて、また今後イベントでトイレトラックを利用する際の地域の方の負担をなるべく軽減できるように、いろいろ検討してまいりたいと考えています。","voiceIndex":37,"id":"exchange-008"},{"speaker":"えのした委員","kind":"質問・要望","question":"しながわシティランのときは５０名と、ちょっと寂しい数かなと思ったのですけれども、運河まつりは１日１,０００人のところ、人数で言うとその半分ぐらいですか。例えば、都内初は調布市ということで、私もその後、助けあいジャパンのほうにもヒアリングしましたけれども、品川区が２３区初ということで導入したので、他区でも動きがあるというお話は伺っております。その辺についてはいかがでしょうか。","respondent":"羽鳥防災課長","answer":"今後そういった平時のトイレネットワークの連携も含めて、いろいろ検討してまいりたいと考えています。","voiceIndex":39,"id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"利用ルールも含め、あと本当に地元の地域にトイレトラックが来てほしいというお声も地域の方からお話を伺っていますので、イベントが重なったりとか、どういう貸出しのルールかというのは、まだまだこれからだと思いますが、そちらのほうも要望として終わりにします。よろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"トイレ確保・管理計画は、資料１の１番の計画とはというところで、東京都のトイレマスタープランとの整合性をとっているというところで、先ほどの質疑の中でも２０人に１基とか、発災後の時間経過で５０人に１基とかいうところを一つの基準として、現状の確保状況をデータ化したというご説明がありましたけれども、ここについて、まず発災後の１週間までが５０人に１基なのだというところと。","respondent":"羽鳥防災課長","answer":"中期段階になると、「共同トイレは２０人に最低１基とし」と書いてあります。ですので、５０人に１基という認識は、多少不便でも災害発生当初はそれで耐えていただく。","voiceIndex":43,"id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"ありがとうございました。解消の対象として今後より詳細な分析をして、トイレ確保ということになって、整備とかとなっていったときに、そこはきちんとまた対応していくところと捉えていらっしゃるのか、ここについてお伺いしたいと思います。","respondent":"羽鳥防災課長","answer":"５０人に１基、２０人に１基の考え方ですが、１人当たりのトイレの数を増やして、なるべく長期化したときはトイレを含めた生活環境を改善していくという考え方かなと認識しています。","voiceIndex":45,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"本日もご説明ありがとうあります。今、品川区のトイレがどうなっているのかと、先ほど２０人に対して１基というような計算が出ていたと思うのですけれども、これは男女比とかというのは差が出てくるのではないかなと思うのですが、その点はどのように考えられているのか、また、基準についても何か差があれば教えていただければと思います。","respondent":"羽鳥防災課長","answer":"学校のトイレも通常ですと男性用、女性用とありますが、災害時には表示を入れ替えて女性用を増やすということも対応はできると思いますし、簡易トイレを設置する際にやはり女性を多く設置する、そういったことで災害時は男女比１対３になるように体制を整備しています。","voiceIndex":49,"id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのときに、下水道未耐震のところがあるといったところが、概要版の数字でいきますと、その他災害用トイレで耐震化されていない既設の洋式トイレは２,２９８基ありますということですけれども、その辺のところは可視化されて、これだけ耐震化されていないところがあるのだな、災害時にはこれは使えないというような対応で簡易トイレ等々を用意するということですが、この辺の耐震化というところは。","respondent":"羽鳥防災課長","answer":"上下水道の耐震のところにつきましては、管轄する東京都のほうで計画的に対策が進められているというところで認識していますが、まず、各避難所までの下水道管は継手の部分は全て耐震化がもう完了しています。","voiceIndex":53,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"耐震化の１経路だけはしてありますというお話ですが、それは各避難所のいわゆる学校の中にあるトイレの１系統ですから、何か所かある、１階から４階、３階までの校舎の１系統という理解でいいのかといったところを確認させていただきたい。","respondent":"羽鳥防災課長","answer":"そういった中で、不足していないところが８か所あったというところで、ほかの場所に関しましては、想定避難者数で割り返したところ、充足しているという状況です。","voiceIndex":55,"id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"表の読み方や状況、よく分かりました。そうしたときに、概要版のほうでも書いてあったかと思うのですが、簡易トイレを増設するといったときに、避難所の中のエリアを見直すといったことが記載されておりましたが、いわゆる簡易トイレ、だから、１つの管だけは耐震化されているので、ほかの耐震化されていないところを簡易トイレとして使うという理解でいいのでしょうか。","respondent":"羽鳥防災課長","answer":"その配置するという計画は立てるものの、どこに配置するのかというところを各避難所においてやはり場所を決めないといけないという課題がありますので、そこも含めて検討するという内容になってあります。","voiceIndex":57,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"避難所の話、トイレの話からちょっと離れてしまうのですが、この避難所のスペースを、一方で、ペットのことをどうしようかということもあって、スペースを使うのに結構悩ましい話ですけれども、何か品川区として今ある学校施設それぞれのスタイルが、しつらえになっておりますが、おおむね学校の施設ですから同じようなしつらえですけれども。","respondent":"羽鳥防災課長","answer":"昨年度、そういった委員のご指摘もありますので、品川区として標準的な避難所の運営の方針を定めたマニュアルを定めさせていただきました。それに基づいて、今年度各避難所ごとにその内容を落とし込んでいただくという作業に入ります。","voiceIndex":59,"id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"そこら辺の案はお持ちですかということですけれども、そういうのは、標準の中にこんなふうに考えていったほうがいいですよ。要するに、これは組み立てて個室を作らなければいけませんよね。そのまま置いておけば誰でも使えるという話ではない。だから、標準マニュアルの中にそういうのも示してさしあげたほうが検討しやすいかなと思ったので、その辺をお伺いしましたけれども、いかがでしょうか。","respondent":"羽鳥防災課長","answer":"そこはあとはそれぞれの避難所において、そういった動線であったりスペースが確保できるのかというところを細部まで詰めていくような作業になるのかなと考えています。","voiceIndex":61,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"一方で、最初にお話をしました耐震化の話、学校、避難所の前までは継手も何も東京都の管轄でということですが、学校内の施設の中での耐震化というのは学校施設、いわゆる品川区としてもそこは主導してできる話かなと思いますので、ぜひ学校施設内の、避難所施設内の耐震化というところも併せてしておく、そうした計画もぜひお願いしたいと思いますが、その辺はどのようなお考えでしょうか。","respondent":"羽鳥防災課長","answer":"今回、防災課のほうで災害時のトイレ確保・管理計画というものを策定いたしました。今後、庁内にこの計画を共有いたしまして、各所管で必要な対策を進めていただければと考えています。","voiceIndex":63,"id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、避難所運営会議とかでもいろいろ話が出るのですけれども、品川区内も２００超の町会、自治会がある中、様々な防災のイベントとか、防災に関してというのは温度差があるところ、当然地域性にもよるではないですか。私はすごくそれを痛感したので、ぜひお願いしたいと思っていますので、もしそのことで何かあれば、要望なのですけれども、よろしくお願いいたします。","respondent":"羽鳥防災課長","answer":"全区民配布をいたしました携帯トイレの今後の活用のところですが、実は本計画にも、２６ページになりますが、「自助・共助の取組の普及啓発方針」というところに、まさに先ほど委員がご指摘いただきました。","voiceIndex":67,"id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。ぜひよろしくお願いいたします。いま一度要望とします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからその前のところで、１３ページのところに、災害時のトイレを使えるかどうかということで、「排水管等の点検を実施」ということであるのですけれども、これは耐震化されているところも含めて点検してから使うということになるのか、そのところを伺いたいと思います。それで、この点検というのは一体誰がどのように行って、使えるまでにどれくらいで使えるようになるのか。","respondent":"羽鳥防災課長","answer":"その点検方法がマニュアルに書いてあるのかどうか今確認はできませんが、そういったやり方で断水状況という、被害状況というのを確認していただいてからご利用いただくというのが順番になります。","voiceIndex":70,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"断水してなくて電気も停電もなっていないということであれば使えるということで、それはだから一般の人でも簡単に点検ができるということで考えていいのか、その点も伺いたいと思います。それで、できればそれを下水道直結型に変えていくという方針はないのか、ぜひそうしていただいたほうがさらに使えるようになるのかなと思うのですけれども、そこの方針、計画についても伺いたいと思います。","respondent":"羽鳥防災課長","answer":"今後、貯留タイプから直結式というところに関しましては、既存のものを更新するというのもなかなかすぐには対応できませんので、今後新たに設置する際は下水道直結タイプのほうを優先的に設置できればとは考えてあります。","voiceIndex":72,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"帰宅困難者の数というのも品川区は特に多いと思うのですけれども、１２ページのところには、被害想定というところで帰宅困難者が２３万３,３１６人ということであるのですけれども、この帰宅困難者のトイレというのは、４ページのところに、すごく需要が増加するため、いろいろトイレを活用とかと書いてあるのですけれども。","respondent":"羽鳥防災課長","answer":"一時滞在施設については、区としては３日分の携帯トイレの備蓄をさせていただいていますので、そちらをご利用いただくということで対応しています。","voiceIndex":74,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。それから、防災公園に今マンホールトイレとかはほとんど設置されているようになっていると思うのですけれども、防災公園のマンホールトイレというのも下水道直結型というのはすごく少ないと伺ったのです。飲み水という点ではなかなか難しいかと思うのですけれども、生活用水という点では必要ではないかなと思うのですけれども、そこら辺の方針はどうなっているのかも伺いたいと思います。","respondent":"羽鳥防災課長、溝口防災まちづくり部長","answer":"設置できるところに関しましては井戸も生活用水としても活用できますので、そういったことも踏まえて設置できるよう対応していきたいと考えています。先ほど防災課長が答えたように、できるところはしっかり、マンホールトイレを含め、また、井戸を設置していきたいとは考えているところです。","voiceIndex":76,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほど３,２１９基を、足りない分をゼロにすると言われましたけれども、そこのところはいつまでにどういう形で設置を進めていくかというのは、計画を立てるということも今後していくのか、その点についても伺います。","respondent":"羽鳥防災課長","answer":"そこは国や都、他自治体、民間事業者、そういった協力体制を平時から築いていくというところで対応をとってまいりたいと考えています。","voiceIndex":79,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"これは大半のご家庭がそうだと思うのですよ。だって調べられないではないですか。排水管が実際どこかで断裂している、壊れているということは分からないから、そういうのはいざ大震災が起きたときに、だって全然宣伝なんか、皆さんこうしてくれ、ああしてくれとは言えないと思うのですが、まずそこをどのようにお考えになっているのか、基礎的なことだけ教えてください。","respondent":"羽鳥防災課長","answer":"区内の約８割の世帯の方が共同住宅に住まれているということですので、マンションに関しましては管理組合などで確認はできるかなと思いますので、あとは戸建ての方に関しましては。","voiceIndex":82,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"僕らが聞いている説明書の話でも、１,０００人から１,３００人ぐらいは使えるという話が、６００人だったら、これで満杯になってしまったらどこで給水するのですか。地下水といっても、例えば学校をもってもいろいろな施設をもってもかなり遠方になると思うし、これは本当に、耐震化は分かるのですけれども、給水化というのができてないと全く機能しないのではないですか。その辺についてお聞かせください。","respondent":"羽鳥防災課長","answer":"助けあいジャパンの災害派遣トイレネットワークでは、トイレトラックを派遣するだけではなくて、一緒に給水車とバキュームカーも所有している自治体に声をかけて一緒に対応していると聞いてありますので、そういったところも対応しているという認識です。","voiceIndex":84,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"認識はあれですけれども、現実論どうなのか。やはりもう和式は駄目ではないですか。小さなお子さんは絶対座れない。まして暗かったら絶対行けないではないですか。そうすると、そういう対策がなければトイレなんか行く人が少なくなって、それに対して二次災害の被害を受けて、病気になったり倒れたりする方も増えるのではないかと思うのですが、この辺はどういうふうにお考えになっているのか教えてください。","respondent":"羽鳥防災課長","answer":"委員のおっしゃるとおり、避難所のトイレ環境が悪いとトイレを我慢して、その分、飲食を我慢して、体調を崩して、最悪の場合は災害関連死ということにつながりかねませんので、トイレの環境というのは改善が必要だと考えています。","voiceIndex":86,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、もう本当に都会で暮らしている方は水洗トイレに慣れ切って、明るくて冬は暖かく夏は涼しい、そういうトイレ環境でもう３６５日過ごされているのですよね。改善しなければいけない。災害時はみんな我慢するのだよという時代は変わってしまったと思うので、ぜひ、大変だと思うのですけれども、様々な対応を予算がかからない方法で私はやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"私はもう皆さんの今の質疑を聞いていてほとんど理解いたしましたので、１点だけなのですけれども、特に災害時トイレ空白エリアとかに関わってくるのかなと思うのが、近隣区との連携、特に目黒区、大田区、港区だと思うのですけれども、こういったところとの連携というか、近隣区で、ごめんなさい、私は知識がないのですけれども、こういったトイレ確保・管理計画とかがあったりして。","respondent":"羽鳥防災課長","answer":"今後、他区の防災の課長会などで情報共有させていただきながら、他区と連携を深めていきたいと考えています。","voiceIndex":90,"id":"exchange-031"},{"speaker":"せお委員","kind":"質問・要望","question":"江戸川区のみだろうということで、すごくこの計画を立てられたということは本当に評価したいなと思っているので、ぜひこれからですけれども、協力だったりとか、そういったところを含めて連携は大切になってくるのかなと。やはり空白エリアが区境だったりするので、そういったところでも何か連携できるのか模索していっていただきたいなと、それだけ要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"だからこそ、スフィア基準があるからやるというのはすごく大事なのですけれども、でもだからやみくもにそこだけに負うことではなくて、やはり大事なのは、こうやって日々課長と私たちと、また区民が話し合う、だからここに何が大事なのかということを積み重ねることが本当の防災になると思うので、基準に引っ張られるという言い方はちょっと失礼に当たってしまうかと思うのですけれども。","respondent":"羽鳥防災課長","answer":"国のほうは、方針、指針といたしましては、ＴＫＢＢということで４つの視点で改善を掲げていますので、それに対しても、トイレだけではなく、区としてはバランスよく対応していくという方針で、今後もいろいろ検討してまいりたいと考えていますので。","voiceIndex":93,"id":"exchange-033"},{"speaker":"ゆきた副委員長","kind":"質問","question":"それが１点。２点目で、避難が長期化する場合はかなりの災害用のトイレが不足するため、今後さらなる備蓄の整備が必要になると思われますが、そこで東京都では各自治体について災害用トイレの整備費用の２分の１を補助する制度の利用を促していて、新年度から取組を進めていくことになっていますが、この活用については品川区としてどのように捉えているかお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"令和１２年度までに空白エリアの解消です。こちらはハード整備も含めていろいろな対応が必要になってくるところではありますので、今後、都とも連携しながら様々な面で対応を進めていくと考えています。具体的な方針まではまだできていませんが、都と連携して進めていくです。","voiceIndex":97,"id":"exchange-034"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"まさに今後ということなので、空白地帯の解消も今後進めていただければと思います。新年度の東京都の予算の活用については、補正予算とかを使っていただいて活用に努めていただければと思います。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"今回トイレのことがきちんと全体像というか計画が示されたということは本当によかったなと思うのですが、その中で、１３ページに、私はずっと災害・環境対策特別委員会のこの前の期のときだと思うのですけれども、他区との連携の中でいろいろな自区、自分の区だけでは調達できないものについてお互いに譲り合うというのでしょうか、融通し合うというような資料が示されていて、その中に。","respondent":"羽鳥防災課長","answer":"バキュームカーについての質問ですが、こちらは所管するのが品川区清掃事務所のほうになりますので、防災課のほうで詳細は把握していないところではありますが、もちろん都と連携をしながら対策をとるところと。","voiceIndex":101,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"トイレだったら汚物の処理は絶対課題になるわけではないですか。だから、汚物の処理ということについては所管は違うかもしれないけれども、こういう災害のときのし尿収集車の台数の不足というのは、まさにこの所管のところで問題になるわけではないですか。これは今は要望にとどめておきますので、ぜひ今後ご検討いただけたらと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-037"}]},{"id":"topic-03","title":"品川区防災ポータル・アプリの導入","agenda":"品川区防災ポータル・アプリの導入","exchanges":[{"speaker":"まつざわ委員","kind":"確認","question":"すみません、確認だけさせてください。平常時はハザードマップとかでやっていて、災害になるとこのアプリがぱちんと切り替わって、ふだんは例えばハザードマップだったのが、もう全部被害状況とか、アプリごと切り替わって、画面ごと変わってしまうのですか。","respondent":"羽鳥防災課長","answer":"出ている情報に関しましては、平常時の情報に関しましてはそのまま残して、少しレイアウトを変更して災害情報が上のほうにいくような設計になっています。被災情報であったり避難所の開設状況といったところは、災害時モードで初めて表示されるという状況になってあります。","voiceIndex":110,"id":"exchange-038"},{"speaker":"まつざわ委員","kind":"質問","question":"分かりました。これも災害時にこうやってアプリが切り替わるというのは分かるのですけれども、例えば定期的に、半年に１回、１年に１回、こういう災害状況、そのようなものがないからどういうふうなのかが分かっていないのですけれども、やはりそういうのがきちんと切り替わるようなテストというか、何かそういったことができるといいなと思っていますが、そこら辺どうでしょうか。","respondent":"羽鳥防災課長","answer":"訓練のときの活用ですが、テスト環境をつくって訓練用に災害モードに切り替えるということも、可能かどうかも含めて検討してまいりたいと考えております。","voiceIndex":112,"id":"exchange-039"}]},{"id":"topic-04","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"２つ目は、在宅避難（備蓄、マンション、相談窓口等）についてというところなのですけれども、それの（２）番なのですが、「在宅避難対策の推進に向け、非常用電源発電や太陽光発電の活用、周知・啓発等を含め」というので書いているのですけれども、周知・啓発というのは非常用電源のことや太陽光発電の活用についての周知啓発という意味で書かれているのでしょうかということで、それであれば。","respondent":"大倉委員長","answer":"いただきましたご意見・ご指摘も含めて、個別支援計画は避難計画に訂正させていただければと思います。","voiceIndex":119,"id":"exchange-040"},{"speaker":"鈴木委員","kind":"意見","question":"今の個別避難計画というのは書いていただくということでいいのですけれども、「避難行動要支援者の対象に障害者も含まれていることを示すなど、表記方法に十分配慮されたい」というのが、意味がよく分からないなと。どういう意味で、どこに表記するのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7031#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":37215,"voices":128}},{"id":"r07-20250425-10","meetingId":"r07-cm04","date":"2025年4月25日","dateIso":"2025-04-25","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"今ご説明いただきました件の中で確認をさせていただきたい点があります。それは、備考のほうもよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"こんの委員","kind":"提案","question":"備考のほうに、「など」とついている部分があります。その「など」というところを何点か確認させていただきたいと思います。それから３点目が、若者のニーズを把握するという手法の一つに、住民参加型デジタルプラットフォームがあると思いますので、その活用についても、「など」という中に確認をさせていただきたいと思います。次の調査事項の３点目に、重層的支援体制に関すること。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"正副委員長でまとめていただきまして、ありがとうあります。こんの委員からもありました「など」のところの確認、要望なども含めまして、私たちしながわ未来からの感想、意見を申し上げます。１つ目は、ＳＤＧｓ推進・行財政改革特別委員会ということで、ＳＤＧｓ推進と行財政改革を調査項目としたことで、当会派の要望どおり進めていただき、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"せお委員","kind":"質問・要望","question":"３つの会派からでしょうか、要望があった上で、先日の議運で議論したことも加えて、このようにきれいにまとめてくださり、正副委員長には感謝申し上げたいと思います。そのときそのときで、何か加えなければいけないものもあるかもしれませんので、柔軟に対応していただけたらと考えております。","respondent":"まつざわ委員長","answer":"４月１４日の議会運営委員会でいろいろな話が出たときに、特別委員会の在り方というのをもう一度いろいろ検討しましょうというお話の中で、自民党案が出て、公明党、また未来からいろいろなお話があった中で、ただいつもどおり常任委員会のものを切り分けて、ただやるのではなく。","voiceIndex":9,"id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"今までも特別委員会というのは、まとめという形で出していたと思うので、私は変わらないのではないかと思うのですけれども、大事なのは、今回３つの特別委員会を出されていますけれども、委員会の中で、しっかり委員間で討議をして、きちんと合意ができるところについては、議会として委員会として提案するけれども、民主的な議論というのはすごく大事だと思っていまして、そこで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"すみません。よく議論することが大事、そして、その結果まとまったものについては、提案していくと。そのまとめる努力とか議論する努力というのは、共産党としてもやっていくということは考えているということだけ述べさせていただきたいと思います。","respondent":"あくつ副議長","answer":"おっしゃっていることはそのとおりだと思いますし、まとめるための努力をしていくというご発言がありましたので、そこはきちんと議事録に残していただいて、今までのように、こんな意見もあって、こういう反対意見もあったみたいなものを区長に出したときに。","voiceIndex":14,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"特別委員会の調査事項、要望はかなりたくさん出たのだと思うのです。ですけれども、確認なのですが、あくまでそこの特別委員会の委員長、副委員長、それで委員と、これから調査事項についてはそこで決めて、そしてそこで議論していくという形で、皆さんのいろいろな要望はありましたけれども、それは聞くにしても、その特別委員会の中で決めていくというスタンスでいいのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"この２７人の中に無所属議員の方が入るのかということと、これは委員会なわけですから、大事な発言の機会なわけですが、今までもそうだったのでしょうけれども、議員によって所属する委員会の数が違うという不公平についてはどのように考えているのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"あくまで会派でやるということは、会派に入っていない人は入ることができないという提案ということでしょうか。そういうことになると思うのですけれども、私は今回、数を増やしても、１３人でいいではないですかと思うのですが、前回、１３人だと多過ぎるという議論がありましたけれども、実際、１時から始まります特別委員会で、５時までやったことは１回もないと思います。それをなぜ改善しないのですか。","respondent":"まつざわ委員長","answer":"無所属の方からのご意見を私も実際聞いています。やりたいという方もいらっしゃれば、それは迷惑だからやらないでほしいという方も実際にいらっしゃいました。特別委員会に、無所属一丸となって入れてくださいというお話は、私にはありませんでした。","voiceIndex":23,"id":"exchange-009"},{"speaker":"須貝委員","kind":"提案","question":"今、安藤委員からそういう提案が出ましたけれども、それはそれで、私は悪いとは思わないのですが、ただ、そういうことならば、無所属の方も特別委員会に含めたらどうだという、長い間の慣例はそのようにはなっていないのですが、だったら別の場できちんと話し合って、議運でまた皆さんで決めて直していかない限り、ここで今云々ということを、こうしますというわけにはなかなかいかないのかなと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"せお委員","kind":"意見","question":"私は９人でよろしいかと思います。先ほど、共産党も、議論をしっかりして、まとめて、しっかりまとまったことを提言していくというお話があったと思うので、議論をしっかりしていく、一定の成果というか、一定の提言というのをまとめるに当たっては、１３人では多いと感じておりますので、そこは私たち会派も９人が妥当なのではないかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"安藤委員","kind":"提案","question":"須貝委員より、別の場をつくって討議したらどうかという提案だと私は受け止めたのですけれども、その提案に対するリアクションがないというか、どのようにお考えなのでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"少し確認です。ペーパーレスは全然いいかと思うのですけれども、基本的には今あるものが、そのままペーパーレスですか。多少、中身は省くようなものが出たりはするのでしょうか。","respondent":"大澤区議会事務局長","answer":"この形のままアップするということではなくて、ここに載っている必要な情報については、何らかの形で皆さんに、紙ではなくてお手元に行くようにいたします。","voiceIndex":40,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7033#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":12762,"voices":47}},{"id":"r07-20250512-6","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"区民委員会","time":"午後 １時００分～午後 ３時４２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「荏原町安全安心ステーション」の廃止","agenda":"「荏原町安全安心ステーション」の廃止","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところですけれども、協議というのはいつ行うのかというところを教えていただきたいのと、区としては、公衆トイレにするという方向、考えでその協議に臨むのかということを確認させていただきたいのが１つです。","respondent":"澤邉生活安全担当課長","answer":"２点目、公衆トイレですけれども、公衆トイレにするというわけではなくて、あくまでも次の使う形というのは、地域の皆さんの意見を聞きながら、そこは先方の民間鉄道会社と話し合って、町会の意見を聞きながら。そのボタンについては、次が何になるかにもよるのですけれども、基本的には外すような形になると思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域の方の声をよく聞いて、進めていただきたいと考えています。それで、この間、町会長ですとか推進委員をやっている方ともお話を進めてきたということなのですが、最終的には廃止に合意ということでしたけれども、話合いの間、どんな意見が出されたのかなというか、少し紹介していただきたいと思います。廃止に反対という声はなかったのかというのも含めて、教えていただきたいと思います。","respondent":"澤邉生活安全担当課長","answer":"実際に協議は、記載がありますのは４回ですけれども、実はそれ以外にも、私のほうで赴きまして、推進員と生の会話を何回かやっております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。１８年前に、交番を残してほしいという大きな地域の要求運動が相当あったのですよね。それにもかかわらず交番がなくされてしまったのですが、それで１８年が経過して、今度はステーションをなくすということになりますけれども、区とか警視庁は、地域の安全・安心という点では、どのように総括されているのか。ちょっと難しい質問かもしれないのですけれども、お願いしたいと思います。","respondent":"澤邉生活安全担当課長","answer":"委員の今のご質問ですけれども、なかなか難しいところがありますが、基本的に区としましては、警察４署ありますけれども、そこと連携してこういった防犯を進めていくというスタンスは変わりません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"先ほど紹介した声の中にも、昔から地域にあったもので、伝統もあるのでという話もありましたけれども、それまでの経緯で、やはり地域の安全を守ってきたという経緯があるので、今後、何に活用するにしても、地元で培ってきたような地元の皆さんの思いですとか、あるいは周辺の関係ですとか、そういったことを踏まえた上で、ぜひご検討していただければと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"平均年齢が８０歳以上の方々ということですけれども、そういった方々の交流の場にもなったのではないかなというところもあると思いますので、ここについてはやはり廃止したで終わりではなくて、その後の、要望があれば受けるという形だけではなくて、貢献されてきた方々の意向に沿って、所管をまたいでのことになると思うのですけれども、これから働きたいとか、シルバー人材センターへのつなぎとか、あと。","respondent":"澤邉生活安全担当課長","answer":"平均年齢８０歳以上と申し上げましたけれども、皆様かくしゃくとしていらっしゃいます。そして熱い思いを持っていらっしゃいます。そういった方々が働ける場だとか、そういったことを何か、課を超えてになりますけれども、我々も考えていきたいと考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認させていただきました。ぜひ推進員の方々の意向を酌んで、受け身ではなくて、要望に沿った形で進めていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"意見","question":"公表するかどうかというのは防犯面でまた難しいかと思いますので、ただ、課のほうでしっかりと把握していただくのであれば、地図を俯瞰的に見て、この辺、足りていないねとか、そういったものも分かりやすいと思いますので、また地域の町会の方のお話を聞きながら、進めていただけたらと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"最初の防犯カメラと今の防犯カメラではそこがちょっと違ってきているような気もするのですが、荏原町の付近だけではないと思うのですけれども、改めて防犯カメラがついているところのチェックをきちんとしていかないと、１０年前、１５年前ぐらいの防犯カメラと今の防犯カメラでは違うと思うので、その辺のチェックというのは区が指導してやっていっていただきたいと私は思うのですけれども。","respondent":"小林地域産業振興課長、澤邉生活安全担当課長","answer":"ただいまシルバー人材センターの登録というか年齢制限はあるのかというお話ですけれども、これについてはなくて、今、最高齢の方でいくと、９０歳を超えても登録されている方とか、あるいは。防犯カメラの設置場所についてですけれども、常に新しいものに更新しておりますので、補助事業で新しく更新された部分についてもきちんと把握しておりますので、そこのところは担当としましてきちんと把握していきたいと考えています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"安全・安心のまちづくりには、間違いなく防犯カメラというのは効果があるというのはもう分かっていることですから、手厚く、まず説明して、情報弱者にならないようにしていっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"澤邉生活安全担当課長","answer":"委員ご指摘の部分でございまして、区からの発信というのは非常に大事だと考えております。まだ私も着任１か月半ですけれども、先月、各センターが主催しました町会長会議がありまして、その場で、実際に私も行かせていただきまして、説明はさせていただきました。","voiceIndex":24,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で、もし何かご答弁があればお話を聞きたいですけれども、ぜひそういった視点も含めて、せっかく今までの古きよきものがあって、それが一定の役割を終え、廃止されるのであれば、私はやはり次の未来に向かって、新しいものをそこから発信するというのも、地域がさらにまた活性化をするためには必要になってくるのかなと思うので、ぜひその辺の視点を含めて検討していただきたいと思いますが。","respondent":"澤邉生活安全担当課長","answer":"そうしますと、警視庁に一旦、交番として認めさせてもらわなければいけないだとか、いろいろそういったことが事務作業としてはあるのかと思いますけれども、ただ、ご提案としては、そういったＤＸ化だとか直通というものについては、今後。","voiceIndex":26,"id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私からは１点。皆さんからいろいろなお考えが出て、私も同様に感じます。地域の方たちのご意見はぜひ活かしていただきたいと。地域の方たちのご意見を活かしてこの土地の活用をする場合、これはあくまで使用貸借を前提とした協議を進められるということなのでしょうか。その点、確認させていただきたいと思います。","respondent":"澤邉生活安全担当課長","answer":"本件の土地につきましては、以前、交番があった昭和４９年から使用貸借契約でずっと来ておりまして、今回の安全安心ステーション、平成１９年に設置した際にも、新たに使用貸借ということで契約を行っております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"提案","question":"区としてはどうしても使用貸借でいきたいという方向なのかということを伺ったのですけれども、おっしゃったとおり、すごくいい場所ですので、これを使用貸借のまま継続してというのと、そこから先は、交渉とか、それから区のほうの、所管だけでは決められない、予算という話になってくると思いますけれども、皆さんからもご意見が出たとおり、区民として、地域の方たちに有効な活用として提案する場合に。","respondent":"澤邉生活安全担当課長","answer":"賃貸となりますと、お借りして金銭を支払うというところですけれども、ここはちょっと私のほうでも契約当時ではないのであれですが、多分、地域の皆様のためにだったら使用貸借という形で、お金を取らないよという形で、善意で借りている部分もあるのかなと想像しますので。","voiceIndex":31,"id":"exchange-012"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ここの委員会の皆さんのご意見でも、地域の方たちの意見はきちんと尊重してということだったと思うのです。それが、要はそこから先は条件交渉みたいになるのだと思うのです。私としては、要望としては、その辺まで踏み込んだ交渉がないと、こっちが持っているカードというか、それとしてはすごく弱いと思うのですけれども、いかがでしょうか。","respondent":"澤邉生活安全担当課長","answer":"使用貸借といいましても、実際はお返しするときには更地にして返すというのが基本的なところです。そこを、これまでどおり、先方の所有者にご理解いただいて、無償のような形で、跡地を地元の方たちに使っていただくような形で、何とか交渉したいというのが担当としての考えです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これ以上はもう答弁は求めませんけれども、私の意見として申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"}]},{"id":"topic-02","title":"八潮地区における買物弱者支援事業","agenda":"八潮地区における買物弱者支援事業","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"既に始まっているということなのですけれども、販売内容は実施場所によって異なるということなのですが、３か所それぞれについて、大体こういう違いがありますよとかをお知らせいただきたいのと、あと、販売者はどこになるのかというのと、あと、曜日と時間帯ですね、実際いつ行われているのか、行われていくのかというのを含めて、教えていただきたいなというのと、それと。","respondent":"今井八潮まちづくり担当課長","answer":"最後に、エリアの一番下側、南側の都営４０～４３号棟エリアにつきましては、毎週土曜日の１３時半から１４時半までといったところで、生鮮食品、お刺身とかお魚とかといったものを中心として移動販売をしていただいているのと、先ほど冒頭にご説明いたしました。","voiceIndex":40,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"費用もまだかかっていないということですけれども。それで、試験運用もやったし、あと本格運用も７日から始まっているということなのですけれども、その結果、何か得られた知見ですとか、あるいは住民の反応とか、そこら辺についてはどうなのかというのをお伺いしたいのと、それと、覚書というのがあるのですが、これはどんな覚書の内容なのかというのをご紹介いただければと思います。","respondent":"今井八潮まちづくり担当課長","answer":"一方で、品川区と事業者の覚書につきましては、実施場所としてどこの都営住宅の敷地の中で販売をするかといったような内容ですとか、実施日時ですね、何時から何時までといった内容、それから販売商品の内容といったところで。","voiceIndex":42,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだ始まったばかりなのですけれども、利用人数的なところというのは、もし何かイメージというか、結構使われているのですよねみたいになっているのか、それとも、まだこれからですよというところなのか、そこら辺が分かるような何か人数的なものがもしあれば、後で教えていただけないでしょうかというのが１つと、それと、買物弱者支援事業というのは非常に重要で。","respondent":"今井八潮まちづくり担当課長","answer":"この買物弱者支援事業という事業のスキームが、実施の要件として、移動販売車で物を販売するといった事業を都営住宅の敷地内でやるというスキームになっているところから、移動販売事業者でどこか八潮地区内で移動販売を実施できるところはないかという検討をさせていただいて。","voiceIndex":44,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"その辺の体制をとってほしいという要望なども住民のほうからはあって、私たち共産党としても議会で何回か取り上げたこともあるのですけれども、そういったことも併せて検討していただきたいと思うのですが、いかがでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"移動支援的なところでの買物弱者支援をできるかどうかということですけれども、今の費用負担の問題等も関係してくると思いますが、今回の事業スキームですと、品川区側としても東京都側としても基本的には費用ゼロで事業を実施できるといったところで、あるいは。","voiceIndex":46,"id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"本質的には買物支援だと思うので、今回こういった形で移動販売ということで事業がスタートいたしましたけれども、やる中で、様々、当事者の住民の方の声を聞きながら、移動支援なども検討していっていただければありがたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-019"},{"speaker":"おぎの委員","kind":"質問","question":"私からも何点かお聞きしたいのですが、足の悪い方とかご高齢の方とかもいらっしゃると思うのですけれども、軽トラで販売に行くということで、雨天のときの対応はどうなっているのかというのと、あと、個人商店と契約ということですが、こちらは、今、１者ですか。今後また何者か増える予定とかはあるのか、お聞かせください。","respondent":"今井八潮まちづくり担当課長","answer":"雨天時の対応なのですけれども、基本的には、例えば都営住宅の敷地のひさしの下とか、ぬれないところで販売できるように対応を検討しています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"天気にも対応できて、その場所なのかなという気がしました。それで、今後増えていくと、お買物なんかもとても楽しく、外出の機会も増えるのでいいと思うのですけれども、広報の方法というのはどういった予定でしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"現状ですけれども、自治会のほうでＰＲのチラシを作成していただいておりまして、こちらの内容は、全自治会長の情報共有用のＬＩＮＥグループがありまして、そちらで流していただいたりですとか。","voiceIndex":52,"id":"exchange-021"},{"speaker":"おぎの委員","kind":"意見","question":"品川区のホームページを見られない方もいらっしゃると思いますので、チラシとかをつくっていただくのはすごくいいと思います。ぜひ皆さんが利用しやすいように工夫していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問","question":"実施内容のところで、試験運用が１月後半から、本格運用が７日からです。いわゆる場所を提供しているだけだと。ということは、主体は品川区なわけだから。場所を提供しているだけですと言われたら、では、何かあったときに誰が責任をとるのですかというところでもあるわけです。なので、今回、どういうふうに報告事項として上がってきたのか分からないのだけれども、その辺、改めて教えてください。","respondent":"今井八潮まちづくり担当課長","answer":"この間の経緯といたしましては、１月２５日から試験運用という形で、場所とか時間とかを変えながら、どういった内容で販売するのがいいのかいろいろトライアル的に試しながら実施をしてきたところでして、東京都との覚書のやり取りとかもその間で調整させていただきまして。","voiceIndex":55,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"分かりました。ただ、特にこれは品川区だけではなくて東京都も絡んでいるわけですよね。これは多分どの委員会でも、いろいろな事業で毎回出るわけです。なので、そこはやはりもう少し丁寧に報告事項の在り方を考えてほしい。これは別に答弁は要らないですけれども、ぜひその辺は、特に前列の皆さんにはしっかりと、いわゆる情報共有については考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"私としても、今、石田しんご委員がおっしゃったようなところは感じていたので、ぜひ考えていってほしいというところです。それも含めてというか、だから、せっかく試験運用みたいなことをしていただいていても、５月７日ではなくても、本格運用するまでの間に報告していただければ、何か課題が上がってきたときに、みんなで考えられたなというのもあったのですね。","respondent":"今井八潮まちづくり担当課長","answer":"ただ、事業者が切り替わるといったような背景もございまして、なかなか閉業期間中に別の場所で移動販売などをスーパーバリューとしてやることは難しいということで、品川区で対応を検討した結果、こういったやり方を実現したといったような内容になりますので。","voiceIndex":59,"id":"exchange-025"},{"speaker":"せお委員","kind":"意見","question":"そういったことも聞けていたらよかったなというのがあったので、今後、そこら辺は留意していただいて、事業者が変わってしまうということですけれども、このスーパーもずっと八潮の方々のために運営されてこられていたので、区民の方はもちろんですけど、こういう事業者とも関係性がよくなるような取組をぜひ続けてください。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"常々、そういう資料は、いちいち情報公開請求しなくても、所管の委員会ぐらいには添付してほしいと思うのですけれども、それは別の問題になりますが、販売者についてどことどういう契約を結んでいるのか、教えていただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"品川総合福祉センターについても、このたび八潮地域内にプチレーブが移転してきたといったタイミングでございましたので、そこの事業者にお声かけをさせていただきまして、ちょうど品川区でこういった買物弱者支援事業の運用を開始しているというところで。","voiceIndex":63,"id":"exchange-027"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それはご答弁を求めたいと思いますけれども、本当にそれでいいのかなという気がして、例えばお客さんがたくさん集まっているところだなと思うほかの事業者が、自分たちもここで販売したいとかということは許さないのか、そういう自由を求めるのだったら何か手続が必要になるかと思うのですけれども、その点についてはいかがでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"区としては、特に財産を貸し出しているわけでもなく、利益を供与しているわけでもないというところで、八潮地域内で販売のなじみのある、プチレーブについてはこれまでも障害者の就労支援事業としても実施していただいているといったつながりもありましたので。","voiceIndex":65,"id":"exchange-028"},{"speaker":"吉田副委員長","kind":"質問","question":"プチレーブに関しては、就労継続支援Ａ型の事業所ですから、それはある意味、当然かなと思っているので、私としてはあまり違和感ないのですけれども、やはり販売者を決める何か手続というか、しかるべき手順があってもよかったのではないかなと。もし何か見解とか伺えることがあったら、聞きたいです。","respondent":"今井八潮まちづくり担当課長","answer":"先ほどご説明した内容と重複もしてくるのですけれども、買物弱者支援事業の発端といたしましては、１月中旬あたりにスーパーバリューが一時期閉店すると、それが地域の方に知らされたのが、直近の、１か月を切ったぐらいのタイミングで知らされたといったところがあります。","voiceIndex":67,"id":"exchange-029"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これで最後にします。だんだん事情が分かってまいりました。そういうこともあってご報告が遅れたのもあるのかなと思いますけれども、先ほど石田しんご委員からもありましたが、もう少し早くご報告があってしかるべきだったかと思います。早めにご報告をいただいたほうがいいと思います。これはあくまで要望です。強く要望しておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"だから、これは本当に課題があると思うのだけれども、課題の中で、もし危機感を持って、スーパーが、一時閉店だけれども、撤退にならないと希望的観測で思うけれども、撤退したらどうしよう、そうやって軽自動車等で販売してくれるところがなくなってしまったらどうしようというこの課題というのは、すごくきちんと押さえておかないと、今後あるなと思うのと、それと、数多い事業者に声をかけて。","respondent":"今井八潮まちづくり担当課長","answer":"スーパーの撤退等については、地域の方もやはりかなり危機意識を持っていらっしゃる部分でございまして、八潮まちづくり担当としても、広い意味で、長期的な目線で対応していかなければいけないと考えているところです。","voiceIndex":71,"id":"exchange-031"}]},{"id":"topic-03","title":"氏名の振り仮名法制化に伴う品川区の対応","agenda":"氏名の振り仮名法制化に伴う品川区の対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区に本籍があるのだけれども住んでいるところは違う方に対して、品川区は全て住所が分かるものなのですかというか、通知を送付できるものなのかというのが心配なのですが、そこら辺どうなのかというのを伺いたいなと思います。それと、はがきなのですけれども、はがきを送るとあるのですが、個人情報などプライバシーが配慮されたものになっているのかどうか、伺います。","respondent":"築山戸籍住民課長","answer":"３点目の質問です。はがきの個人情報の配慮ということですが、こちらは個人情報保護がされている形で、開かないと分からない形式のはがきを使いますので、そこは保護されているもので送付する予定です。","voiceIndex":77,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"２つ目は、行政をかたった詐欺などが多いので、１１日号の広報も見せていただいたのですけれども、本人に通知が行くとはいっても、周知の仕方なのですが、現状の対応では不十分なのではないかなと思って、さらなる、例えば本人に通知が行くというのと広報によるというだけではない対応、今こういうことが行われていますというような、ポスター掲示なのか分かりませんが、もう少し周知の工夫というのがないと。","respondent":"築山戸籍住民課長","answer":"周知です。周知は区でもしてまいりますが、こちらは国の事業ですので、法務省からも周知がされるですので、全国的な周知がありますので、区も併せて、広報紙ももう一度発行いたしますが、このような形で周知してまいりたいと考えております。","voiceIndex":79,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"はがき送付が６月下旬ということで、コールセンターはその前から、今月末からということなのですけれども、まだ時間は若干あると思うのです。大講習室は結構広いところで、そこまで必要なのかと率直に思ってしまうのです。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-034"},{"speaker":"おぎの委員","kind":"質問","question":"件数を考えますと、結構大変な作業と思うのですが、特設会場・コールセンターの部署となります中小企業センターには、増員というか、職員の配置はどれぐらいになっているのでしょうか。","respondent":"築山戸籍住民課長","answer":"職員の配置の状況ですが、繁忙の状況にもよりますけれども、職員１０名と、あと委託事業者も入れますので、そこで２０名程度を想定しています。","voiceIndex":85,"id":"exchange-035"},{"speaker":"おぎの委員","kind":"質問・要望","question":"なかなか大人数で１年間取り組んでいただくという形になるのだと確認しました。やはり個人情報ですので、ＲＰＡは万能ではないので、やはり最後は人のチェックと、データの管理はしっかりとしていただきたいなと。こちらは要望で、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-036"},{"speaker":"ゆきた委員","kind":"質問","question":"個別対応でそれぞれ返信用封筒などの対応をしていくのか、一定数あると思うのですが、そこについての予算の考慮もされているのか、お聞きしたいと思います。","respondent":"築山戸籍住民課長","answer":"郵送の場合につきましては、そのままご返信いただくような形を考えております。郵便料はかからないので、区の負担となっております。","voiceIndex":89,"id":"exchange-037"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。こういった問合せについては、業務委託のコールセンターでの対応、または直接戸籍住民課での対応になると思いますが、丁寧に進めていただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"例えばですよ、品川区だから。それが１点で、もう１つは、はがきで送らないとかそういう人は、中小企業センターとか設置されているところに行って申請するのですか。ということでいいのでしょうか。それで、もし名前の振り仮名がというか読み方が違っているはがきが来てしまった人が、予想すると大体４万人ぐらいいるのではないかという数で役所としては考えているということでいいのでしょうか。","respondent":"築山戸籍住民課長","answer":"委員のおっしゃるとおりで、まず、人数としては大体４万人ぐらい、誤っていて届出が必要になるのではないかと想定しています。","voiceIndex":93,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"そこまでは分かって、最初の質問で、一番最初の一歩で、「しながわ」さんと「ひんかわ」さん、そういう理解でいいのですよね。本当は「ひんかわ」さんなのに、「しながわ」さんで来ていたからというあれで、「ひんかわ」ですというふうに変えるという意味で、これをすればいいという、一番基本中の基本というか、最初の一歩はそれでいいのですよね。最初の一歩はそれでいいのですよね。","respondent":"築山戸籍住民課長","answer":"おっしゃるとおりで、名前の振り仮名が間違っていなければ、何もしなくて結構です。ただ、読み方が、先ほどおっしゃったように、「ひんかわ」さんが「しながわ」さんとなっていた場合は、正しくは「ひんかわ」ですというように届け出ていただく必要があるです。","voiceIndex":95,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"技術的なことかもしれないのですけれども、これ、品川区だから「しながわ」さんと言っているだけですからね、最初に「品川何々」さんですよねというはがきが来るとき、「品川」というお名前を「しながわ」というのは、まあ、「しながわ」だろうなという感覚でやるということですか。だから、１回目というか、最初は大体予想をつけて出してみようという思いでいいのでしょうか。","respondent":"築山戸籍住民課長","answer":"その場合に、誤って登録されていることが想定されますので、今回、初めて戸籍を有する全国民に振り仮名の通知をするですので、これまで分からなかった、間違って登録していたという方々がたくさん出てくるのではないかと考えているところです。","voiceIndex":97,"id":"exchange-041"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々から何かを発信することはないわけですよね。だから、それをきちんと言わないと、要は、区からそういう問合せを本人にすることはないですよというのを絶対に明記してもらいたいと私は思って、まず、公式の郵送物だというのと、区から直接何かを求めることはないですよというのを、やはりそろそろ公式な郵送をするときのルール化というか、ぜひ進めていただきたい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"すみません、１点だけ。本当はこのことだけに限らないのですけれども、視覚障害者の方へのはがき上の配慮はどういうふうになっているのか、改めて確認させていただきたいと思います。基本は、同行援護とかのサービス利用されている方は、その方に読んでもらってやってもらうのだと思うのですけれども、直接区としての配慮があったら、教えてください。","respondent":"築山戸籍住民課長","answer":"ですので、視覚障害の方も、もちろんそうでない方も、アプリで、Ｕｎｉ－Ｖｏｉｃｅは誰でも無料でダウンロードできますので、それで音声が読み取れるようになっておりますので、この音声読み取りにつきましてはそれぞれの通知文に対応しておりますので。","voiceIndex":104,"id":"exchange-043"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"分かりました。そういう配慮がされるということで、よかったと思います。基本は、皆さん、障害者の方も、最近視覚を失われた方以外は、いろいろな制度のことがよくお分かりなので大丈夫だと思いますけれども、ご要望いただくのは、せめて視覚障害者協会にこういう情報は提供してほしいと。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"来させるか、あるいはマイナポータルを使えというのはあまりにもハードルが高過ぎるので、それは本人負担がかからないようにしてもらいたいと思います。何とかしていただけないでしょうか。いかがでしょうか。","respondent":"築山戸籍住民課長","answer":"今回、もし誤っていて届け出なかった場合どうなるかと言いますと、１年後に自動的に戸籍のほうにその振り仮名が登録されることになるのですけれども、１回に限り、家庭裁判所の許可なく、区市町村への申出によって訂正することができますので。","voiceIndex":109,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"マイナカードをどうしても浸透させたいという意図的なものを感じてなりませんが、マイナカードというのはつくるかつくらないか任意ということでやっていたわけですから、まずは品川区が持つと。は郵送代を自費で、単費で持っていただきたい。そして、そのことを後から国に請求するなりということをしてでも、そういうことをやっていただきたいと私は思っております。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-046"},{"speaker":"ゆきた委員","kind":"意見","question":"１点で、切手の費用が高くなったということが１つあります。２つ目が、施設に入っている親族の方にもし誤った振り仮名で通知が届いた場合ですけれども、こういった場合には直接行くことが難しいと思います。この２点、あると思います。マイナンバーもなく郵送で行う方も数多く、この点についてぜひ考慮していただければと思いますが、何かあればお願いします。","respondent":"築山戸籍住民課長","answer":"なかなかお越しになれないというような状況もあるかと思います。ただ、期間を１年間設けておりますので、先ほどもお答えいたしましたが、一度に限り、家庭裁判所の許可なく変更も可能となっております。","voiceIndex":113,"id":"exchange-047"},{"speaker":"石田（し）委員","kind":"質問","question":"これは別に本庁でなくてもいいのですよね。各地域センターとか、住民票とかを担当しているところでは駄目なのか、そこだけ。どこで届け出られるのかだけ、教えてください。","respondent":"築山戸籍住民課長","answer":"今回は戸籍の届出になりますので、そうすると本庁のみとなっております。","voiceIndex":115,"id":"exchange-048"}]},{"id":"topic-04","title":"品川歴史館リニューアル１周年記念企画展「昭和100年 しながわめぐり」","agenda":"品川歴史館リニューアル１周年記念企画展「昭和100年 しながわめぐり」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今、昭和という時代に対して、去年はドラマもありましたけれども、ティーンの方もいろいろな意味で関心を持たれているところもありまして、ぜひ区内の高校生ですとか１０代の方にも見に行ってもらうことが大事と思うのですが、小中学生が無料とあるのですけれども、子どもの権利条約もそうなのですが、厳密に言うと１８歳までが子どもとなっているので、１００円とか５０円という価格でもありますので。","respondent":"大森文化観光戦略課長","answer":"小中学生が無料で、そこから、年齢でいうと１２歳以上１８歳までという形で高校生以下の無料はいかがかというようなお話ですけれども、何分受益者負担というところでお願いしている金額設定で、区内の小学生・中学生は社会科見学とか。","voiceIndex":121,"id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"ぜひ多くのお子さん、１８歳以下の方に見ていただくことが大事だと思いますので、先ほど言ったように、子どもの権利条約では１８歳までが子どもとなっておりますので、受益者負担という言葉も出ましたが、非常に寂しいなと思いますので、今後、いろいろなほかの部署との関係もあるでしょうし、ご検討していただけるとありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問","question":"私からは１点だけ、ＪＲ品川駅サイネージは少し新しい試みなのかと思います。私はあの自由通路のところだと思ったら、中央改札の前ということで、金額はどれぐらいかかるのかというのと、あと、品川駅自体は港区なのですけれども、品川区民に向けてということなのか、それとも品川区の魅力をアピールしたいみたいな、どういった狙いで品川駅になったのでしょうか。以上２点、お願いします。","respondent":"大森文化観光戦略課長","answer":"金額は、「ミュージアムめぐり」の掲載と品川駅のサイネージを合わせまして、２７万円になります。","voiceIndex":125,"id":"exchange-051"}]},{"id":"topic-05","title":"品川区立総合区民会館における指定管理者候補者の公募","agenda":"品川区立総合区民会館における指定管理者候補者の公募","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３の（３）なのですけれども、施設の維持および修繕に関することというのが主な業務とあるのですが、大ホールの修繕とか、大きな修繕などでは区が費用を負担している現状があると思うのですけれども、ここにはこういうふうに維持および修繕とあるのですが、指定管理者の契約上、そこら辺のすみ分けというのでしょうか、どうなっているのかというのをお伺いしたいと思います。","respondent":"大森文化観光戦略課長","answer":"こちらは、５０万円以下の金額のものについては指定管理者側で修繕をお願いするということで契約内容に入っているものです。","voiceIndex":131,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、５のところなのですけれども、選定基準というところで、2)で経費の縮減を図るということがありまして、一方で、3)で会館の管理を安定して行う人的能力を有しているものというのがあるのですけれども、ここは矛盾しているのではないかと思ってしまうところがありまして、経費の縮減を図るということを求められると、大体人件費を削るのではないかと思うのですが。","respondent":"大森文化観光戦略課長","answer":"3)人的能力とか、そちらに影響が出てしまうかというところにつきましては、まず、物的能力については、その業者が持っている車椅子だったりとか筆談機だったりだとか、そういったところの持っているものを使っていただきたいと思いますし、人的能力に関しましては。","voiceIndex":133,"id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"でないと、私たちは何をもって提案したのかも分からないので、そういった点数化も含めて、次回の議決の際には、このような審査を行いましたということで、調査報告書を、評価報告書みたいなものも含めて、ぜひ提出していただきたいのですけれども、そのように改善されるお考えはあるでしょうか。","respondent":"大森文化観光戦略課長","answer":"報告の様式についてということなのですけれども、できるだけ透明性とか公平性といったものを重視して選定していくということがこちらのプロポーザルの主たるものだと思いますので、議会の皆様に対してもできる限り分かりやすい説明ができるように心がけてまいります。","voiceIndex":135,"id":"exchange-054"},{"speaker":"藤原委員","kind":"確認","question":"指定管理ということで、品川区は十何年の歴史があると思うのです。最初に指定管理をきゅりあんに導入してから、私の記憶だと、ずっと同じところが選定されていると思っているのですけれども、まず確認ですが、それでよろしいのでしょうか。","respondent":"大森文化観光戦略課長","answer":"１回目から指定管理者に選ばれているところは、公益財団法人品川文化振興事業団となります。１回目から今回で５期目となります。","voiceIndex":138,"id":"exchange-055"},{"speaker":"藤原委員","kind":"意見","question":"ずっと文化振興事業団ですよね。それは、きちんとした公募をして、きちんとした審査をして、点数もつけて、ここの団体しかないと。なぜならば、これ以上言えませんけれども、これこれこういう理由だとなってしまったら、公募の意味とか民間を活用するとかという大前提が崩れてしまっていると私は思うのですけれども、担当の課長として、この辺、どう考えますか。","respondent":"大森文化観光戦略課長","answer":"そこにについて、非公募という話になると、やはり実績ですとか経験値で文化振興事業団が選ばれてきていたのではないかと思うのですけれども、ここに関して、課長としての考えとしては、特に文化振興事業団が指定管理という部分に、貸し借り業というか。","voiceIndex":140,"id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"だから、なのですね。だって、前職が副区長ですよね、その方が行かれているわけですから、品川区の意向もいろいろ話し合ってできるという意味で、私はすばらしいと思っているのですよ。そのように力強く課長が、そのとき担当の課長ではないかもしれないですけれども、そういうふうに言ってくれるように私は心から希望してこの質問を終えたいと思うのですけれども、その辺について、いかがでしょうか。","respondent":"大森文化観光戦略課長","answer":"今のご質問に対してなのですけれども、公募に応募していただくというところだけはどうしても左右できないところがあるので、これが少ないのか、多くなって非常にいい提案を得られるのかという状況にあるのかどうなのかというのは、今、言えないところではあります。","voiceIndex":144,"id":"exchange-057"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私から１点だけ。社労士を入れてのモニタリングを入れていますというご答弁をいただいて、今の段階ではそれをいただいていると思うのです。その１つとして、労務について社労士を入れたモニタリングをぜひ入れていただきたいと思うのですが、今のところ、そのご予定はどうなっていますでしょうか。","respondent":"大森文化観光戦略課長","answer":"なので、選定のところで入れるというよりは、やはり始まってから入れるほうがよろしいのではないかなと考えていますので、その辺り、区のほうでしっかりと気持ちよく働ける環境というか、そういったところも管理してまいりますし。","voiceIndex":147,"id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ただ、やはり事業者を選ぶに当たっても、その事業者がきちんとそこで働く人たちの労働環境をどのように考えているかというのも、ぜひ評価点の、それが社労士を入れたモニタリングかどうかはまた別として、その視点は持っていただいていると思うのですけれども、その点についての評価も、今後、選定の中に入れていただきたいと思うのですけれども、その点については現状どうなっているのでしょうか。","respondent":"大森文化観光戦略課長","answer":"提案による採点と、あとは実際にプロポーザルによる採点という２段階で評価して進めていくというところがありますので、そういったところの表記があるのかどうなのかとかというところで点数を配分していくというのは、今から採点表を作成していくに当たって。","voiceIndex":149,"id":"exchange-059"}]},{"id":"topic-06","title":"品川区立体育館における指定管理者候補者の公募","agenda":"品川区立体育館における指定管理者候補者の公募","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"３番目のところなのですけれども、（２）に事業の運営というのと、（５）に自主事業というのがあるのですけれども、先ほどのきゅりあんの場合ですと、（２）がなくて自主事業しかなかったのですが、（２）と（５）は実際にどんなことを今やっているのかというのを改めてざっとご説明いただければと思います。","respondent":"守屋スポーツ推進課長","answer":"（２）の体育、スポーツおよびレクリエーションに係る事業ですが、これは基本的に体育館で実施しておりますスポーツ事業であるとかレクリエーションに係る一般的な事業の運営に関することでございまして、こちら、（１）から（２）、（３）、（４）、（６）につきましては。","voiceIndex":155,"id":"exchange-060"},{"speaker":"安藤委員","kind":"提案","question":"例えば自主事業というのはどういうことをやっているのかというのがあるとイメージしやすいというのがあるので、後でお願いしたいのと、それと、こちらも簡易型プロポーザル方式（公募型）ということで、募集要項を見ますと、提案書の提出を受けて、ヒアリングを実施した上で、審査および評価を行って、選定するとあるのですけれども。","respondent":"守屋スポーツ推進課長","answer":"評価項目につきましては、具体的な詳細までは決まっておりませんが、基本的に選考基準といたしまして、応募者の経営状況とか、業務実績ですとか、提供するサービスの提案内容ですとか、業務への取組体制ですとか、かかる経費等を主な内容として、採点というか。","voiceIndex":157,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"こちらもずっと同じ業者だと思うのですけれども、公募するというところで、今回幾つ来るのかというのはこれからなのですが、公募の仕方というのですか、どういうふうにしていく考えなのか。もう少し積極的に、例えば目ぼしいところにこちらからこういう公募をしていますよというお知らせまでするのか、それともホームページに載せて終わりということなのか、そこら辺の実態だけ教えてもらえればと思います。","respondent":"守屋スポーツ推進課長","answer":"ただ、私どもがお聞きしているのは、指定管理者を受託する会社というのは、ネットとかで、いつ、どこの自治体で指定管理が開始されるという情報を把握されているようですので、こちらから特段、特定のところにお声かけするということはないのですけれども。","voiceIndex":161,"id":"exchange-062"},{"speaker":"ゆきた委員","kind":"提案","question":"行政のプロポーザルについてですけれども、先ほどのきゅりあんのほうにも関わってくるのですが、こちらの区立体育館のほうですけれども、「５.指定管理者候補者の選定」の（３）選定基準で、利用者の平等な利用およびサービスの向上を図るもの、2)体育館の適切な維持および管理ならびに管理に係る経費の縮減とありますが、やはり競争原理を働かせていかなければ。","respondent":"守屋スポーツ推進課長","answer":"２番目の体育館の適切な維持および管理ならびに管理に係る経費の縮減を図るものというところですが、安定的な運営のところにはやはりそれなりのスタッフや費用が当然かかってしまうところだと思っているのですけれども。","voiceIndex":164,"id":"exchange-063"},{"speaker":"ゆきた委員","kind":"提案","question":"今後の予定で、６月に募集要項の配布となっていますけれども、おっしゃるとおりで、1)、2)はそのとおりなのですが、サービスの向上、あと管理に係る経費の縮減というところも、具体的に選定基準がどうあって、どこに勝負をかけていけば提案が評価されるのかという、そういう選定基準が明確になければなかなか難しいと思うのですけれども、ここについてもう一度。","respondent":"守屋スポーツ推進課長","answer":"一定の応募を求める中身につきましては、応募要項の中に記載しますので、事業者の皆様にはそこでご理解いただくとともに、応募いただいた会社には必ず現地説明会に参加していただくことが必須となっておりますので、体育館であれば、それぞれの体育館に行っていただいて。","voiceIndex":166,"id":"exchange-064"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"デフリンピックも大事ないろいろ、いよいよ今年ということで大事なのですが、所管課として、デフリンピックの開催を議題にした話合いというのですか、当事者である聴覚障害者協会と、例えばデフリンピックを区内でどう盛り上げていきましょうかみたいな、そういう話合いをしたことがあるのかどうか伺いたいのと、そういうテーマで一度、障害福祉課だけではなく。","respondent":"守屋スポーツ推進課長","answer":"聴覚障害者団体の区内、協会と……。","voiceIndex":172,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区内に、区役所を含め、区有施設は山ほどあるのです。そこというのは品川区の施設なので、品川区の一存で掲示ができるわけです。駅には毎日多くの方が足を運ぶわけですから、駅への掲示をお願いするということをぜひやっていただきたいのですけれども、そういった話というのは、ポスター掲示というのは、私たちも協会の皆さんから聞いたのですが、どうでしょうか。ぜひやっていただけないでしょうか。","respondent":"守屋スポーツ推進課長","answer":"新しいポスターをつくるとなりますとどうしても経費がかかってきてしまいますので、作成するということはすぐには難しいとは考えておりますけれども、引き続き、既存のもの等を活用しながら、地域に対しての細やかなＰＲ等を進めていきたいと考えております。","voiceIndex":176,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"デフリンピックは１１月１５日から開催ということで、まだもう少し時間があるわけです。だから、やはり最大限そのチャンスを活かすべきだと私は思うので、ぜひ当事者の話に耳を傾けていただいて、必要な予算もつけて、普及啓発を推進していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7043#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":48846,"voices":182}},{"id":"r07-20250512-7","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"厚生委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"前と同じような特養ホームとショートステイということで、すごく安心しました。「以上」となっているので、前も公募で事業者からのこういう提案だったのか、そこのところは確認していないのですけれども、そういう条件としては変わっているのか。それであれば、その理由も教えていただきたいと思います。それから、もう公募をして、応募の見通しというのがあるのか、その点についても伺います。","respondent":"東野福祉計画課長","answer":"現在、何社かから問合せをいただいておりますので、応募につきましては、意思があるところが十分確保できるのではないかと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"補助も増額されて、既に問合せもあるということで、ぜひ特養ホームができる限り早くに開設できるように、取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"品川区立平塚橋特別養護老人ホームおよび品川区立平塚橋高齢者多世代交流支援施設（平塚橋ゆうゆうプラザ）指定管理者候補者の選定","agenda":"品川区立平塚橋特別養護老人ホームおよび品川区立平塚橋高齢者多世代交流支援施設（平塚橋ゆうゆうプラザ）指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"７月に予備委員会で、８月には選定委員会ということなので、そこら辺のところも、もう決まっているのかと思うのですけれども、伺いたいと思います。待遇の部分や何かも含めて、ここのところは大丈夫なのかということについても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"３つ目の、選定委員会等についての資料の報告等の、こちらの議会に諮るときの報告書の内容については、公募のときと非公募、全く変わりませんので、同じような形で報告書は提出させていただきまして、審議をしていただく予定となっております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"意見","question":"だから、それはそれで本当に介護全体のことですので、人材確保ができるような、そういうところへの介護の充実というのが本当に大事だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"今回、非公募ということでやられるということですけれども、これ、今、人材不足というご答弁がありましたが、非公募の場合、当初の運営期間終了後、連続して１０年を限度とするという縛りがあると思うのですけれども、今回、次の５年終わった後はまた公募にかけるということでよろしいのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘のとおり、こちらの施設は平成２８年５月にオープンしましたので、ちょうど今回で１０年ということになります。次の５年で連続して、更新期間１５年が限度となっておりますので、次は公募という形を取らせていただく予定です。","voiceIndex":16,"id":"exchange-005"}]},{"id":"topic-03","title":"品川区健康危機対処計画（感染症編）策定","agenda":"品川区健康危機対処計画（感染症編）策定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"そういう中で人材の確保というところをどう考えられているのかというところを伺いたいのですけれども、厚生労働省で出している保健所における健康危機対処計画（感染症編）策定ガイドラインというところでも、保健所の体制というところをしっかりと行い、そして、人材の確保、それから育成、そこのところを計画の中にも記載することが必要だということで書かれていたのですけれども。","respondent":"五十嵐保健予防課長","answer":"すみません。こちらには項目出し的なところしか書いていない部分もありますが、基本的には、保健師であれば、感染症の対応ができるようにすることが必要と考えております。","voiceIndex":22,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"保健師たちからも、すごく現場としては、せっかく新たに入られた方が、現場がすごく大変で辞められたりだったりとか、定年まで働き続けるのがすごく不安という声も、大変な労働強化の中で、今でもそのような状況だということは伺っていまして、そこに新たなこういう計画がつくられて、研修だったりとか、それだけでなく、また今度、これから報告がありますけれども、５歳児健診だったり、産後ケアだったり。","respondent":"五十嵐保健予防課長","answer":"ほかの区ですと、管理職になられている保健師なども多かったりする部分もあるのかと思いますが、その中でも、基本的にはやはりふだんの仕事につきましても、プリセプターなどがついて、指導しながらやらせていただいている中で。","voiceIndex":24,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのような答弁があったと思うのです。そこら辺のところは、現場としても認識はしていただきたいと思います。それと、このガイドラインを見ていましたら、「健康危機管理を含めた地域保健施策の推進のために本庁に統括保健師を配置する」ということもあったのですけれども、この統括保健師ということに対しての品川区の考え方はどういうことなのかということも伺いたいと思います。","respondent":"高山健康推進部次長、五十嵐保健予防課長","answer":"大変、感染症から福祉、それから母子保健など様々な分野を経験してきた、言ってみれば、保健師の中の保健師のような、有用な経験をたくさん積んできた保健師を統括的なポジションとして位置づけるということで。統括保健師、今のように置かせていただいているところではありますが、いきなりいろいろなこと全ては難しい部分があるかと考えていますので、まず、保健予防課でできる部分、感染症の部分は感染症でやりつつ。","voiceIndex":26,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう計画をつくって、やはり実際にこれからやっていくというのが、現場に新たないろいろな施策が区民にとっては本当にプラスになるということでいいと思うのですけれども、そういう新たな施策が、ただただ現場での労働強化にとなるのではなくて、それに対してはしっかりと体制をつけるということでぜひともそれをお願いしておきたいと思いますし、２３区平均まで計画的に保健師の数を増やしていくという。","respondent":"五十嵐保健予防課長","answer":"その状況に応じまして、いきなりコロナのような感染症の対応とかではなく、はしかが出たときにどうなるのかとか、そのような小さいところから少しずつやっていって、大きなところに広げていくというイメージを持っておりますので。","voiceIndex":29,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"確認","question":"このたび品川区健康危機対処計画の策定ということで確認でお伺いしたいのですけれども、コロナ禍のときに、品川区内のデイサービスでコロナ感染者が職員で出ました。","respondent":"五十嵐保健予防課長","answer":"すみません。当時私、品川区にいなかったので、品川区の状況は存じ上げておりませんが、ほかの区でも同様のことをやっている区もありましたし、私がいた区でもそのようにしておりました。","voiceIndex":32,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"当然、品川区の保健所の方は非常に一生懸命やられていたことは理解するのですけれども、こういった送迎を介護施設に強いたり、かなりリスクの高い検査を実施したりということをしていたという実態はかなり改善すべきことかとは思っておりますので、ぜひこういった事実、以前、委員会でこの話をしたときに、そんなことがあったのですかみたいな感じの理事者の方の答弁だったと私は記憶しているのです。","respondent":"阿部品川区保健所長","answer":"品川区は、他の自治体よりはるかに濃厚な調査をまとめた検討報告書を出しましたけれども、私たちはその中で、最初の頃にはなかった、例えば、外部の協力を得た、患者あるいは感染可能性のある方の移送のための車両の確保ですとか、あるいは、最終的には区の職員だけではなく。","voiceIndex":34,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問","question":"１点、今、人材不足のお話があって、医療機関で私、コロナ禍でまさに働いていたときに感じたのが、お子さんを育てている看護師の方が、学校が休学になったりとかして、子どもが家にいるから病院に来たくても働けないのですというお声だったり、コロナの患者が入っている病棟だと、子どもを預けたくても、医療従事者関係の方の通園はご遠慮していますみたいなことを言われたというような報告を受けていて。","respondent":"五十嵐保健予防課長","answer":"医療従事者等への風評被害はかなりあったと思っていますし、私も実際対応している中で感じた部分はございました。","voiceIndex":37,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問・要望","question":"風評被害だけではなくて、学校が休みになってしまって、子どもが家にいるから見ないといけないみたいなところは大きな課題かと思っていて、そこは区でも、そこで働いてくださる方のための子どもたちを預ける場所みたいなところまでできると、実際の病院はもう少し回ったのかと思っていて、難しいですか。そういうところもぜひ検討いただきたいと思います。何かあれば、お願いします。","respondent":"五十嵐保健予防課長","answer":"確かに学級閉鎖等もいっぱいさせていただきましたし、特に初期の頃に至っては、過剰なぐらいやっていたかという思いもなきにしもあらずな部分はあるのですけれども、やはりなかなか状況が分からない中ですと。","voiceIndex":39,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"１ページのところの背景と目的というところの２段落目のところに、「ＩＨＥＡＴの法定化等の措置が講じられた。","respondent":"五十嵐保健予防課長","answer":"ただ、なかなか東京都に登録してくださっている方がそんなに多くないという現状もございまして、なかなか難しい部分もありますが、そういう外部人材の活用も必要だと考えていますので、そういう方に対して検証させていただいたりということも必要かと考えていますので。","voiceIndex":42,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、区内でそういう資格を持っている人が登録をしてもらうということの呼びかけだったりとか、そういうものはどこかにされていて、ぜひ登録をしてくださいという取組というのは既にされているのでしょうか。それであれば、どんな取組をされているのかも伺います。","respondent":"五十嵐保健予防課長","answer":"すみません。今、積極的にどこかで募集をしているということは書かせていただいていないところですが、コロナの終わった頃に関しましては、少しそういう話は出ていたのかと思っているところです。","voiceIndex":44,"id":"exchange-015"}]},{"id":"topic-04","title":"令和７年度５歳児健康診査事業〈モデル実施〉","agenda":"令和７年度５歳児健康診査事業〈モデル実施〉","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"それでも２５０人とか３００人になるのか。その点を伺いたいと思います。なぜここあぽになったのかと聞いたのは、５歳児健診マニュアルとかというのがあったのですけれども、そこのところを見ると、ＳＤＱというもので問診を取るということが例として挙げられていたのですが、そういうものではなく、ここあぽということで発達障害についての問診票ということにしたのかという、その理由を伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"ＳＤＱというアンケートを活用してスクリーニングをやっている他自治体が結構いろいろ調査したところでは多くて、そこでスクリーニングをかけて健診につなげているという自治体もあるのですけれども、ＳＤＱが、版権の関係で。","voiceIndex":51,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"今の説明でよく分からなかったのですけれども、５歳児健診というのは、イコール集団健診のことですよね。それで、そのときに、ここあぽのところをいろいろと見ていたら、この問診票を使って２割ぐらいに絞れるということも書いてあったのですけれども、そういう形で、リスクの高い子どもに絞ってだけ集団健診を行うということになっていくということなのでしょうか。そこのところをもう１回教えてください。","respondent":"石橋品川保健センター所長","answer":"品川区としましては、保護者のアンケートおよび心理職の集団観察というところも一つの健診と考えて実施をするということになりますので、健診は一応、年中クラスの１２園の全児童に対して同意を得られたご家庭には全て実施をしていくという形で。","voiceIndex":53,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。だから、アンケートと心理職による集団観察というのも含めた、そこが５歳児健診と。だから、集団健診イコール５歳児健診というわけではなくて、アンケートの段階のところから５歳児健診という考え方だということなのですね。やっと分かりました。その心理職をどこにどういう方に委託をするのか、そして、その心理職の集団観察というのはどのように行われるのか、その点についても伺います。","respondent":"石橋品川保健センター所長","answer":"心理職の委託先というところになるのですけれども、こちらについては、今、心理職ということで、園のほうで相談事業等を心理職がやっているところもありますので、そういったところも園と連携を取って、そのような心理職の方の活用ですとか、そういったことも含めて、あとは。","voiceIndex":55,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"それなので、例えば、これは発達障害についての問診票ということですので、発達障害についての、保育園だったりとか、保育園の職員も含めて、そういうものの研修というか、それをどう捉えるのかということをしっかりと研修をしていかないと、私は子どもに対してそういう見方で職員自身が見てしまうというか、そのようなことも避けなければならないと思いますし、そこのところを見て。","respondent":"石橋品川保健センター所長","answer":"今、保育施設運営課とも、その辺りについては、保育園でもしっかりそういった知識を深めていただくこと、また、今回対象になる園の保護者に対しては、保健センターのほうでしっかりと早期に気づくことの重要性というものも含めて丁寧に伝えするということで。","voiceIndex":57,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"確認","question":"それと、あと、集団健診に進んだときに、集団健診をどう行うのかというあたりは、ここでは書かれていないのですけれども、１１月なので、また改めて報告があるのかどうか分からないのですが、集団健診のやり方とかもいろいろとホームページとかを見たら出ていまして、医師や保健師はもちろんなのですけれども、そのときに専門職に相談できるという体制も必要ということで、管理栄養士だったりとか。","respondent":"石橋品川保健センター所長","answer":"先ほどの研修の場というところになりますが、現時点では研修の場をしっかり設けるという回答はこの時点ではできないのですけれども、私どもとしては、しっかりと保育士や保護者の方にはそのことを認識していただくということは必要だと考えておりますので。","voiceIndex":59,"id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"すみません。何点か知識不足もあるので、教えていただきながらと思っているのですけれども、５歳児健診でモデル実施ということですが、私がお聞きしたいのは、子ども、幼児にとって何が一番大切なのかというのをどこに見ているのか。そうすると、どういうことを求めているのですかというのがよく分からなくなってくる。そこら辺のところをもう少し分かりやすく説明してほしい。なかなか理解できなくて。","respondent":"石橋品川保健センター所長","answer":"今回、そういったことも考えて、一応、全園実施、１園ずつというところにもなってしまうかもしれないのですけれども、全園やってみて、その辺の幼稚園ですとか保育園のカラーというところもしっかり認識しながら、モデル園ということで、次年度以降、例えば。","voiceIndex":65,"id":"exchange-021"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だけれども、今、品川区はこれだけ子育て支援をやっているわけではないですか。一緒にどうやっていろいろな、何でもいいのです。公立幼稚園は、データがある程度、２年保育だから、初年度は結構大変かと思う。これは答弁できないかもしれないから要望にしておきますけれども、それのほうが私はいいと思います。そうしたら、答えられるような答えをつくってもらうために、一般質問か何かでやります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今回、品川区がここあぽのアプリでやるということなのですけれども、２３区でここあぽを使っている区というのはどれくらいあるのか。他区の状況で、５歳児健診がどんな状況になっているのか。それを伺いたいと思います。２０２８年までには全ての子どもにやっていくという方向というのは取られるのか、そこの点についても伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"いやいや、２０２８年までにはと国が出しているのです。これに対してどう考えられているか、伺います。","respondent":"石橋品川保健センター所長","answer":"それぞれお子さんの数も違いますので、それぞれの手法で実施をしているところになります。２０２８年１００％というところになるのですけれども、一応、品川区としましては、今回モデル実施をしまして、次年度以降どう実施していくかの検討を考えていくところになります。","voiceIndex":72,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"児童発達支援のところが、ここの障害児福祉計画の中でも、見込量というのが、計画の９９ページのところに児童発達支援のところも出ていますけれども、そこのところというのは、ここの中で指摘された子どもたちがきちんとフォローできるような、そういう見込量だったりとか、それから、そういう受け入れる整備だったりとか、そのようなところはどう考えられているのか、そこのところも伺います。","respondent":"石橋品川保健センター所長","answer":"健診後のフォローという形についてになりますが、ごめんなさい、その前に、保護者に対しての再度サポートというか、フォローというところになりますが、保護者に対してのフォローに関しまして、繰り返しの答弁になりますが、そこについてはしっかりと丁寧に説明を。","voiceIndex":74,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、この５歳児健診をやって、そのような支援が必要だという結果が出たときには、その支援が受けられるという体制は、障害者福祉のほうとしっかりと連携を取って、どのように、どれぐらい想定されるだろう、所要量もしっかりと出して、そして、今足りない分も含めて所要量をしっかりと出して、そこのところが支援につながる、支援がしっかりと受けられる、そういう施設の整備。","respondent":"石橋品川保健センター所長、阿部品川区保健所長","answer":"その辺り、しっかりと認識していくことがとても重要だとは捉えております。委員ご指摘のとおり、今後、関係各課としっかりと調整をして進めてまいりたいと考えております。この実施を通じまして、今回モデル園にならない園への理解、協力も求められるようなことについても、できれば取り組んでまいりたいと考えています。","voiceIndex":76,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当にこれは健診をやったことによって、でも、６０人ぐらいは集団健診に行くだろうということで想定がされているわけですから、ここの中でしっかりとフォローの体制、それから支援の体制、そこのところをセットでやっていただくということで強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-027"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）副委員長","kind":"提案","question":"改めまして、１年間ありがとうございました。松永委員長の下で様々、皆様からいろいろ、委員の皆様からもご意見をいただいて運営をしていくという形の中で、行政の皆様にもいろいろなご提案、ご提言ができたと考えています。１年間ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7041#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":31021,"voices":85}},{"id":"r07-20250512-8","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"建設委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)羽田空港周辺地域における地価動向分析調査結果","agenda":"はじめに、(1)羽田空港周辺地域における地価動向分析調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、国のほうが不動産価格への影響から調査したということで、それは一つの指標として調査かなと思うのですが、残念ながらというか、不動産価格への影響は確認できなかったという結果だということで、まず確認させていただきたいのですけれども、今回この地価の動向を分析したということで、そもそもの不動産価格というのはどういった要因から決まってくるのかというところ。","respondent":"高梨都市計画課長","answer":"最後に、不動産を購入する、賃貸等する際の重要説明事項に羽田新飛行ルートに関することが記載されるかどうかということは、そちらについては区のほうで記載されているかどうかということを調べた調査結果等ございませんが。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"そう考えてくると、今実際全体として都内では地価が上がっていると、全体的に上がってきているということで、年代別というか運用前と運用後では、運用前のほうが上昇率が高いですけれども、運用後も結局は上がっているという状況ですけれども、やはりそれが全体としてはそういう流れの中で、またいろいろな要素がちょっとあり過ぎて、これをどう見たらいいかというのもなかなか難しいのですけれども。","respondent":"高梨都市計画課長","answer":"最初に、新飛行ルートの影響を区としてはどのように考えているかといった部分につきましては、今回、不安の声を受けて国が実施した調査結果は、一定その公示値をベースとしたデータで、全体の地価の上昇下落の動きの中で、新飛行ルートのルート下であること。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今までのお話を聞いている中で、この羽田新ルートについては、不動産の契約のときには重要説明事項では一般的にはないというお話で、そうすると実際いろいろ契約をする際に、この羽田新ルートのことを知らないで契約をしているという方もいるのかなと思います。区としてはなぜ影響があるということで声が上がっていると思うのか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"引き続き、不動産価格以外に区民の方々が感じていらっしゃる様々な声があろうと思いますので、そういった声につきましては、区としてしっかりと国に届けてまいりたいと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としてぜひ、実際なぜこういう声が上がるのかというのをつかんでいただきたいと思います。ほかの調査もぜひ、ほかにもアンケートで電波障害とか様々な影響が出ておりますので、引き続きほかの調査もやっていただくように国に求めていただきたいと思いますし、区としても、国がやらないのであればぜひ実施をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"調査結果ということでご説明がありました。伺いたいのは、この調査結果に対する区の評価を伺います。先ほども記載の結果が得られたと思うとか、書かれてあるとおりというお話がありましたけれども、不動産価格への影響は確認できなかったとする国の調査結果について、品川区はどのように見ているのか。国と同じく影響がないと区も評価しているのか。区の立場をご説明いただきたいと思います。","respondent":"高梨都市計画課長","answer":"全区民アンケートを実施させていただきまして、その中にも不動産価格の影響を懸念するといった選択肢を選んでいただく問いもございましたし、また自由意見の中でもそういったご意見がございました。","voiceIndex":12,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、区としては不動産価格の影響は確認できないという国と同じ立場なのか、それとも、いや、国とは違う立場であればどういう立場なのか。この間のやり取りを振り返ると、それは別に区が表明するものではなくて、実施責任者である国が調査し評価するもので、区としては影響があるともないとも言う立場にないというものなのか、その区の立場を改めてご説明いただきたいと思います。","respondent":"高梨都市計画課長","answer":"先ほども一部答弁をさせていただきましたけれども、今回公表されたこの調査結果についてのこの条件の中では、一定、公示価をベースとした地価の変動率といったところにつきましては、新飛行経路の影響がないとしたという国の結果について。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"つまり公示値で把握をするというところで、家を買ったり売ったり、家を借りたり貸したり、不動産という立場に私は立ったことがないですから、公示値というものが実際の売買だったり実際の賃貸借契約にどれほど影響するものなのかというのは実感がないもので、ぴんと来ないというのが私の正直なところですけれども、品川区の公示値と言っても、あちらとそちらで良いところ、また道路付けが悪いところ。","respondent":"高梨都市計画課長","answer":"私もその地価動向分析について、専門的な知見を持ち合わせているわけではございませんけれども、国によりますと、過去も羽田新飛行ルート運用開始前も、大阪空港と福岡空港において同様の調査を同じような手法で実施し。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"最後に、様々な声を今後も伺うということです。その影響で、羽田新ルートによるマイナスの影響が隠れてしまっている、上昇のほうが上回っている、それが実体なのではないかなというのが私の実感だけでしかないのですけれども、やはりそういう動きが一番敏感なのが、地元の不動産業界の方々や直接のオーナーだと思うので、区としては何か声が寄せられているのか、そこを最後に伺いたいと思います。","respondent":"高梨都市計画課長","answer":"一般区民の方からメールや電話等でお問合せを受けているところですけれども、参考までに申し上げますと、令和６年中、令和６年４月から令和７年３月の１年間で寄せられた内容のうち、不動産関連。","voiceIndex":18,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"業界からはないというところですけれども、それぞれが実際どのように思っていらっしゃるのか、ぜひ把握に努めていただきたいと思います。その後、その実態はどのように変化していくのか、国の調査とともに、区としてもそれを細かに把握して、区としての知見といいますか、見解を持っていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"}]},{"id":"topic-02","title":"リニア中央新幹線オープンハウス型説明会の開催","agenda":"リニア中央新幹線オープンハウス型説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そして順次行っていくということですが、次をやるときはいつ頃になるのかというのを伺いたいと思います。やはり教室型でやることによって、様々な問題点、自分の気づかなかった問題点などを共有したりすることができるということで、ぜひ教室型説明会の実施をＪＲ東海に求めていただきたいと思いますけれども、いかがでしょう。","respondent":"大石まちづくり立体化担当課長","answer":"最後、教室型説明会を求めるべきですけれども、区といたしましては区民からの不安の声や質問に丁寧に対応することが重要と考えてございまして、その手法につきましては、当然教室型説明会を含め様々なものがあると認識しています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"シールドマシンが１か月で数百ｍ進む距離があると思うのですけれども、そこから、そうすると１か月で何kmだったか、１か月、２か月後にまた説明会をやるということになるのか。そうすると、１か月後だと結構短いというか、またお知らせがどうなっているのか、しっかりその対象地域にやれるようにしていただきたいと思うのですけれども、そうした関係を伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の教室型説明会につきましては、ちょっと先ほどの答弁の繰返しになりますが、区といたしましては不安の声やそういったご懸念にしっかりと寄り添うことが重要と考えてございまして、その手法につきましては、教室型説明会も含めまして様々なものがあると認識しています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"今後やはり本格的な掘進を行っていくために今回説明すると言っていますけれども、やはりそういった原因がしっかり分からないうちに本格掘進を進めていくということは、区内の住宅街にも大きな影響を及ぼしかねないというものだと思いますので、そこはしっかり原因究明していくことが必要なのではないかと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"質問の１点目の、今後もオープンハウス型説明会を開催される際は議会へ報告されるのかですが、基本的には報告しようと考えているところです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"今、気泡などの影響については観測井戸で調査をしているということで、その調査結果などを聞いているところがあれば伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"現在のところ、ＪＲ東海からは、周辺に影響を及ぼすような結果は得られていないと聞いているところです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"影響を及ぼすような結果がないというのは、つまりどういうことでしょうか。水位の変化があるとか、気泡が出ているとか、水質が変わったとか、内容を伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海は、酸素濃度測定を行っていると聞いてあります。そちらで周辺環境に影響が認められるような結果は確認されていないです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、このリニア中央新幹線の事業は国土交通省が認可されているということで説明がありましたけれども、やはり国が認可しているというのはありますけれども、実際に住んでいる区民に影響が起こりかねないというこの大深度地下のリニア中央新幹線の工事ですので、そこは区としても当事者意識を持って、やはりこの原因究明をしっかり求めていくと、それまではやはり本格掘進しないようにと。","respondent":"大石まちづくり立体化担当課長","answer":"そういったところから、区といたしましてはＪＲ東海に対し、数回にわたり要請文という形で安全を確保するよう要請したり、区民の声にしっかり応えるようしっかりと要請しています。引き続き区といたしましては、必要な要請を行ってまいりたいと考えているところです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"目黒川の気泡のことについて今もやり取りがありましたけれども、このオープンハウス型説明会のいわゆる説明パネルというのでしょうか。何かパネルの説明資料はホームページで確認できるのですか。そこは今後なのでよく分からない、そこについてご説明いただきたいと思います。そもそもそのパネル展示の中身を事前に区が把握しているかどうかも私には分からないので、まずそこをご説明いただきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今回のオープンハウス型の説明会につきましては、ＪＲ東海からは、まず気泡につきましては５月に開催するオープンハウス型の説明会にて、泡の状況などについて説明する準備をしていると聞いているところですが、その内容やその手法につきましては。","voiceIndex":37,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"２つ目が、やはり地上への影響について、先ほどもどのような説明がされるのか、現状では区としては把握が難しいというお話でしたけれども、やはり地上への影響について、ＪＲ東海としての立場といいますか見解をきちんと説明するように、区としてＪＲ東海に求めていただきたいと思うのですけれども、いかがでしょうか。測定の方法と、測定の結果が数値で公表されているのか。","respondent":"大石まちづくり立体化担当課長","answer":"ほかの説明会でそういったご意見があったということは認識していますので、そういったことも含めまして要請していますので、引き続き必要な要請を行ってまいりたいと考えているところです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで安心してくださいとは全くなりません。なので、測定地点であったり測定の方法であったり、測定の結果の数値の公表であったり、これは区として公表をＪＲ東海に求めるべきだと、それが説明責任を果たすということだと思うのですけれども、その点は区としてＪＲ東海に箇所、方法、数値を公表するよう求めるべきだと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"今、行っております酸素濃度測定の結果の公表等、まずＪＲ東海のほうは５月に開催するオープンハウスの説明会で、目黒川の泡の状況などについて説明する準備をしていると聞いてありますので、そちらの内容をしっかりと区として注視してまいりたいと考えているところです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言意見を述べますけれども、説明会ですから、しっかりと説明パネルに気泡のことや、また地上への影響のことについて、区としてＪＲ東海に要請していただきたいと思います。現状において、リニア中央新幹線の工事を進めるべきではないと思いますし、またリニア中央新幹線工事に合わせた開発も中止して、まずは今起きている事態に対して必要な丁寧な説明を尽くすということだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"}]},{"id":"topic-03","title":"みどりの実態調査の結果","agenda":"みどりの実態調査の結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"緑被調査によってみどりが増えたというご説明ですけれども、その増加の要因をもう少し伺いたいと思います。特に樹木被覆地の７.６haのほうですけれども、この樹木被覆地が増えた要因が、先ほど公園もちょっと聞こえたのですけれども、増えた理由を伺いたいと思います。","respondent":"大友公園課長","answer":"樹木被覆地の増加というところにつきましての理由、改めてご説明しますと、樹木の成長のほか、区内各地の集合住宅地などの建築や公園の新設に伴い、緑化が増加したものです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"もともとの計画が水とみどりの基本計画・行動計画ということで、申し訳ないですけれどもそれほどこれに直接詳細に私が目を通したわけではないのですけれども、今のご説明ですと、このまちづくり計画が、結果みどりを増やすことにもなっているとおっしゃいましたけれども、つまりこの水とみどりの基本計画・行動計画も、再開発を進めることで。","respondent":"大友公園課長","answer":"まちづくりの中においてみどりを確保するというような記載の中において、結果としてこのまちづくり、敷地３００m2を超えるような場合については緑化指導を行っておりますので、そこにつながっているという形になるです。","voiceIndex":50,"id":"exchange-021"},{"speaker":"中塚委員","kind":"意見","question":"やはりみどりを増やしていくというのであれば、高層化によってＣＯ２排出を増やすのではなく、高層化そのものを規制しつつ、また木密地域における住民の皆さんとの合意で公園を増やしていく、そうした方向に向いていくことが必要だと述べたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"この緑被率を増やしていくということは、環境問題の地球温暖化などの問題でも重要なことだと思います。実際どのように今後この結果を活かしていくかということだと思いますけれども、具体的に増やす取組を考えているのかということを伺いたいのと、今回接道部では減ってしまったということ、この原因を伺いたいと思います。","respondent":"大友公園課長","answer":"こちらの計画に基づいて実態調査を行っているところなのですけれども、水とみどりの基本経過・行動計画の中には１２の施策があり、数多くの事業が設置されているところにあります。","voiceIndex":53,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど３００m2以上は緑化指導しているということでしたので、ぜひ緑被率が上がるようにしていっていただきたいと思いますし、先ほどもありました、結局超高層マンションなどができても、エネルギーの消費量がそこで急激に上がるということですから、そうした開発で、地球温暖化への貢献というのは結局プラスマイナス、むしろマイナスになってしまうのではないかなと思われますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-024"},{"speaker":"横山委員","kind":"質問","question":"幾つか順番に伺ってまいります。屋上緑化も面積自体は増加しているのですけれども、また箇所が前回のときよりも少し減少しているのですけれども、こちらは何か特殊な要因ですとかあれば教えてください。壁面緑化は増えているのですけれども、こちらの要因が何か分析されているようでしたら教えてください。そちらからお願いいたします。","respondent":"大友公園課長","answer":"みどりの面積というところなのですけれども、緑被地ということでまとめた形の面積につきましては、区内３４５.９haという形になってあります。壁面緑化が増えているという理由です。少々お待ちください。","voiceIndex":56,"id":"exchange-025"},{"speaker":"横山委員","kind":"質問・要望","question":"少し昔の話になるのですけれども、昭和５０年代に都のほうで、計画でみどり率が３０％というようなお話があるということがあったかと思いますが、それを品川区のほうでは都市部なので２５％ということで、目指すべき将来的なみどり率が２５％ということで現在やっているのかなと思うのですけれども、当時のことを私はよく分かりませんので、どうしてその３０％だったのかというところ。","respondent":"大友公園課長","answer":"今のみどりの基本計画・行動計画でもそれを踏襲しているという形なのですけれども、東京都は当時みどり率、これを何か３０％を目標としておりました。それに合わせて品川区も３０％にするかどうかというような議論が当時あったものと認識しております。","voiceIndex":58,"id":"exchange-026"},{"speaker":"横山委員","kind":"意見","question":"１点だけ分からなかったところがあるので、もう一度ご答弁をお願いしたいのですけれども、接道部の可能性が高い箇所と、可能性が低い箇所というのが、どういった状況なのかというそのイメージのところもお聞かせいただけますか。","respondent":"大友公園課長","answer":"緑化の可能性の低い接道部につきましては、駐車場の出入り口に利用しているであったり、または建物の擁壁だったり、壁を取り壊さないと接道部ができないような場所を言っているです。","voiceIndex":60,"id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば他区の事例なのですけれども、千代田区とかはヒートアイランドの部分の冷却になるかもしれないですけれども、菜園の助成を令和７年度から増やしていたりですとか、そういったところもありますので、他区の事例等を研究・注視していただきながら、どういったことが品川区でこれからやっていけるのかということをぜひ進めていっていただきたいと思いますので、その部分について一言お願いします。","respondent":"大友公園課長","answer":"現在の施策にとどまることなく、新たな施策事業というところについて、他区の事例等も踏まえ研究し、検討してまいりたいと考えています。","voiceIndex":62,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"都立公園や林試の森とかそういうのは除外するという見方なのですが、要は区としての計画はいろいろ先ほど来質疑があって、粛々と進めていただいていると思うのですが、東京都という話もありましたけれども、隣接する区との連携によってこの率を上げていくとか整備のあり方という考え方・捉え方というのは、どのように今までやってきたのか。","respondent":"大友公園課長","answer":"こちらについて水とみどり、水も含めてなのですけれども、近隣自治体との方針というものを図りながら、ネットワーク整備方針を検討していくです。","voiceIndex":64,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"計画とか考え方とかは当然あると。ただ実態として具体的に目黒区との区境とか、大田区境というと大通りになるのかもしれないけれども、目黒区境などは比較的どちらかの区道がつながっていると思うのですけれども、そういったところのみどりを考えていくときに、こういう計画に基づいて実施された具体的な場所というのはあるのでしょうか。","respondent":"大友公園課長","answer":"整備等々もこのみどりの軸の連携の一つになるのかなと計画しています。","voiceIndex":66,"id":"exchange-030"}]},{"id":"topic-04","title":"五反田～天王洲、舟旅通勤","agenda":"五反田～天王洲、舟旅通勤","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点伺いたいのは、通勤ということで、通勤というのは自宅から職場に恐らく行くことだと思うのですけれども、恐らく区も、また多くの会社も、最短距離しか交通費が出なくて、自分としてはここを行きたいのだと思っても、行くのは勝手だけれども会社としてはこの道の分しか出しませんというような、ほとんどそうだろうなと思うのです。このルートは通勤で認めてもらえるのですか。お答えください。","respondent":"関根河川下水道課長","answer":"そういった使い方等も考えられるのではないかと考えているところです。区といたしましても、水辺利活用推進計画において、水辺のにぎわい創出につきましては積極的に取り組んでいくこととしておりますので、そのような形での利用の方法もあるのかなと認識しています。","voiceIndex":72,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"水辺のにぎわい創出については、品川区も上位計画を持っているわけですけれども、なぜそのようなことを聞いたかというと、やはり通勤というのは、通勤で使っても構わないのですけれども、その先に狙いがあるのではないかと私は思っているのです。では、その先の狙いというのは何なのか伺いたいと思います。そうではないのですか。伺います。","respondent":"関根河川下水道課長","answer":"今ご質問いただきました点で、本当に通勤だけなのかというところですけれども、こちらは令和４年度に社会実験として実施をしております。","voiceIndex":74,"id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"特段再開発と絡めたものではないとおっしゃいますけれども、将来的な再開発の動きに合わせたものだと私は思っています。屋根もついていない海音という船がありますけれども、私はそのようなことをするのだったら、もっと観光に特化してつまみとビールでも出しながら楽しくとか、よほどそちらのほうが面白いのではないかと思うけれども、やはり通勤だと言い切るところがうさんくさいなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは屋根がないということで、これは雨のときには雨天中止ということなのかということを伺いたいのと、あと、この社会実験では通勤が一番利用が見込めそうだということでしたけれども、実際今見込んでいる利用量というか人数というのはどのくらいなのか伺いたいと思います。五反田と天王洲を行き来する人ということになると思うのですけれども、これが実際に成り立つのか、そこをお伺いしたいと思います。","respondent":"関根河川下水道課長","answer":"３点目、事業として成り立つのかどうかですけれども、こちらも直接的に区として成り立つ、成り立たないということを述べる立場ではございませんけれども、区としても水辺利活用推進計画に基づきまして、区としてできることは取り組んでいくということで考えてあります。","voiceIndex":77,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として実施するものではないということなので詳しく分かりませんけれども、そうですか。では今後見守っていきたいと思いますけれども、区としても船着場の整備とかはしているわけですから、関わっているということはあると思いますので、見ていっていただきたいと思います。それと、私も最後に、これを再開発につなげないようにということは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-035"},{"speaker":"横山委員","kind":"確認","question":"私のほうからは数点確認したいのですけれども、１点、まず区としては積極的な広報等の支援を行うということが書いてあるのですけれども、広報については都のほうとどのように連携をして、区としてどのようなことを行っていくのか、具体的に教えていただけたらと考えています。","respondent":"関根河川下水道課長","answer":"東京都の広報についてですけれども、申し訳ありません、現時点で東京都が具体的に、例えば都営線にポスターをつけるとか、そういった情報は把握できてございませんけれども。","voiceIndex":80,"id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"こちらは５月１４日から運航開始ということなのですけれども、終了の予定はいつ頃になっているのでしょうか。特にそういったものは、終了という期間の定めがないようなものなのか、その辺り、期間についてもし何か分かりましたら教えてください。","respondent":"関根河川下水道課長","answer":"それから３点目、五反田～天王洲だけではなく、例えばお台場等へちょっと足を延ばすといったことのイメージですけれども、この五反田、それから今回天王洲、区の船着場、東品川の船着場ですが、この岸にシェアサイクルポートもありますし、またこの舟運自体も。","voiceIndex":82,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"以前質問させていただいたのですけれども、乗換案内のアプリに船の航路というのが載ってくるのかどうかというところもすごく広報としても重要かと思っておりまして、例えば時間がかかってしまったりとか、料金も高いけれども、そういった選択肢の一つとして、乗換案内のアプリですとかそういったところにもぜひ積極的に情報共有を行っていただきたいと思っているのですけれども。","respondent":"関根河川下水道課長、大友公園課長","answer":"ほかにいろいろ連携して、お台場からといったところにつきましても、いろいろともちろん通勤もそうですし、通勤以外のところも少し含めて幅広く使っていただけるような取組みにつきましては、検討を進めてまいりたいと考えています。みどりの実態調査の結果について、先ほど横山委員から説明を求められた件で、みどりの面積について確認が取れましたので、ご説明をさせていただきたいと思います。申し訳ありませんでした。","voiceIndex":84,"id":"exchange-038"},{"speaker":"つる委員","kind":"意見","question":"先ほど質疑がありましたけれども、東京都の事業ということを含めて、要は品川区の取組状況というのは令和６年度、令和７年度と書いてありますが、区への経済効果というところはどのように見立てがあったのか、今どのように捉えているのか。年間何組とかという点はあるかもしれませんけれども、そういう可能性という部分ではどうなのか。","respondent":"関根河川下水道課長","answer":"現時点で具体的に何かこう決まっているものはありませんけれども、区としても水辺のにぎわい創出に向けて連携できるものがあれば、そうした話を地域も含めて進めていきたいと考えています。","voiceIndex":88,"id":"exchange-039"},{"speaker":"つる委員","kind":"意見","question":"その動きがどうなのかなというのが少し気になるのですけれども、将来的にはそういう夏の風物詩、今舟運関係でも既にやっていただいているのはあるのですけれども、そういったところのソフト面のものでというところでは、可能性が広がるのかなと思いますので、これは別にあえてではなく、もし何かあればご答弁いただければと思います。","respondent":"関根河川下水道課長","answer":"いろいろとありがとうあります。繰り返しなってしまいますが、具体的には水辺利活用推進計画も動き出したところですが、ソフトの充実というのが非常に重要な観点かなと考えていますので、区としても今後、取組の検討ですとか地域の取組支援等を進めてまいりたいと考えています。","voiceIndex":90,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7039#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":35838,"voices":96}},{"id":"r07-20250512-9","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"文教委員会","time":"午後 １時００分～午後 ４時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度学級編制","agenda":"令和７年度学級編制","exchanges":[{"speaker":"西村委員","kind":"意見","question":"例えば、特別支援の教室を普通教室に活用しなければならなくなったり、フリースペースのような形で廊下をパーティションで区切って、そこを活用するなど、学校の中でそういった措置が必要になっている事例があれば、お聞かせいただければと思います。","respondent":"石井学務課長","answer":"具体的にどこの学校でというところまでは、すみません、私はまだ把握し切れていないところなのですけれども、確かに委員がおっしゃるとおり、例えば特別教室を普通教室に変更したりとか、フリースペースの部分を教室に変更したりとか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"以前の委員会のご報告の中に、城南小と城南第二の学区域の変更というのがありましたが、そのことは、今回はここには反映されていないのか、変更後のことも反映されての今回の結果なのか、そこを確認させていただきたいと思います。","respondent":"石井学務課長","answer":"学区域の変更につきましては、令和８年４月１日入学からとなっております。今回については、令和７年４月１日入学者までですので、現状、反映されていない状況の一覧となっています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"意見","question":"分かりました。今後、城南小学校・城南第二小学校に限らずですけれども、その辺の柔軟な対応といいますか、先も見越した中での対応とか、現状においての対応というのは、ぜひ柔軟にご対応いただけるように、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"その点で、特に浜川小学校などは、５クラスでもういっぱいかと。鈴ケ森のほうはまだ少しあるかもしれませんけれども、その辺りの想定と今後について、先ほど他の委員からありましたけれども、教室の対応については、現時点のことで結構ですので、どのようにお考えになっているかというのを、まずお願いします。","respondent":"石井学務課長","answer":"例えば今、学校の改修や改築ですとか、そういった工事をするときの設計時のプロポーザルも、教室が転用できるような形で提案していただいているということであって、今後の就学人口の増に関しては、適切に対応してまいりたいと考えているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"新規に改築するところはそうなのですけれども、５年とか６年かかるということは、これから数年後に入ってくる方はどうか。特別支援学級のほうなのですけれども、１クラスの標準、文科省の標準は８人と伺っているのですが、これを見ると、２４人になっていないけれども３クラスにしていると。柔軟に対応できるということは、よろしいかと思うのですけれども、その辺の対応はどのようにされているのでしょうか。","respondent":"石井学務課長","answer":"特別支援学級については、８人で１学級ということで、１６人で２学級になるのですけれども、３学級にするためには１７人を超える形にならなければならないので、現行は特段、柔軟な対応ということではなく、通常の恒例どおりの対応という形でやってあります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"つまり、３２人に達していないけれども４クラスです。ぎりぎり３２人にならなければ駄目だということではなく、その辺の対応をしていただくのはありがたいので、逆に言うと、学校のほうから、１クラス増やして、１クラスの人数を減らして、指導しやすいようにという要望を出せるような状況があるのかというところで、その辺の柔軟な対応はどのようにしているのかというところを教えてください。","respondent":"石井学務課長","answer":"学校から、例えばより丁寧な対応をしたいということで、一定程度柔軟な要望があった場合については、もちろんこれは加配教員の関係も出てくると思いますので、その辺り、要望を受けつつも、法令にのっとって適切に対応できるような形で進めていきたいと考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話あったように、学校側が一番、どういうお子さんが入ってくるか分かっていらっしゃると思うので、そういったリクエストにはできるだけ応えていただいて、東京都の加配という関係が出てきてしまうのですけれども、そこは区として加配の形をつくるような状況、ぎりぎり３２だから４クラスとかではなくて、いろいろ細かいルールがあるのだと思うのですが、置いておいて。","respondent":"石井学務課長","answer":"もちろん、いろいろルールがある中でやっていきながらも、特別支援学級などのお子さんに対してきめ細やかな教育ができるような形で、そこはきちんと現場と話し合いながら、また、東京都とも適宜相談していきながらになってくるとは思いますけれども。","voiceIndex":18,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"情報を適宜、様々集めながら、新しい学校をつくるときは転用できるような形で設計会社にお願いしていると思うのですけれども、そこの情報、例えばどこに新築マンションができますという情報は、教育委員会としてどこから取っているのか、事業者にお願いをして、何かそういう情報収集をしているのか、それとも品川区のいわゆる民間の建築確認機関とか、そういうところに集まってくるものを聞いて。","respondent":"石井学務課長","answer":"就学人口を推計するに当たっては、当然、最新の人口推計を使うのですけれども、マンションの建築計画に関しましては、都市環境部ですとか、そういったところから、大型マンションの建築の予定を照会したりとか、そういったところで一定程度。","voiceIndex":21,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"民間の事業者に人口動向の推計はお願いしていると。区役所内のそういったところの計画等の情報収集をしていると。それと、先ほどありましたけれども、そういったことを、先ほどご努力としてやられている、情報収集している中で、今のこういうやりくりというか、数の中で、大体それは想定内に収まっているのか、想定外のことも起こっているのか、その辺りを最後に教えてください。","respondent":"石井学務課長","answer":"これが完全に想定内かと言われますと、当然、城南小の段階では、当時の想定を超えるような形で入ってきているということで、想定外もあり得るということは、常に肝に銘じておかなければならないと考えております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からもご質問します。再開発で、マンション建設に伴う児童増加に対する対策について、今のご質疑にもあったのですけれども、改めてお伺いします。そういった形で連携を事前にしているということなのですけれども、有効な話合いが行われて、予定の教室数を超えて児童が増えて、逼迫するようなことがない状況が一つずつ確認できているのかどうかというところ。","respondent":"石井学務課長","answer":"例えばマンションができることによって、周辺の教育環境に影響があるというところについては、懸念を示すことが可能なのですけれども、基本的には、教室数が足りなくなるから開発規模を下げてくれとか。","voiceIndex":26,"id":"exchange-010"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それ以外にも、別室指導のお部屋とか、いろいろ、既に部屋をつくったり、活用しているところの中で、就学人口が増えていくことで、対応し切れるのかというところの不安の声があったのですけれども、この個別事案に関して、これまでの経緯とか完成後の見通しなどが、それでも大丈夫だとかという推計が既にあるようでしたら教えていただきたいのですが、いかがでしょうか。","respondent":"石井学務課長","answer":"今の日野学園個別事例については、申し訳ございません、今、手元に資料がないので、この場でご説明することはできないのですけれども、ただ、今そういった声があるということについては受け止めた上で、そういった不安が生じないように対応してまいりたいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご確認いただきたいです。その中で、保護者の方からの声なのですけれども、この再開発は学校の隣地なのです。それから、こういった形でマンションが建ってくると、保護者の方々から不安になったりするというところでいろいろな声が上がってきてありますので、周辺住民や保護者の方々には、大丈夫だというところの分かりやすい説明をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"その辺を、地元の子どもや親御さんの選択だからとして、地元公立中学校ではなくて私立が選ばれることに対して、そのまま何もせず容認をしてしまうのか、そうではなく、私立に行かないで、ぜひ我が地元、品川区立中学校、義務教育学校に入ってほしいと、さらに教育の質を高めるという取組について、こういう数字の傾向を見てどのようにお感じになっていらっしゃるのかというところをお伺いしたいと思います。","respondent":"石井学務課長","answer":"そういう意味では、私立に行くことそのものを否定するということではないですけれども、もともと学校選択制というのも、選ばれるための各学校の努力を促すための取組ですので、きちんと魅力があって選ばれる品川区立の学校になるため。","voiceIndex":35,"id":"exchange-013"},{"speaker":"山本副委員長","kind":"質問","question":"私からも質問します。学校選択の中で、選択して希望が通らなかった児童・生徒はどの程度いるのかということと、理由はどのようなものかということを教えてください。これまでの傾向と、過去と比較した今年度の特徴があれば、併せて教えてください。","respondent":"石井学務課長","answer":"特に例えば兄弟枠で、本当だったら入れるところを入れなかったことが、令和７年度は１名出てきております。令和６年度は兄弟枠で入学できない方はいらっしゃらなかったのですけれども、令和７年度は１校、そういったところが発生しています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"山本副委員長","kind":"質問・要望","question":"兄弟枠でも１名入れない状況の学校があるということで、承知しました。ほかに、全体的な数字の割合とか、把握できるものがあれば教えていただきたいのですけれども、いかがでしょうか。例えば、全体で言うと何割ぐらいが入っていないとか、もしくは、ある学校ではこうだという形でのご説明がもしいただけるようだったら、お願いしてもよろしいでしょうか。","respondent":"石井学務課長","answer":"中学校に関しましては、申請者における入学可能者数については、大体６０％台で推移しているのですけれども、令和７年度に関しては６８.１％という形で、ほぼ似通った数字で推移しています。","voiceIndex":41,"id":"exchange-015"},{"speaker":"山本副委員長","kind":"意見","question":"先ほどの何かのご答弁でもありましたけれども、学校の教室には限りがありますし、全ての方の要求に応えるというのはかなり難しいということは理解しておりますけれども、やむを得ないと思うのですが、品川区で学校ごとにそれぞれ特色のある取組などが進められていて、それぞれのところに行きたいという子どもたちが、できるだけご希望がかなって行けるようなことになるように工夫等をして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-016"}]},{"id":"topic-02","title":"区立学校におけるいじめの重大事態の調査結果","agenda":"区立学校におけるいじめの重大事態の調査結果","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"分からないことがあるので、まず全体について伺いたいと思います。まとめて伺いますが、２つの事案で、保護者の方は２名です。「除去することが必要である」ということなのでしょうか。これを当該の保護者の方が読んだときに、幾つかの方の目を通して、特に教育関係の方、弁護士等が書いたものを、どこかの段階で直さなかったのでしょうかという、少し不信感を覚えるのではないか。","respondent":"丸谷教育総合支援センター長","answer":"それは再発防止に努めるためにです。そうした趣旨を保護者に説明いたしまして、そういうことであればということでご納得いただき、公表を希望というか、公表について許諾をいただいたという流れです。","voiceIndex":48,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"大丈夫なのだろうかと。先ほどご説明ありましたけれども、２つ目の事案の１５ページの発達支持的生徒指導、これも本委員会における答申において複数回提案していると。今、取り留めもなくいろいろなことを申し上げましたが、特に最後のところですけれども、今、教育委員会として、そういったことができていない、複数回、何度も提案を受けているということですが、そこについてのお考えを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういった視点を持ちながら、学校経営、学級経営を行っていきましょうということを働きかけて、繰り返し伝えているところです。今後この成果が表れるように、我々もしっかりと学校の取組を注視して見ていきたい、また支援していきたいと考えております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"１番目の事案の１３ページなのですけれども、提言のところで、保護者は教育の専門家ではない。中段ぐらいです。学校において積極的に状況の確認・整理をし、保護者らの不安等を除去することが必要と、最後の結論のところにもあるのです。保護者らは専門家ではない。先ほどもありましたけれども、私にはそのように読めてしまったので、そこについての見解を最後に伺って、終わりにしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味では、教育委員会がしっかりバックアップをして、学校がしっかり対応できるような取組、仕組みづくりというものを昨年度から進めておりまして、最終的には教育委員会が責任を持って対応していくということが求められていると捉えております。","voiceIndex":52,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"最後と言いましたが、その前に２つお聞きすると言ったのが、１つ質問し忘れてしまったので、それも伺います。今のお話を伺っていると、報告の途中でも出てきますけれども、その報告書自体が事実関係と学校の判断の区別ができていない、そのこともしっかり是正すべきであるという提言もありました。最後に、さっき聞き忘れたのが、１番目の報告書の１４ページのところ。","respondent":"丸谷教育総合支援センター長","answer":"本事案について背景を探ると、部活動の中の人間関係というものも、学校へのヒアリング等で分かってきたところではあるのですけれども、本件いじめとして認知をしたものと直接的な関係はないということで、ここには全体を通しての網羅的な記載はされていないです。","voiceIndex":54,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"あくつ委員の質問の冒頭というか、前半のところと共通する問題意識を持っておりまして、そのことをお伝えしたいと思います。これは公表されているものなので、広く多くの方が見る。そういう恐らく違和感もあったから、ご説明の中では被害生徒Ｖということで、枕言葉というか、名前を入れていただいたのだと思うのですが、そういう意味でも、僕はここも訂正すべきだと思うのですが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"言い回しも含めてですけれども、今ご指摘いただいた点につきましては、品川区いじめ対策委員会にもお伝えさせていただき、今後、答申として上がってくるものについては、検討いただくように申入れをしたいと考えます。","voiceIndex":57,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ申入れをしていただきたいと思います。同時に、最初、こういう表記を見た、報告を受けた教育委員会として、専門的表現だから致し方ないと思ったのか、そこはもっと丁寧な表現で書くべきではないかと思ったのか、その受け止めはどうだったのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"こうした細かな表現についてまでは十分に見切れていなかったかなということが、今ご指摘をいただきまして分かりました。その点も含めて今後、受け取る際には、しっかりと被害側に寄り添った表記・表現になっているかというところも、併せて確認していきたいと思います。","voiceIndex":59,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったことを改善するためにも、しっかりこういう定義もして、また品川区教育委員会や、あと区長部局にもいじめ対策の窓口をつくっていただいたりとか、そういう流れがある中でこそ、私はこういうＶという言葉ではなくて、きちんと、いじめられてしまった子どもにさらに寄り添って表現していただかないと、客観的に見た人から、そこまでの対策をきちんと本当に取っているのか、いじめ隠蔽対策。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"西村委員","kind":"質問・要望","question":"様々な要因が重なり合っておりますし、文脈から読み取るしかないのですけれども、一体どのような体制が望ましかったのか、これからの取組も含めてお考えをお聞かせいただきたいと思うのが１点。今申し上げた第三者による介入というところと、私はつながってくるかなと思っているのですが、１点伺いたいのが教員の負担について。","respondent":"丸谷教育総合支援センター長","answer":"その後、この学校では、毎週いじめ対策委員会を開いて、かなり丁寧に行っている、それぞれの事案について丁寧に対応策を考えて検討しているという報告を受けておりますので、今後誰かに頼ったような対応ではなくて、組織として行うことが大切であるということを。","voiceIndex":63,"id":"exchange-024"},{"speaker":"西村委員","kind":"質問・要望","question":"こういった担任と保護者の間、もしくは学校と保護者の間での関係性を良好に築くことができていなくて、学校側の対応が保護者側に伝わっていないこともあるのではないかと思っておりまして、少しお話が飛躍してしまうのですが、先日の立川市で保護者の方が学校側に来て、暴力を振るったということもあったので、そういったことを受けて、教育委員会としてのお考えがあれば、あと。","respondent":"丸谷教育総合支援センター長","answer":"それを未然に防ぐために、４月当初の保護者会等を通じて、学校のいじめ対応方針についてしっかり伝えて、何か子ども同士でトラブルがあったときの対応について、まずは事実関係をしっかりと把握することですとか、保護者と連携をしていくことですとか。","voiceIndex":65,"id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"確認","question":"１個目の事案の１２ページで、疑いの段階から事実確認をという点と、もう一つは次のパラグラフ、イの途中ぐらいで、責任を背負い過ぎたというところと、それから、対応チームをつくったほうがという２点に関しては、かねがね言われていたことでした。","respondent":"丸谷教育総合支援センター長","answer":"いじめの疑いの段階からしっかり確認して対応していく点、これは早期発見、早期対応につながるものだと考えております。","voiceIndex":68,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"教育委員会として、現場のバックアップをしているというところは理解しました。常にこれからも密接に連絡を取っていただいて、先ほど言ったように月明けの報告があって、それを単に受けるだけではなくて、そこからしっかりとアドバイスということをしていただければと思います。先ほどから研修の話が出ています。これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"},{"speaker":"せらく委員","kind":"質問・要望","question":"区教育委員会として、いじめの再発防止のために、公表を後押しするようなものと捉えてもよいでしょうか。ガイドラインに関係者の意向確認というところがありました。被害者側とその他の関係児童等とございまして、これまで非公表だった事案で、被害者側は公表していいという意向だったけれども、そのほかのところで公表の許可が得られなかった、そのような状況となったことはありますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味で、後押しといいますか、趣旨をきちんと説明して、確認を取っているです。今後、複数事案がまだ残っていますので、こうした公表について意向の確認をしっかり取りながら、被害児童・生徒に寄り添った対応ができるように努めてまいりたいと思います。","voiceIndex":72,"id":"exchange-028"},{"speaker":"せらく委員","kind":"質問・要望","question":"被害児童・生徒に寄り添ってというところなのですけれども、これまで非公表というものが多くなっております。先ほどあくつ委員がこの内容を皆さんに見ていただきたい、納得できないからというところがあったのかという質問をされていたと思うのですけれども、私は逆なのかなと思っていまして、非公表となっている方が、内容に納得できないから公表したくないのかなと考えたところでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-029"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも質問します。３つ目なのですけれども、せらく委員のご質問にもありましたが、調査を受けた被害児童・生徒の保護者の方々や、被害生徒・児童の方々に納得度の確認、調査に対する満足度の確認というのはやっているのでしょうか。例えば時間がかかってしまっているというところ、最初に申し上げたようなところに対して、被害児童・生徒の保護者の方が大きく不満に思っているのではないでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"おっしゃるとおり、子どもたちはこの１年の中でも成長していくわけですので、どうにか調査の期間を短くできないかという課題感を持ちながら、対策委員会の中でも話題にはなっています。","voiceIndex":76,"id":"exchange-030"},{"speaker":"山本副委員長","kind":"質問・要望","question":"時間がかかるというところについてのご答弁なのですけれども、おっしゃるとおり、いじめの判断をしていくに当たって、このように複雑な事案で、一つ一つ確認していかなければいけないというところでの時間がかかること、それから、最終答申案をつくるので文章を整えるというところに時間がかかるというのも、かかってしまう理由は分かるのですが、一方で、繰り返しになりますが。","respondent":"丸谷教育総合支援センター長","answer":"こうした国が示しているものに沿って対応するということが、一つ大事かなと思いますので、今後も引き続き、そういったご意見もしっかり受け止めながら、対応は進めていきたいと思います。","voiceIndex":78,"id":"exchange-031"},{"speaker":"山本副委員長","kind":"質問・要望","question":"いじめの重大事案に遭われた児童・生徒や保護者の方々の気持ちにはこのようなところがあるということを、改めて理解していただきたいのと、それに、公表された２事案の中にも出てきていますけれども、信頼関係とか、より被害者の皆様に寄り添う気持ちとかというのがすごく大事になってくるのかなというところで、そういった一つ一つのところを丁寧にやっていただきたいというのは、改めてご要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-032"}]},{"id":"topic-03","title":"朝の児童の居場所確保事業試行実施","agenda":"朝の児童の居場所確保事業試行実施","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"まとめて端的に質問いたします。間もなく試行が開始されるということで、もう目の前に来ているところなのですけれども、まず、ここに書いてある４番目の保護者への周知・利用登録というところなのですが、もうこの利用登録は終わったのでしょうかというところが１点です。適切に周知する必要があると思うのですが、それはどのような仕組みを考えられているのか教えてください。","respondent":"三輪子ども育成課長","answer":"現時点で予定していますのが、源氏前小学校が図書室、戸越小学校が多目的室、豊葉の杜学園が和室を予定しています。最後に、台風等により受入れができないということに関しましては、事前に分かり次第、保護者に対してメール等で周知を予定しています。","voiceIndex":90,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点目が登録は終わったというところで、どれぐらいの申請を受けて登録をしたのか、各学校について教えていただきたいということ。それと２点目が、今お伺いすると、体育館ではない、いわゆるお部屋を用意するということになったようですけれども、たしか以前体育館だと伺っていたような気がするのですが、こうなった経緯みたいなもの、そもそもそういう考えだったのかというところも含めて教えてください。","respondent":"三輪子ども育成課長","answer":"ですが、各学校との調整の中で、適切な場所を設定しようというところで、校長先生のヒアリング等を通じて設定をしています。保護者への案内につきましては、保護者への一斉通知メールを今考えているです。詳細については今検討中ですので、よろしくお願いいたします。","voiceIndex":92,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"最後に１点だけ聞かせてください。最後に朝食支援のところなのですけれども、今後実施する需要調査も踏まえ、試行開始を予定という言い回しになっているのですが、端的に言うと、朝の居場所に来られる子どもたちにアンケート調査をするということなのですか。","respondent":"三輪子ども育成課長","answer":"需要調査につきましては、各学校、試行３校において、保護者向けに朝食支援を希望するかという調査をしたいと考えています。","voiceIndex":94,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、これは朝の児童の居場所を使っている子どもやそのご家庭にということではなくて、今回試行する３校全体で需要を調査するという認識でいいでしょうか。","respondent":"三輪子ども育成課長","answer":"委員おっしゃるとおり、今使っていない方についても、朝食支援が始まった段階で使うということもあり得るかなと思いますので、幅広の調査をする必要があるかなと考えております。","voiceIndex":96,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"目的のところなのですが、２つの文章がありまして、１つ目は、「朝の小１の壁」に重要な課題があるという表現。そういうところの需要があるので、朝の居場所ということなのですが、最初の「朝の小１の壁」というのは、朝の居場所対策をすることの解決にどう結びつくか、すみません、予算委員会等々で説明あったのかもしれないですが、改めてお伺いしたいと思います。","respondent":"三輪子ども育成課長","answer":"実際、校門前に立たれてしまっていると、安全・安心の確保の観点から、少し課題があるかなというところがありますので、本事業を実施するです。","voiceIndex":99,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"分かりました。対象校が源氏前小学校と戸越小学校と豊葉の杜学園ということで、まずは小学校１年生を含むそういう子どもの居場所の確保ということですが、義務教育学校も対象になっています。中学校へのこういう対応を今後考えていらっしゃるのかどうかをお伺いしたいと思います。","respondent":"三輪子ども育成課長","answer":"現段階で中学校というところまでは、検討しているところではございません。","voiceIndex":101,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"むしろそういう子どもが多いということは、居場所での過ごし方ももうひと工夫必要になってくるし、また、受け入れてくださる方の負担といいますか、対応のメニューをもう少し増やしていくことも、今後必要になってくるかと思われるのですが、その辺の見通しはいかがでしょうか。","respondent":"三輪子ども育成課長","answer":"実際に居場所の中で自主学習ができない子どもたちをどこまで指導できるかというところも、試行の中で検証していくことになると思うのですが、あまり多くの人数を配置することは現実的には難しいというところがありますので。","voiceIndex":103,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"最初の確認いたしました「小１の壁」、保育園には親御さんがお送りして、預かっていた子どもが、小学生になった瞬間に自ら学校に行くわけです。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-040"},{"speaker":"西村委員","kind":"質問","question":"前もご説明いただいていたら、繰り返して申し訳ないのですが、見守り員の委託先がシルバー人材センターなのか、どこなのかを改めて伺いたいのと、あと、すまいるスクールの職員もここにフォローで入ってくるのか、どれぐらい入ってこられるのか、改めて伺えればと思います。","respondent":"三輪子ども育成課長","answer":"ただ、本課のほうに朝の居場所の担当で新しく配置されている職員がおりますので、何か緊急事態等あれば対応できるような体制を取っているです。","voiceIndex":107,"id":"exchange-041"},{"speaker":"西村委員","kind":"質問・要望","question":"理解しました。これは需要だけではなくて、その際に実態調査も行っていただきたいと要望させていただきたいです。そもそも食べていないお子さんに関しては、朝ご飯を食べる習慣をつけるということでもいいのですけれども、子どもが毎日食べられていない理由と原因の改善、また、提供するものの栄養価なども考えながら取り組む必要があると思うのですが、その辺りのお考えを伺えればと思います。","respondent":"三輪子ども育成課長","answer":"需要調査の中身につきましては、まさに今、これから考えていくですので、委員のご意見も参考に、おっしゃるとおり、どういったものが原因になってくるかというところは、我々としても把握した上で実施する必要があるかなと考えておりますので。","voiceIndex":109,"id":"exchange-042"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません、もう１点だけ要望させていただきたいのですが、今回の朝の居場所に関しては、静かに学習などをしながら過ごしてくださいと書かれておりますけれども、孤食だったり、食べないということが課題の子どもたちが集まるならば、朝を楽しく過ごす習慣だったり、黙食しながら静かに早く食べるようにという指導ではなくて。","respondent":"三輪子ども育成課長","answer":"教育の分野のところまでのお話は、すみません、私のほうからはお答えすることが難しいです。","voiceIndex":111,"id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問","question":"それはつまり、全校展開するわけなので、全校展開するときに、さらに３掛ける３０校ではないですけれども、１００人以上必要になってくるので、その点について見通しみたいなのはいかがでしょうかというのが一つ。もう一つは、７時半に校門を開けます。ただ、お子さんたちが７時半に来るとは限らない部分もあるので、どのような形で事業計画を立てているのかお尋ねします。","respondent":"三輪子ども育成課長","answer":"全校展開に向けてなのですけれども、今回の集まり具合を見ると、シルバー人材センター単体で確保するというのはなかなか難しいのかなというところもありますので、どういった方策があるかというのは。","voiceIndex":115,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この３校の試行で課題が見えてくると思いますので、委託する方の確保も含めて、早いうちに何とか対応していただきたいと思います。校門の件は承知しました。閉まっていて、見守り員の方が開けるということで安全が確保されるということで、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"提案","question":"大丈夫なのかというところが１点。体育館や図書館等と書いてあるのです。それからもう一つ、うちの会派から言われていて、これも聞くのを忘れていて申し訳なかったのですが、この事業を一般質問等でご紹介するときに、先行事例だった豊中市では、小１のときにはまず保護者が最初、校門まで連れてきてくださいというつくりになっていたのですが、今回はそういう縛りはかけないということでいいのでしょうか。","respondent":"三輪子ども育成課長","answer":"２点目のご質問が、しっかり聞き取れなかった部分があって申し訳なかったのですけれども、家で食べられないお子様の対応については、いろいろなご意見は恐らくあるかと考えています。","voiceIndex":119,"id":"exchange-046"},{"speaker":"山本副委員長","kind":"質問・要望","question":"朝早く来る子どもたちの安心・安全について、７時半という早い時間に学校に来てしまう子どもたちが、実は行っていなかったというところがすごく心配で、これまでもどうするのですかというお話をしていたのですけれども、今回７時半に、区の方が雇われる誘導員の方が旗当番とかで見てくださる。これで認識がよければいいです。違ったらご答弁ください。実態調査をお願いしたいと思っています。","respondent":"三輪子ども育成課長","answer":"朝食のアレルギー対応についてなのですけれども、朝の居場所事業の登録のところで、若干、朝食の支援についても触れておりまして、現段階では、アレルギー食までの対応というのは難しいというところをご了承いただいた上での申込みをしていただいているという状況です。","voiceIndex":122,"id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問・要望","question":"分かりました。１点、トラブルが起こったときとか、２人いて、１人の方が何かその対応をしていると、残りの１人だけだと、その場が対応し切れないとかということももしかしたら出てくるかもしれないなと思います。そういったことも試行の中で検証いただきながら、万全な体制となるように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"確認","question":"私からは１点だけ。待機児童ゼロの状態が継続されているということで、ここ数年間、新しい私立幼稚園の誘致はされないということで来ていると思うのです。これは所管には確認させていただきましたけれども、大井町トラックスができるということも含めて、大井町周辺はどうしても通勤のハブ駅で、非常に需要が大きいということで、突発的に募集をしたということでご説明を受けました。","respondent":"芝野保育入園調整課長","answer":"ご質問の答えは、私立保育園でよろしいですか。","voiceIndex":129,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"足りないところは当然つくるというところで、一つは、先ほど小学校のところでもありましたけれども、情報収集をどれだけきめ細かくできるのかというところにもかかってくるのかなと。かなり待機児童対策でたくさんの保育園を誘致したという中で、いろいろなことが言われている、保護者の方からもいろいろ言われている中で、そういったところへのお考えを最後に伺って、おしまいにしたいと思います。","respondent":"染谷保育施設運営課長","answer":"区立・私立含めまして、保育園の質の部分のお話ですけれども、令和６年の４月にお示しをしております品川区内保育園等あり方基本方針の中で、区立保育園を核とした保育の質の向上についてお示しをさせていただいておりまして、具体的には、例えば公私立の連携をしていく中で。","voiceIndex":133,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"区内全域で４２７人で、その不承諾の子どもの行き場はどうなっているのかというところの確認なのですが、３歳以上だと幼稚園に行く可能性もあるのだと思いますが、ゼロ歳から２歳児までの合計３６６人の子どもは、どういう状況になっているのかを把握されているのかということと、もっと基本的なことは、待機児童と不承諾数との関係性です。","respondent":"芝野保育入園調整課長","answer":"育児休業の延長も、育児休業を引き続き延ばすという形になりますので、行き場がなくなるということではないということですので、トータルで言えば、お困りになっている状態というのは、区内ではないと認識しております。","voiceIndex":136,"id":"exchange-051"}]},{"id":"topic-04","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問・要望","question":"都立の学校だと、学校徴収金すなわち私費会計は、事務取扱規程で学校内に特別の委員会、業者選定委員会をつくるのですが、小・中学校の場合はないのかということと、多くの区内の小・中学校はそうすると、恐らく卒業対策委員というのか、ＰＴＡの方々、関係の方が選定したりしているのですが、その辺り、どうやって卒業アルバムの業者を選定して、最終的にどこと誰が、学校になるのだと思うのですが。","respondent":"舩木庶務課長","answer":"卒業対策委員会が中心になって、この対応に当たっていただいていると思いますけれども、細かい事業者選定に関するところまでは、現時点で情報を持ち合わせてはおりませんので、答弁は省略します。","voiceIndex":143,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問","question":"お答えできる範囲でいただいたので、ありがとうあります。なかなか難しいので、その辺り、今後どのようにしていったらいいのか、現時点でのお考えを伺います。","respondent":"舩木庶務課長","answer":"こうした中で、実際の契約相手方の企業が、さらに印刷の部分だけをどこかに再委託するというところの部分が、事前にしっかりと分かればというか、そこはしっかりといろいろなことを想定して対応していかなければいけないというところはありますので。","voiceIndex":145,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7037#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":59127,"voices":152}}]);
